@media (max-width: 760px) {
  .job-option-fieldset {
    padding: 17px;
    border-radius: 18px;
  }

  .job-budget-options,
  .job-duration-options {
    grid-template-columns: 1fr;
  }

  .project-form .job-option-card {
    min-height: 78px;
    padding: 13px;
  }

  .job-listing-meta {
    gap: 7px;
    margin: 11px 0 13px;
  }

  .job-listing-pill {
    min-height: 30px;
    padding: 6px 9px;
    font-size: 11px;
  }
}

@media (max-width: 390px) {
  .job-listing-meta {
    align-items: stretch;
    flex-direction: column;
  }

  .job-listing-pill {
    width: 100%;
    justify-content: flex-start;
  }
}

