.privacy-erasure-choice-fieldset {
  min-width: 0;
  margin: 0;
  padding: 18px;
  border: 1px solid #d7ddd6;
  border-radius: 17px;
  background: #f8faf7;
}

.privacy-erasure-choice-fieldset legend {
  padding: 0 7px;
  color: #29352d;
  font-size: 13px;
  font-weight: 850;
}

.privacy-erasure-choice-intro {
  margin: 0 0 14px;
  color: #687269;
  font-size: 11px;
  line-height: 1.6;
}

.privacy-erasure-choice-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.privacy-erasure-choice {
  position: relative;
  display: grid !important;
  grid-template-columns: 30px minmax(0, 1fr);
  gap: 11px !important;
