  padding: 15px;
  border: 1px solid #d7ddd6;
  border-radius: 14px;
  background: #fff;
  color: #303a32;
  cursor: pointer;
  transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
}

.privacy-erasure-choice:hover:not(.is-disabled) {
  border-color: #8da393;
  box-shadow: 0 8px 22px rgba(43, 68, 49, 0.08);
}

.privacy-erasure-choice.is-selected {
  border-color: #5f8068;
  background: #eef6f0;
  box-shadow: inset 0 0 0 1px #5f8068;
}

.privacy-erasure-choice.is-danger.is-selected {
  border-color: #a04c45;
  background: #fff2f0;
  box-shadow: inset 0 0 0 1px #a04c45;
}

.privacy-erasure-choice.is-disabled {
  background: #f1f2ef;
  cursor: not-allowed;
  opacity: 0.64;
}

.privacy-erasure-choice input {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
}

.privacy-erasure-choice-mark {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: #e5ece6;
  color: #496050;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.05em;
}

.privacy-erasure-choice.is-danger .privacy-erasure-choice-mark {
  background: #f3e5e3;
  color: #8c443e;
}

.privacy-erasure-choice strong,
.privacy-erasure-choice small {
  display: block;
}

.privacy-erasure-choice strong {
  margin-bottom: 5px;
  color: #29332b;
  font-size: 12px;
}

.privacy-erasure-choice small {
  color: #6d766f;
  font-size: 10px;
  font-weight: 600;
  line-height: 1.55;
  text-align: left;
}

.privacy-erasure-eligibility {
  margin-top: 12px;
  padding: 13px 15px;
  border: 1px solid #dfc985;
  border-radius: 13px;
  background: #fff9e8;
  color: #69561c;
}

.privacy-erasure-eligibility.is-ready {
  border-color: #afd0b5;
