}

.privacy-erasure-eligibility p {
  margin: 0;
  font-size: 10px;
  line-height: 1.6;
}

.privacy-erasure-eligibility ul {
  display: grid;
  gap: 5px;
  margin: 9px 0 0;
  padding-left: 18px;
  font-size: 10px;
  line-height: 1.5;
}

.erasure-blocker-list {
  display: grid !important;
  gap: 8px !important;
  margin: 12px 0 0 !important;
  padding: 0 !important;
  list-style: none !important;
}

.erasure-blocker-list li {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  padding: 10px;
  border: 1px solid rgba(151, 80, 71, 0.2);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.58);
}

.erasure-blocker-list li::before {
  content: none !important;
}

.erasure-blocker-list li > span:last-child {
  min-width: 0;
}

.erasure-blocker-list strong,
.erasure-blocker-list small {
  display: block;
}

.erasure-blocker-list strong {
  margin: 0 0 3px;
  color: inherit;
  font-size: 11px;
