  place-items: center;
  border-radius: 9px;
  background: #f2d9d5;
  color: #7c342e;
  font-size: 11px;
  font-weight: 900;
}

.privacy-eligibility-refresh {
  min-height: 34px;
  margin-top: 12px;
  padding: 7px 11px;
  border: 1px solid currentColor;
  border-radius: 9px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 10px;
  font-weight: 850;
  cursor: pointer;
}

.privacy-eligibility-refresh:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.72);
}

.privacy-eligibility-refresh:disabled {
  cursor: wait;
  opacity: 0.55;
}

.privacy-erasure-requested-action {
  display: grid;
  gap: 4px;
  margin: 14px 0;
  padding: 14px 16px;
  border: 1px solid #bdd2c1;
  border-radius: 14px;
  background: linear-gradient(135deg, #eef7f0, #fbfdfb);
  color: #304c36;
}

.privacy-erasure-requested-action.is-close_account {
  border-color: #dfaaa5;
  background: linear-gradient(135deg, #fff0ee, #fffaf9);
  color: #71342f;
}

.privacy-erasure-requested-action.is-legacy {
  border-color: #dec77e;
