  color: #695719;
}

.privacy-erasure-requested-action.is-confirmation {
  border-color: #a9c7af;
  background: #edf7ef;
}

.privacy-erasure-requested-action > span {
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.privacy-erasure-requested-action > strong {
  font-size: 13px;
}

.privacy-erasure-requested-action > p {
  margin: 0;
  font-size: 10px;
  line-height: 1.55;
}

.erasure-request-selector .privacy-erasure-requested-action {
  max-width: 620px;
  margin-bottom: 0;
}

html[data-theme="dark"] .privacy-erasure-choice-fieldset,
html[data-theme="dark"] .privacy-erasure-choice,
html[data-theme="dark"] .privacy-erasure-requested-action {
  border-color: #3d4940;
