.erasure-actions-menu {
  position: relative;
  z-index: 8;
}

.erasure-actions-menu > summary {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  box-sizing: border-box;
  border: 1px solid #cfd7cf;
  border-radius: 12px;
  background: #fff;
  color: #334038;
  font-size: 18px;
  font-weight: 900;
  letter-spacing: 2px;
  cursor: pointer;
  list-style: none;
}

.erasure-actions-menu > summary::-webkit-details-marker {
  display: none;
}

.erasure-actions-menu[open] > summary {
  border-color: #7f9583;
  box-shadow: 0 0 0 3px rgba(72, 99, 78, 0.1);
}

.erasure-actions-menu > div {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  width: min(310px, calc(100vw - 36px));
  padding: 8px;
  border: 1px solid #d6dbd4;
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 20px 48px rgba(29, 39, 31, 0.18);
}

.erasure-actions-menu button,
.erasure-actions-menu a {
  width: 100%;
  display: grid;
  gap: 3px;
  padding: 12px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #263229;
  font: inherit;
  text-align: left;
  cursor: pointer;
  text-decoration: none;
}

.erasure-actions-menu button:hover:not(:disabled),
.erasure-actions-menu a:hover {
  background: #f1f5f1;
}

.erasure-actions-menu button.is-danger {
  color: #8e3434;
}

.erasure-actions-menu button.is-danger:hover:not(:disabled) {
  background: #fff0ef;
}

.erasure-actions-menu button:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

.erasure-actions-menu button span,
.erasure-actions-menu a span {
  font-size: 14px;
  font-weight: 850;
}

.erasure-actions-menu button small,
.erasure-actions-menu a small {
  color: #788078;
  font-size: 12px;
  line-height: 1.45;
}

