  padding: 12px 13px;
  border: 1px solid #ccd5cc;
  border-radius: 11px;
  background: #fff;
  color: #242c26;
  font: inherit;
  font-size: 14px;
  line-height: 1.55;
  outline: none;
}

.erasure-identity-card textarea,
.erasure-dialog textarea {
  resize: vertical;
}

.erasure-request-selector select:focus,
.erasure-identity-card select:focus,
.erasure-identity-card textarea:focus,
.erasure-owner-approval input:focus,
