  font-size: 13px;
  line-height: 1.6;
}

.stripe-connect-feedback {
  padding: 10px 12px;
  border: 1px solid #d8d8d2;
  border-radius: 11px;
  background: #fff;
}

.stripe-connect-feedback.is-success {
  border-color: #c4ddcd;
  background: #eef8f1;
  color: #176b3a;
}

.stripe-connect-feedback.is-error {
  border-color: #e8c7c0;
  background: #fff1ef;
  color: #98382e;
}

.stripe-connect-feedback.is-info {
  border-color: #d9d7ff;
  background: #f3f2ff;
  color: #5148d8;
}

.stripe-connect-footer {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 17px;
}

.stripe-connect-button {
  flex: 0 0 auto;
  min-height: 43px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  margin: 0;
  padding: 10px 15px;
  border: 1px solid #242421;
  border-radius: 12px;
  background: #191917;
  color: #fff;
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  line-height: 1.2;
  cursor: pointer;
  transition: transform 0.18s, background 0.18s, opacity 0.18s;
