.account-page .chat-page {
  width: min(1080px, calc(100% - 40px));
  margin: 24px auto 48px;
}

.account-page .chat-shell {
  min-height: min(760px, calc(100dvh - 112px));
  border-color: rgba(28, 28, 25, .1);
  border-radius: 20px;
  box-shadow: 0 18px 54px rgba(28, 28, 25, .075);
}

.account-page .chat-header {
  position: relative;
  z-index: 20;
  flex-wrap: nowrap;
  gap: 12px;
  padding: 13px 16px;
  background: rgba(255, 255, 252, .96);
  backdrop-filter: blur(18px);
}

.account-page .chat-back {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 7px 9px;
  border-radius: 10px;
  font-size: 12px;
  font-weight: 760;
}

.account-page .chat-back:hover {
  background: #efefea;
  color: #171715;
}

.account-page .chat-profile-link {
  flex: 1;
  width: auto;
}

.account-page .chat-avatar {
  width: 40px;
  height: 40px;
  flex-basis: 40px;
}

.account-page .chat-person strong {
  font-size: 14px;
}

.account-page .chat-person span {
  margin-top: 1px;
  font-size: 10px;
}

.account-page .chat-header-actions {
  position: relative;
  width: auto;
  margin-left: auto;
}

.chat-actions-menu {
  position: relative;
}

.chat-actions-menu > summary {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border: 1px solid #deded8;
  border-radius: 12px;
  background: #fff;
  color: #343431;
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.chat-actions-menu > summary::-webkit-details-marker,
.chat-message-actions > summary::-webkit-details-marker {
  display: none;
}

.chat-actions-menu > summary:hover,
.chat-actions-menu[open] > summary {
  border-color: #bdbdb6;
  background: #f5f5f1;
}

.chat-actions-menu > summary span {
  letter-spacing: 2px;
  transform: translateY(-2px);
}

.chat-actions-popover {
  position: absolute;
  z-index: 80;
  top: calc(100% + 8px);
  right: 0;
  width: min(340px, calc(100vw - 28px));
  display: grid;
  gap: 3px;
  padding: 7px;
  border: 1px solid #deded8;
  border-radius: 15px;
  background: #fff;
  box-shadow: 0 18px 52px rgba(20, 20, 18, .18);
}

.chat-actions-popover > button,
.chat-actions-popover > a {
  min-width: 0;
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  align-items: center;
  gap: 9px;
  padding: 10px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #242421;
  font: inherit;
  text-align: left;
  text-decoration: none;
  cursor: pointer;
}

.chat-actions-popover > button:hover,
.chat-actions-popover > a:hover {
  background: #f2f2ee;
}

.chat-actions-popover > button:disabled {
  cursor: not-allowed;
  opacity: .46;
}

.chat-actions-popover > button > span:first-child,
.chat-actions-popover > a > span:first-child {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: #ededE8;
  font-size: 13px;
  font-weight: 900;
}

.chat-actions-popover > button > span:last-child,
.chat-actions-popover > a > span:last-child {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.chat-actions-popover b {
  font-size: 12px;
}

.chat-actions-popover small {
  color: #777772;
  font-size: 9px;
  line-height: 1.4;
}

.chat-actions-popover .is-danger {
  color: #92392f;
}

.chat-actions-popover .is-danger > span:first-child {
  background: #fff0ed;
}

.account-page .chat-messages {
  min-height: 390px;
  max-height: 58vh;
  gap: 7px;
  padding: 24px clamp(16px, 4vw, 42px);
  background:
    radial-gradient(circle at 12% 12%, rgba(215, 210, 187, .16), transparent 28%),
    #f7f7f3;
}

.account-page .chat-message {
  position: relative;
  max-width: min(74%, 660px);
  padding: 10px 13px 7px;
  border: 1px solid rgba(30, 30, 27, .07);
  border-radius: 16px;
  box-shadow: 0 2px 8px rgba(20, 20, 18, .035);
}

.account-page .chat-message.is-mine {
  border-color: #1a1a18;
