  line-height: 1.48;
}

.account-page .chat-message time {
  margin-top: 4px;
  font-size: 9px;
}

.chat-message-actions {
  position: absolute;
  top: 5px;
  right: 7px;
  z-index: 4;
}

.chat-message-actions > summary {
  width: 26px;
  height: 22px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  color: #777772;
  font-size: 9px;
  letter-spacing: 1px;
  cursor: pointer;
  list-style: none;
  opacity: 0;
}

.chat-message:hover .chat-message-actions > summary,
.chat-message-actions[open] > summary,
.chat-message-actions > summary:focus-visible {
  background: #efefea;
  opacity: 1;
}

.chat-message-actions > button {
  position: absolute;
  top: 25px;
  right: 0;
  width: max-content;
  padding: 8px 10px;
  border: 1px solid #ddddD6;
  border-radius: 9px;
  background: #fff;
  color: #8e392f;
  font: inherit;
  font-size: 10px;
  font-weight: 780;
  box-shadow: 0 10px 28px rgba(20, 20, 18, .16);
  cursor: pointer;
}

.account-page .chat-form {
  gap: 8px;
  padding: 10px 12px 12px;
  background: #fff;
}

.account-page .chat-form textarea {
  min-height: 44px;
  max-height: 128px;
  padding: 11px 13px;
  border-radius: 13px;
  resize: none;
  font-size: 13px;
}

.account-page .chat-send {
  min-height: 44px;
  padding: 0 16px;
  border-radius: 12px;
  font-size: 12px;
}

.private-work-share {
