  .private-work-album.count-1 button {
    height: min(42vw, 190px);
  }

  .private-work-album.count-1 button {
    height: min(64vw, 330px);
  }

  .private-work-lightbox figcaption {
    padding: 0 64px;
    white-space: normal;
  }
}

/* =========================================================
   ADMIN Ă˘ÂÂ FULL DISPUTE CONTEXT
========================================================= */

.admin-case-context-panel > .dispute-panel-heading {
  align-items: flex-start;
}

.admin-case-context-panel > .dispute-panel-heading p {
  max-width: 650px;
  margin: 7px 0 0;
  color: #74746e;
  font-size: 11px;
  line-height: 1.55;
}

.admin-context-locked,
.admin-context-error,
.admin-context-loading {
  min-width: 0;
  margin-top: 18px;
  padding: 18px;
  border: 1px solid #dfdfd9;
  border-radius: 16px;
  background: #f7f7f3;
}

.admin-context-locked {
  display: flex;
  align-items: center;
  gap: 13px;
}

.admin-context-lock-icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: #191918;
  color: #fff;
  font-size: 20px;
  font-weight: 800;
}

.admin-context-locked strong,
.admin-context-error strong {
  display: block;
  color: #292927;
  font-size: 12px;
}

.admin-context-locked p,
.admin-context-error p {
  margin: 5px 0 0;
  color: #74746e;
  font-size: 10px;
  line-height: 1.55;
}

.admin-context-error {
  border-color: #e1c4c1;
  background: #fff5f3;
}

.admin-context-error strong {
  color: #8a3029;
}

.admin-context-loading {
  color: #676761;
  font-size: 11px;
  font-weight: 700;
  text-align: center;
}

.admin-context-access-note {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px 13px;
  margin: 17px 0 13px;
  padding: 11px 13px;
  border: 1px solid #cad8c9;
  border-radius: 13px;
  background: #f1f7f0;
}

.admin-context-access-note strong {
  flex: 0 0 auto;
  color: #38543a;
  font-size: 10px;
}

.admin-context-access-note span {
  color: #637164;
  font-size: 9px;
  line-height: 1.45;
}

.admin-case-context-grid {
  min-width: 0;
  display: grid;
  gap: 13px;
}

.admin-context-section {
  min-width: 0;
  overflow: hidden;
  border: 1px solid #dfdfda;
  border-radius: 17px;
  background: #fff;
}

.admin-context-section > summary {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.admin-context-section > summary::-webkit-details-marker {
  display: none;
}

.admin-context-section > summary > span:first-child {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.admin-context-section > summary small {
  color: #888882;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.admin-context-section > summary strong {
  color: #292927;
  font-size: 14px;
}

.admin-context-section-body {
  min-width: 0;
  padding: 0 16px 16px;
  border-top: 0;
}

.admin-agreement-history {
  display: grid;
  gap: 12px;
  padding-top: 15px;
}

.admin-agreement-version {
  min-width: 0;
  padding: 15px;
  border: 1px solid #e3e3de;
  border-radius: 14px;
  background: #fafaf7;
}

.admin-agreement-version.is-accepted {
  border-color: #bed0bd;
  background: #f5faf4;
}

.admin-agreement-version-heading {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 13px;
}

.admin-agreement-version-heading > div {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.admin-agreement-version-heading span {
  color: #83837d;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.admin-agreement-version-heading strong {
  color: #333330;
  font-size: 11px;
}

.admin-current-version-badge {
  flex: 0 0 auto;
  padding: 5px 8px;
  border-radius: 999px;
  background: #1c1c1a;
  color: #fff !important;
  font-size: 7px !important;
}

.admin-agreement-version .agreement-details {
  margin: 0;
}

.admin-agreement-acceptance {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 12px;
  margin-top: 12px;
  padding-top: 11px;
  border-top: 0;
  color: #73736d;
  font-size: 8px;
  line-height: 1.45;
}

.admin-full-chat {
  min-width: 0;
  max-height: 620px;
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-top: 15px;
  padding: 4px 4px 4px 0;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.admin-chat-message {
  width: min(82%, 650px);
  min-width: 0;
  padding: 12px 14px;
  border: 1px solid #dfdfda;
  border-radius: 15px 15px 15px 5px;
  background: #f5f5f1;
}

.admin-chat-message.is-contractor {
  align-self: flex-end;
  border-color: #cfcfca;
  border-radius: 15px 15px 5px 15px;
  background: #1e1e1c;
}

.admin-chat-message-meta {
  min-width: 0;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 8px;
  margin-bottom: 6px;
}

.admin-chat-message-meta strong {
  color: #2d2d2a;
  font-size: 9px;
}

.admin-chat-message-meta span,
.admin-chat-message-meta time {
  color: #85857f;
  font-size: 7px;
  font-weight: 700;
}

.admin-chat-message-meta time {
  margin-left: auto;
}

.admin-chat-message p {
  margin: 0;
  color: #41413d;
  font-size: 11px;
  line-height: 1.58;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.admin-chat-message.is-contractor .admin-chat-message-meta strong,
.admin-chat-message.is-contractor p {
  color: #f2f2ee;
}

.admin-chat-message.is-contractor .admin-chat-message-meta span,
.admin-chat-message.is-contractor .admin-chat-message-meta time {
  color: #aaa9a3;
}

html[data-theme="dark"] .admin-case-context-panel > .dispute-panel-heading p,
html[data-theme="dark"] .admin-context-locked p,
html[data-theme="dark"] .admin-context-error p,
html[data-theme="dark"] .admin-context-loading,
html[data-theme="dark"] .admin-agreement-acceptance {
  color: #aaa9a3;
}

html[data-theme="dark"] .admin-context-locked,
html[data-theme="dark"] .admin-context-loading,
html[data-theme="dark"] .admin-context-section,
html[data-theme="dark"] .admin-agreement-version {
  border-color: #393935;
  background: #1b1b19;
}

html[data-theme="dark"] .admin-context-lock-icon,
html[data-theme="dark"] .admin-current-version-badge {
  background: #f1f1ed;
  color: #111 !important;
}

html[data-theme="dark"] .admin-context-locked strong,
html[data-theme="dark"] .admin-context-section > summary strong,
html[data-theme="dark"] .admin-agreement-version-heading strong {
  color: #f0f0ec;
}

html[data-theme="dark"] .admin-context-error {
  border-color: #633d39;
  background: #2b1d1b;
}

html[data-theme="dark"] .admin-context-error strong {
  color: #efaaa3;
}

html[data-theme="dark"] .admin-context-access-note {
  border-color: #345038;
  background: #19251b;
}

html[data-theme="dark"] .admin-context-access-note strong {
  color: #aad0ad;
}

html[data-theme="dark"] .admin-context-access-note span {
  color: #99b09b;
}

html[data-theme="dark"] .admin-context-section-body,
html[data-theme="dark"] .admin-agreement-acceptance {
  border-color: #373733;
}

html[data-theme="dark"] .admin-agreement-version.is-accepted {
  border-color: #3f6042;
  background: #1a291c;
}

html[data-theme="dark"] .admin-chat-message {
  border-color: #3d3d39;
  background: #242422;
}

html[data-theme="dark"] .admin-chat-message-meta strong,
html[data-theme="dark"] .admin-chat-message p {
  color: #eeeeea;
}

html[data-theme="dark"] .admin-chat-message.is-contractor {
  border-color: #d8d8d2;
  background: #e9e9e4;
}

html[data-theme="dark"] .admin-chat-message.is-contractor .admin-chat-message-meta strong,
html[data-theme="dark"] .admin-chat-message.is-contractor p {
  color: #181816;
}

html[data-theme="dark"] .admin-chat-message.is-contractor .admin-chat-message-meta span,
html[data-theme="dark"] .admin-chat-message.is-contractor .admin-chat-message-meta time {
  color: #676762;
}

@media (max-width: 760px) {
  .admin-case-context-panel > .dispute-panel-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-context-access-note {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-chat-message {
    width: 91%;
  }
}

@media (max-width: 480px) {
  .admin-context-locked {
    align-items: flex-start;
  }

  .admin-context-section > summary,
  .admin-context-section-body {
    padding-left: 13px;
    padding-right: 13px;
  }

  .admin-agreement-version {
    padding: 12px;
  }

  .admin-agreement-version-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-chat-message {
    width: 96%;
    padding: 11px 12px;
  }

  .admin-chat-message-meta time {
    width: 100%;
    margin-left: 0;
  }
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  background: #fff;
  color: #111;
  font-family: "Inter", system-ui, sans-serif;
}

button,
input,
textarea {
  font: inherit;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  display: block;
  max-width: 100%;
}

.app {
  min-height: 100vh;
  overflow: hidden;
}

/* =========================================================
   NAVBAR
========================================================= */

.navbar {
  width: min(1180px, calc(100% - 40px));
  min-height: 82px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.logo {
  display: inline-block;
  color: #111;
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.8px;
  line-height: 1;
}

.logo span {
  color: #777;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-links a {
  color: #666;
  font-size: 14px;
  font-weight: 500;
  transition: color 0.2s ease;
}

.nav-links a:hover {
  color: #111;
}

.notifications-nav-link,
.home-notifications-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.notification-dot,
.home-notifications-dot {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  display: inline-block;
  border-radius: 50%;
  background: #111;
  box-shadow: 0 0 0 3px rgba(17, 17, 17, 0.08);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.auth-user {
  color: #777;
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
}

/* =========================================================
   BUTTONS
========================================================= */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  padding: 11px 18px;
  border: 0;
  border-radius: 12px;
  font-weight: 600;
  line-height: 1;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    border-color 0.2s ease,
    background 0.2s ease;
}

.btn:hover {
  transform: translateY(-2px);
}

.btn-dark {
  color: #fff;
  background: #111;
}

.btn-dark:hover {
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.14);
}

.btn-ghost {
  color: #222;
  background: transparent;
}

.btn-ghost:hover {
  background: #f3f3f3;
}

.btn-outline {
  color: #111;
  background: #fff;
  border: 1px solid #ddd;
}

.btn-outline:hover {
  border-color: #aaa;
  background: #fafafa;
}

.btn-light {
  color: #111;
  background: #fff;
}

.btn-large {
  min-height: 52px;
  padding: 15px 22px;
  border-radius: 14px;
}

/* =========================================================
   HERO
========================================================= */

.hero {
  width: min(1180px, calc(100% - 40px));
  min-height: 690px;
  margin: 0 auto;
  padding: 80px 0 100px;
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  align-items: center;
  gap: 70px;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 25px;
  color: #666;
  font-size: 13px;
  font-weight: 600;
}

.eyebrow-dot {
  width: 7px;
  height: 7px;
  flex: 0 0 7px;
  border-radius: 50%;
  background: #111;
}

.hero h1 {
  max-width: 700px;
  margin: 0;
  font-size: clamp(48px, 6vw, 76px);
  line-height: 0.98;
  letter-spacing: -4px;
}

.hero h1 span {
  color: #777;
}

.hero-text {
  max-width: 570px;
  margin: 30px 0 0;
  color: #666;
  font-size: 17px;
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 32px;
}

.hero-actions .btn span {
  margin-left: 15px;
}

.hero-stats {
  display: flex;
  gap: 35px;
  margin-top: 55px;
}

.hero-stats div {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.hero-stats strong {
  font-size: 14px;
}

.hero-stats span {
  color: #888;
  font-size: 12px;
}

/* =========================================================
   HERO VISUAL
========================================================= */

.hero-visual {
  position: relative;
  min-height: 500px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.visual-glow {
  position: absolute;
  width: 330px;
  height: 330px;
  border-radius: 50%;
  background: #f1f1f1;
}

.floating-card {
  position: absolute;
  z-index: 2;
  border: 1px solid #e8e8e8;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 25px 70px rgba(0, 0, 0, 0.09);
  backdrop-filter: blur(10px);
}

.card-main {
  width: 390px;
  padding: 27px;
  border-radius: 22px;
}

.card-header,
.card-meta {
  display: flex;
  justify-content: space-between;
  gap: 15px;
}

.card-header {
  color: #888;
  font-size: 12px;
}

.live-dot {
  color: #222;
}

.card-main h3 {
  margin: 28px 0 12px;
  font-size: 21px;
  line-height: 1.35;
}

.card-main p {
  margin: 0;
  color: #777;
  font-size: 13px;
  line-height: 1.6;
}

.card-meta {
  margin-top: 30px;
  padding-top: 18px;
  border-top: 0;
  color: #555;
  font-size: 12px;
}

.card-small {
  width: 230px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px;
  border-radius: 16px;
}

.card-small strong,
.card-small span {
  display: block;
}

.card-small strong {
  margin-bottom: 3px;
  font-size: 12px;
}

.card-small span {
  color: #888;
  font-size: 11px;
}

.card-top {
  top: 65px;
  right: 0;
  animation: float 5s ease-in-out infinite;
}

.card-bottom {
  bottom: 65px;
  left: 0;
  animation: float 5s ease-in-out infinite reverse;
}

.mini-icon,
.check-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: #f1f1f1;
}

@keyframes float {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-10px);
  }
}

/* =========================================================
   GENERAL SECTIONS
========================================================= */

.section {
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
  padding: 110px 0;
}

.section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 50px;
  margin-bottom: 55px;
}

.section-heading.centered {
  display: block;
  max-width: 650px;
  margin: 0 auto 55px;
  text-align: center;
}

.section-label {
  display: block;
  margin-bottom: 13px;
  color: #888;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
}

.section-heading h2,
.split-card h2,
.final-cta h2 {
  margin: 0;
  font-size: clamp(34px, 4vw, 52px);
  line-height: 1.05;
  letter-spacing: -2.5px;
}

.section-heading p {
  max-width: 360px;
  margin: 0;
  color: #777;
  line-height: 1.7;
}

/* =========================================================
   CATEGORIES
========================================================= */

.category-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.category-card {
  display: grid;
  grid-template-columns: 45px 1fr 25px;
  align-items: center;
  min-height: 120px;
  padding: 22px;
  text-align: left;
  border: 1px solid #e9e9e9;
  border-radius: 18px;
  background: #fff;
  transition:
    transform 0.25s ease,
    border-color 0.25s ease,
    box-shadow 0.25s ease;
}

.category-card:hover {
  transform: translateY(-5px);
  border-color: #ccc;
  box-shadow: 0 18px 45px rgba(0, 0, 0, 0.07);
}

.category-number {
  color: #aaa;
  font-size: 11px;
}

.category-name {
  font-weight: 600;
}

.category-arrow {
  color: #777;
  font-size: 20px;
}

/* =========================================================
   HOW IT WORKS
========================================================= */

.how {
  border-top: 0;
}

.steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 40px;
}

.step {
  padding-top: 25px;
  border-top: 0;
}

.step > span {
  color: #999;
  font-size: 12px;
  font-weight: 700;
}

.step h3 {
  margin: 28px 0 12px;
  font-size: 20px;
}

.step p {
  max-width: 300px;
  margin: 0;
  color: #777;
  line-height: 1.7;
}

/* =========================================================
   SPLIT
========================================================= */

.split-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 15px;
}

.split-card {
  min-height: 380px;
  padding: 45px;
  border-radius: 24px;
  background: #111;
  color: #fff;
}

.split-card.light {
  background: #f5f5f5;
  color: #111;
}

.split-card h2 {
  margin-bottom: 20px;
}

.split-card p {
  max-width: 450px;
  margin: 0 0 35px;
  color: #aaa;
  line-height: 1.7;
}

.split-card.light p {
  color: #777;
}

/* =========================================================
   FINAL CTA
========================================================= */

.final-cta {
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto 40px;
  padding: 90px 60px;
  border-radius: 28px;
  background: #111;
  color: #fff;
  text-align: center;
}

.final-cta .section-label {
  color: #999;
}

.final-cta h2 {
  margin-bottom: 35px;
}

/* =========================================================
   FOOTER
========================================================= */

.footer {
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
  padding: 40px 0 55px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  color: #888;
  font-size: 12px;
}

.footer p {
  margin: 8px 0 0;
}

.footer-links {
  display: flex;
  gap: 25px;
}

/* =========================================================
   APP PAGES
========================================================= */

.page {
  min-height: 100vh;
  background: #f7f7f5;
  padding: 32px 20px;
}

.app-page {
  width: min(900px, 100%);
  margin: 0 auto;
}

.app-page-header {
  max-width: 700px;
  margin-bottom: 42px;
}

.app-page-header h1 {
  margin: 12px 0 16px;
  font-size: clamp(42px, 7vw, 72px);
  line-height: 0.98;
  letter-spacing: -3px;
}

.app-page-header p {
  max-width: 600px;
  margin: 0;
  color: #666;
  font-size: 18px;
  line-height: 1.6;
}

/* =========================================================
   AUTH
========================================================= */

.auth-card {
  width: min(500px, 100%);
  margin: 50px auto;
  padding: 42px;
  background: #fff;
  border: 1px solid #e8e8e5;
  border-radius: 28px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.06);
}

.auth-card .logo {
  display: inline-block;
  margin-bottom: 60px;
  font-size: 26px;
}

.auth-header h1 {
  margin: 10px 0;
  font-size: 46px;
  letter-spacing: -2px;
}

.auth-header p {
  color: #666;
  line-height: 1.6;
}

.auth-form {
  display: grid;
  gap: 22px;
  margin-top: 35px;
}

.auth-form label,
.project-form label {
  display: grid;
  gap: 9px;
  color: #333;
  font-weight: 600;
}

.auth-form input,
.auth-form textarea,
.project-form input,
.project-form textarea {
  width: 100%;
  border: 1px solid #ddddda;
  border-radius: 14px;
  background: #fff;
  padding: 15px 16px;
  outline: none;
  transition:
    border-color 0.2s,
    box-shadow 0.2s;
}

.auth-form input:focus,
.auth-form textarea:focus,
.project-form input:focus,
.project-form textarea:focus {
  border-color: #111;
  box-shadow: 0 0 0 4px rgba(0, 0, 0, 0.05);
}

.auth-form textarea {
  display: block;
  min-width: 0;
  max-width: 100%;
  min-height: 170px;
  box-sizing: border-box;
  color: #171717;
  font: inherit;
  line-height: 1.6;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
  overflow-x: hidden;
  resize: vertical;
}

.auth-form input[type="file"] {
  padding: 12px;
  cursor: pointer;
}

.auth-form button {
  border: 0;
  margin-top: 5px;
}

.auth-error {
  margin: 0;
  padding: 12px 14px;
  border: 1px solid #f0caca;
  border-radius: 12px;
  background: #fff5f5;
  color: #b42318;
  font-size: 14px;
  line-height: 1.5;
}

.auth-footer {
  margin: 25px 0 0;
  text-align: center;
  color: #777;
}

.auth-footer a {
  color: #111;
  font-weight: 700;
}

/* =========================================================
   ACCOUNT / PROFILE
========================================================= */

.account-card {
  width: 100%;
  padding: 34px;
  border: 1px solid #e6e6e2;
  border-radius: 26px;
  background: #fff;
  box-shadow: 0 18px 55px rgba(0, 0, 0, 0.055);
}

/* GÄĹrny podglĂÂd profilu */

.profile-preview {
  display: flex;
  align-items: center;
  gap: 22px;
  margin-bottom: 34px;
  padding-bottom: 30px;
  border-bottom: 0;
}

/*
  WAÄšĹĽNE:
  ZdjĂÂcie nigdy nie moÄšĹşe przejĂÂĂÂ naturalnego rozmiaru
  pliku. Tutaj wymuszamy konkretny rozmiar.
*/

.profile-avatar {
  width: 96px;
  height: 96px;
  flex: 0 0 96px;
  display: block;
  overflow: hidden;
  border: 4px solid #fff;
  border-radius: 50%;
  background: #f0f0ee;
  object-fit: cover;
  object-position: center;
  box-shadow:
    0 0 0 1px #deded9,
    0 10px 25px rgba(0, 0, 0, 0.08);
}

/* Placeholder z pierwszĂÂ literĂÂ */

.profile-avatar-placeholder {
  display: grid;
  place-items: center;
  color: #111;
  background: linear-gradient(135deg, #f1f1ef, #deded9);
  font-size: 32px;
  font-weight: 700;
  text-transform: uppercase;
}

/* Nazwa i e-mail obok zdjĂÂcia */

.profile-preview h2 {
  margin: 0 0 6px;
  font-size: 24px;
  letter-spacing: -0.7px;
}

.profile-preview p {
  margin: 0;
  color: #777;
  font-size: 14px;
}

/* Pole wyboru zdjĂÂcia */

.profile-upload {
  display: grid;
  gap: 12px;
}

.profile-upload-label {
  color: #333;
  font-weight: 600;
}

.profile-upload input[type="file"] {
  width: 100%;
  padding: 12px;
  border: 1px dashed #cfcfca;
  border-radius: 14px;
  background: #fafaf8;
  cursor: pointer;
}

.profile-upload input[type="file"]:hover {
  border-color: #999;
  background: #f7f7f4;
}

.profile-upload-hint {
  margin: 0;
  color: #888;
  font-size: 12px;
  line-height: 1.5;
}

/* PodglĂÂd nowo wybranego zdjĂÂcia */

.profile-upload-preview {
  width: 72px;
  height: 72px;
  overflow: hidden;
  border: 3px solid #fff;
  border-radius: 50%;
  object-fit: cover;
  box-shadow: 0 0 0 1px #ddd;
}

/* Przyciski konta */

.account-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 20px;
}

.account-actions .btn {
  width: 100%;
}

.account-card > .auth-form {
  margin-top: 0;
}

/* komunikat zapisania */

.account-success {
  margin: 0;
  padding: 12px 14px;
  border: 1px solid #cce8d1;
  border-radius: 12px;
  background: #f1fbf3;
  color: #176b2c;
  font-size: 14px;
}

/* =========================================================
   PROJECT FORM
========================================================= */

.project-form {
  display: grid;
  gap: 24px;
  max-width: 700px;
  padding: 32px;
  background: #fff;
  border: 1px solid #e8e8e5;
  border-radius: 24px;
}

.project-form textarea {
  resize: vertical;
  min-height: 150px;
}

.project-form button {
  width: fit-content;
  border: 0;
}

/* =========================================================
   JOBS
========================================================= */

.jobs-list {
  display: grid;
  gap: 18px;
}

.job-card {
  padding: 28px;
  background: #fff;
  border: 1px solid #e8e8e5;
  border-radius: 22px;
  transition:
    transform 0.2s,
    box-shadow 0.2s;
}

.job-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.07);
}

.job-card h2 {
  margin: 12px 0 10px;
  font-size: 25px;
  letter-spacing: -0.7px;
}

.job-card p {
  margin: 0 0 22px;
  color: #666;
}

.job-card button {
  border: 0;
}

.job-details {
  margin-top: 24px;
  padding-top: 22px;
  border-top: 0;
}

.job-details > p {
  max-width: 100%;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.job-details-actions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: stretch;
  gap: 12px;
  margin-top: 20px;
}

.job-details-actions .btn,
.job-actions .btn {
  width: 100%;
  min-width: 0;
  min-height: 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  white-space: normal;
  text-align: center;
  line-height: 1.3;
}

.job-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: stretch;
  gap: 12px;
  margin-top: 20px;
}

.job-owner-note {
  margin-top: 16px !important;
  margin-bottom: 0 !important;
}

/* =========================================================
   LOADING
========================================================= */

.page .auth-card p {
  line-height: 1.6;
}

/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 900px) {
  .nav-links {
    display: flex;
    gap: 16px;
    overflow-x: auto;
    -ms-overflow-style: none;
    white-space: nowrap;
  }

  .hero {
    grid-template-columns: 1fr;
    gap: 20px;
    padding-top: 55px;
  }

  .hero-visual {
    min-height: 430px;
  }

  .category-grid,
  .steps {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 760px) {
  .job-details-actions,
  .job-actions {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 700px) {
  .page {
    padding: 16px 12px;
  }

  .navbar {
    width: 100%;
    min-height: 0;
    padding: 10px 4px 14px;
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-areas:
      "logo actions"
      "links links";
    gap: 12px 10px;
    align-items: center;
  }

  .navbar .logo {
    grid-area: logo;
  }

  .navbar .nav-links {
    grid-area: links;
    width: 100%;
    min-width: 0;
    padding: 2px 0 4px;
  }

  .navbar .nav-links a {
    flex: 0 0 auto;
    font-size: 13px;
    padding: 8px 0;
  }

  .navbar .nav-actions {
    grid-area: actions;
    gap: 6px;
    min-width: 0;
  }

  .home-notifications-link {
    position: relative;
  }

  .home-notifications-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: #111;
    display: inline-block;
    margin-left: 2px;
  }

  .auth-user {
    display: none;
  }

  .hero,
  .section {
    width: calc(100% - 28px);
  }

  .hero {
    min-height: auto;
    padding: 55px 0 70px;
  }

  .hero h1 {
    font-size: 48px;
    letter-spacing: -2.5px;
  }

  .hero-text {
    font-size: 15px;
  }

  .hero-stats {
    gap: 18px;
    margin-top: 40px;
  }

  .hero-stats span {
    display: none;
  }

  .hero-visual {
    min-height: 370px;
    transform: scale(0.9);
  }

  .card-main {
    width: 330px;
  }

  .section {
    padding: 75px 0;
  }

  .section-heading {
    display: block;
  }

  .section-heading p {
    margin-top: 20px;
  }

  .category-grid,
  .steps,
  .split-section {
    grid-template-columns: 1fr;
  }

  .split-card {
    min-height: auto;
    padding: 35px;
  }

  .final-cta {
    width: calc(100% - 28px);
    padding: 70px 25px;
  }

  .footer {
    width: calc(100% - 28px);
    align-items: flex-start;
    flex-direction: column;
  }

  .footer-links {
    flex-wrap: wrap;
  }

  /* PROFIL NA TELEFONIE */

  .account-card {
    padding: 22px;
    border-radius: 22px;
  }

  .profile-preview {
    align-items: flex-start;
    gap: 16px;
  }

  .profile-avatar {
    width: 76px;
    height: 76px;
    flex-basis: 76px;
  }

  .profile-preview h2 {
    font-size: 20px;
  }

  .account-actions {
    grid-template-columns: 1fr;
  }

  .app-page-header h1 {
    letter-spacing: -2px;
  }

  .auth-card {
    margin: 20px auto;
    padding: 28px 22px;
    border-radius: 22px;
  }

  .auth-card .logo {
    margin-bottom: 45px;
  }

  .auth-header h1 {
    font-size: 38px;
  }

  .project-form {
    padding: 22px;
    border-radius: 20px;
  }

  .job-card {
    padding: 22px;
  }
}

/* =========================================================
   DARK MODE Ă˘ÂÂ FINAL CONTRAST LAYER
   Kept at the end so it also overrides component styles.
========================================================= */

