/* Responsive administrative mode */

@media (max-width: 1040px) {
  .admin-navbar {
    grid-template-columns: minmax(180px, 1fr) minmax(0, 1.5fr);
    grid-template-areas:
      "brand actions"
      "links links";
    gap: 10px 14px;
    padding: 12px 0 14px;
  }

  .admin-navbar-brand {
    grid-area: brand;
  }

  .admin-nav-links {
    width: 100%;
    grid-area: links;
    justify-content: flex-start;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
  }

  .admin-navbar-actions {
    grid-area: actions;
  }
}

@media (max-width: 760px) {
  .admin-navbar {
    width: calc(100% - 28px);
  }

  .admin-nav-links {
    padding: 5px;
  }

  .admin-nav-links a {
    min-height: 40px;
    flex: 0 0 auto;
    padding: 9px 11px;
    font-size: 10px;
  }

  .admin-navbar-identity strong {
    max-width: 120px;
  }

  .admin-catalog-toolbar {
    grid-template-columns: minmax(0, 1fr);
    padding: 14px;
  }

  .admin-jobs-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .admin-privacy-note {
    grid-template-columns: minmax(0, 1fr);
    gap: 6px;
  }
}

@media (max-width: 480px) {
  .admin-navbar {
    width: calc(100% - 22px);
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 9px;
  }

  .admin-navbar-brand {
    gap: 7px;
  }

  .admin-navbar-brand .logo {
    font-size: 18px;
  }

  .admin-navbar-label {
    padding-inline: 6px;
    font-size: 7px;
  }

  .admin-navbar-identity {
    display: none;
  }

  .admin-logout-button {
    min-height: 38px;
    padding: 8px 10px;
    font-size: 9px;
  }

  .admin-job-card,
  .admin-evidence-message-card {
    padding: 16px;
    border-radius: 16px;
  }

  .admin-job-card h2 {
    font-size: 18px;
  }

  .admin-job-details {
    grid-template-columns: minmax(0, 1fr);
  }

  .admin-evidence-message-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-evidence-message-card .dispute-secondary-button {
    width: 100%;
  }
}
/* =========================================================
   ACCOUNT / PROFILE
========================================================= */

.account-card {
  padding: 42px;
  background: #ffffff;
  border: 1px solid #e8e8e5;
  border-radius: 28px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.05);
}

.profile-preview {
  display: flex;
  align-items: center;
  gap: 22px;
  padding-bottom: 32px;
  margin-bottom: 32px;
  border-bottom: 0;
}

.profile-avatar-wrapper {
  width: 104px;
  height: 104px;
  flex: 0 0 104px;
  padding: 4px;
  border-radius: 50%;
  background: #111;
  box-shadow:
    0 12px 35px rgba(0, 0, 0, 0.12),
    0 0 0 1px rgba(0, 0, 0, 0.08);
}

.profile-avatar {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  object-fit: cover;
  background: #f0f0ed;
}

.profile-avatar-placeholder {
  display: grid;
  place-items: center;
  color: #111;
  background: #f0f0ed;
  font-size: 36px;
  font-weight: 800;
}

.profile-info h2 {
  margin: 0 0 6px;
  font-size: 25px;
  letter-spacing: -0.8px;
}

.profile-info p {
  margin: 0;
  color: #777;
  font-size: 14px;
}

.account-form {
  margin-top: 0;
}

.account-form small {
  display: block;
  margin-top: 2px;
  color: #888;
  font-size: 12px;
  font-weight: 400;
  line-height: 1.5;
}

.profile-specialties-field,
.profile-skills-field {
  min-width: 0;
  margin: 0;
  padding: 20px;
  border: 1px solid #e3e3de;
  border-radius: 18px;
  background: #fafaf8;
}

.profile-specialties-field legend,
.profile-skills-field legend {
  padding: 0 8px;
  color: #333;
  font-size: 14px;
  font-weight: 750;
}

.profile-field-hint {
  margin: 0 0 15px;
  color: #777;
  font-size: 12px;
  font-weight: 400;
  line-height: 1.55;
}

.profile-category-options {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 12px;
}

.account-form .profile-category-option {
  width: 100%;
  min-width: 0;
  min-height: 44px;
  margin: 0;
  padding: 10px 12px;
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  border: 1px solid #dfdfda;
  border-radius: 12px;
  background: #fff;
  color: #555550;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.25;
  text-align: left;
  cursor: pointer;
  transition:
    border-color 0.18s,
    background 0.18s,
    color 0.18s,
    transform 0.18s;
}

.account-form .profile-category-option span {
  width: 20px;
  height: 20px;
  flex: 0 0 20px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #f0f0ed;
  color: #777;
  font-size: 12px;
}

.account-form .profile-category-option:hover {
  border-color: #bdbdb6;
  transform: translateY(-1px);
}

.account-form .profile-category-option.is-selected {
  border-color: #171717;
  background: #171717;
  color: #fff;
}

.account-form .profile-category-option.is-selected span {
  background: rgba(255, 255, 255, 0.16);
  color: #fff;
}

.account-form .profile-category-option:disabled {
  cursor: wait;
  opacity: 0.55;
  transform: none;
}

.ideahire-specialization-field {
  min-height: 165px;
}

.profile-skill-entry {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: stretch;
}

.profile-skill-entry input {
  min-width: 0;
}

.account-form .profile-add-skill {
  min-width: 92px;
  min-height: 48px;
  margin: 0;
  padding: 10px 16px;
  border: 1px solid #171717;
  border-radius: 12px;
  background: #171717;
  color: #fff;
  font: inherit;
  font-size: 13px;
  font-weight: 750;
  cursor: pointer;
}

.account-form .profile-add-skill:hover {
  background: #30302e;
}

.account-form .profile-add-skill:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.profile-edit-skill-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
  margin-bottom: 12px;
}

.profile-edit-skill-chip {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 8px 7px 11px;
  border: 1px solid #dcdcd6;
  border-radius: 10px;
  background: #fff;
  color: #3f3f3a;
  font-size: 12px;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.account-form .profile-edit-skill-chip button {
  width: 22px;
  height: 22px;
  flex: 0 0 22px;
  display: grid;
  place-items: center;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 7px;
  background: #f0f0ed;
  color: #777;
  font: inherit;
  font-size: 16px;
  line-height: 1;
  cursor: pointer;
}

.account-form .profile-edit-skill-chip button:hover {
  background: #eee1de;
  color: #8e352b;
}

.account-form input[type="file"] {
  width: 100%;
  padding: 12px;
  border: 1px dashed #d5d5d0;
  border-radius: 14px;
  background: #fafaf8;
  cursor: pointer;
}

.account-form input[type="file"]:hover {
  border-color: #999;
  background: #f5f5f2;
}

.profile-upload-status {
  padding: 14px 16px;
  border-radius: 12px;
  background: #f3f3f0;
  color: #555;
  font-size: 13px;
}

@media (max-width: 720px) {
  .profile-category-options {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 440px) {
  .profile-specialties-field,
  .profile-skills-field {
    padding: 16px;
  }

  .profile-category-options {
    grid-template-columns: 1fr;
  }

  .profile-skill-entry {
    grid-template-columns: 1fr;
  }

  .account-form .profile-add-skill {
    width: 100%;
  }
}

/* =========================================================
   GLOBAL APPEARANCE / LANGUAGE CONTROLS
========================================================= */

.site-preferences {
  position: fixed;
  z-index: 10000;
  top: 50%;
  right: 14px;
  transform: translateY(-50%);
  display: grid;
  gap: 8px;
  padding: 7px;
  border: 1px solid rgba(20, 20, 20, 0.11);
  border-radius: 17px;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 14px 38px rgba(20, 20, 20, 0.12);
  backdrop-filter: blur(14px);
}

.site-preferences-handle {
  display: none;
}

.site-preferences-panel {
  display: grid;
  gap: 8px;
}

.site-theme-toggle,
.site-language-toggle button {
  min-width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  margin: 0;
  padding: 0 8px;
  border: 0;
  border-radius: 11px;
  background: transparent;
  color: #575752;
  font: inherit;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
  cursor: pointer;
}

.site-theme-toggle {
  font-size: 20px;
}

.site-theme-toggle:hover,
.site-language-toggle button:hover {
  background: #f0f0ed;
  color: #111;
}

.site-language-toggle {
  display: grid;
  gap: 3px;
  padding-top: 7px;
  border-top: 0;
}

.site-language-toggle button.is-active {
  background: #171717;
  color: #fff;
}

