.cookie-notice {
  position: fixed;
  z-index: 20000;
  left: 50%;
  bottom: max(18px, env(safe-area-inset-bottom));
  width: min(980px, calc(100% - 36px));
  transform: translateX(-50%);
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  align-items: center;
  gap: 16px;
  padding: 17px 18px;
  border: 1px solid #deded8;
  border-radius: 20px;
  background: rgba(255, 255, 252, 0.97);
  color: #181917;
  box-shadow: 0 22px 70px rgba(24, 25, 23, 0.18);
  backdrop-filter: blur(18px);
}

.cookie-notice-mark {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: #171816;
  color: #fff;
  font-size: 19px;
  font-weight: 750;
  font-family: Georgia, serif;
}

.cookie-notice-copy {
  min-width: 0;
}

.cookie-notice-copy strong {
  display: block;
  margin-bottom: 4px;
  color: #171816;
  font-size: 14px;
  letter-spacing: -0.01em;
}

.cookie-notice-copy p {
  margin: 0;
  max-width: 660px;
  color: #686b66;
  font-size: 12px;
  line-height: 1.5;
}

.cookie-notice-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 9px;
}

.cookie-notice-actions a,
.cookie-notice-actions button {
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 16px;
  border-radius: 12px;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
}

.cookie-notice-actions a {
  border: 1px solid #d8d9d3;
  background: transparent;
  color: #333530;
}

.cookie-notice-actions a:hover {
  border-color: #aeb1a9;
  background: #f3f3ef;
}

.cookie-notice-actions button {
  border: 1px solid #171816;
  background: #171816;
  color: #fff;
  cursor: pointer;
}

.cookie-notice-actions button:hover {
  background: #30312e;
}

.cookie-policy-page {
  min-height: 100vh;
  padding: 28px 20px 70px;
  background:
    radial-gradient(circle at 85% 8%, rgba(196, 206, 194, 0.34), transparent 28%),
    #f6f6f2;
  color: #1b1d1a;
}

.cookie-policy-shell {
  width: min(1040px, 100%);
  margin: 0 auto;
}

.cookie-policy-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 28px;
}

.cookie-policy-logo {
  color: #151714;
  font-size: 23px;
  font-weight: 800;
  letter-spacing: -0.055em;
  text-decoration: none;
}

.cookie-policy-logo span {
  color: #777d75;
}

.cookie-policy-back {
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  padding: 0 15px;
  border: 1px solid #d9dad4;
  border-radius: 12px;
  background: rgba(255, 255, 252, 0.72);
  color: #343733;
  font-size: 12px;
  font-weight: 700;
  text-decoration: none;
}

.cookie-policy-back:hover {
  border-color: #aeb2aa;
  background: #fff;
}

.cookie-policy-language-en,
.cookie-policy-back-en {
  display: none;
}

html[data-language="en"] .cookie-policy-language-pl,
html[data-language="en"] .cookie-policy-back-pl {
  display: none;
}

html[data-language="en"] .cookie-policy-language-en,
html[data-language="en"] .cookie-policy-back-en {
  display: block;
}

.cookie-policy-hero {
  padding: clamp(34px, 7vw, 72px);
  border-radius: 30px;
  background: #181a17;
  color: #fff;
  overflow: hidden;
}

.cookie-policy-eyebrow {
  display: inline-flex;
  margin-bottom: 22px;
  padding: 7px 11px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 999px;
  color: #c8cdc5;
  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.cookie-policy-hero h1 {
  max-width: 790px;
  margin: 0;
  color: #fff;
  font-size: clamp(38px, 7vw, 76px);
  line-height: 0.98;
  letter-spacing: -0.06em;
}

.cookie-policy-hero > p {
  max-width: 650px;
  margin: 24px 0 0;
  color: #c6cbc3;
  font-size: clamp(15px, 2vw, 18px);
  line-height: 1.62;
}

.cookie-policy-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 34px;
}

.cookie-policy-meta span {
  padding: 8px 11px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.08);
  color: #d8ddd5;
  font-size: 11px;
  font-weight: 650;
}

.cookie-policy-highlight {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  gap: 17px;
  margin: 20px 0;
  padding: 22px;
  border: 1px solid #cbd7ca;
  border-radius: 20px;
  background: #edf4ec;
}

.cookie-policy-highlight-icon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border-radius: 15px;
  background: #29442e;
  color: #fff;
  font-size: 20px;
  font-weight: 800;
}

.cookie-policy-highlight strong {
  display: block;
  margin: 2px 0 5px;
  color: #1e3122;
  font-size: 15px;
}

.cookie-policy-highlight p {
  margin: 0;
  color: #526155;
  font-size: 13px;
  line-height: 1.6;
}

.cookie-policy-section,
.cookie-policy-inventory {
  margin-top: 20px;
  padding: clamp(24px, 4vw, 42px);
  border: 1px solid #e0e1db;
  border-radius: 24px;
  background: rgba(255, 255, 252, 0.88);
  box-shadow: 0 10px 36px rgba(32, 34, 30, 0.045);
}

.cookie-policy-section,
.cookie-policy-section-heading {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  gap: 20px;
}

.cookie-policy-section-number {
  color: #92978f;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.cookie-policy-section h2,
.cookie-policy-inventory h2 {
  margin: -5px 0 14px;
  color: #1b1d1a;
  font-size: clamp(24px, 4vw, 34px);
  line-height: 1.08;
  letter-spacing: -0.045em;
}

.cookie-policy-section p,
.cookie-policy-section-heading p {
  margin: 0;
  color: #61655e;
  font-size: 14px;
  line-height: 1.75;
}

.cookie-policy-section p + p {
  margin-top: 13px;
}

.cookie-policy-section a {
  color: #283d2c;
  font-weight: 700;
}

.cookie-policy-technology-list {
  display: grid;
  gap: 12px;
  margin-top: 26px;
}

.cookie-policy-technology {
  padding: 20px;
  border: 1px solid #e2e3dd;
  border-radius: 17px;
  background: #fafaf7;
}

.cookie-policy-technology-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 17px;
}

.cookie-policy-technology-heading code {
  min-width: 0;
  color: #1f211e;
  font-size: 12px;
  font-weight: 750;
  overflow-wrap: anywhere;
}

.cookie-policy-technology-heading > span {
  flex: 0 0 auto;
  max-width: 280px;
  padding: 6px 9px;
  border-radius: 999px;
  background: #e8eee6;
  color: #3e5342;
  font-size: 10px;
  font-weight: 750;
  text-align: center;
}

.cookie-policy-technology dl {
  display: grid;
  grid-template-columns: 0.75fr 1.4fr 1.15fr;
  gap: 18px;
  margin: 0;
}

.cookie-policy-technology dl > div {
  min-width: 0;
}

.cookie-policy-technology dt {
  margin-bottom: 5px;
  color: #969b93;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.cookie-policy-technology dd {
  margin: 0;
  color: #535750;
  font-size: 12px;
  line-height: 1.55;
  overflow-wrap: anywhere;
}

.cookie-policy-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 30px 4px 0;
  color: #858a82;
  font-size: 11px;
}

.cookie-policy-footer a {
  color: #363934;
  font-weight: 800;
  text-decoration: none;
}

html[data-theme="dark"] .cookie-notice {
  border-color: #383c37;
  background: rgba(23, 25, 22, 0.97);
  color: #f3f4ef;
  box-shadow: 0 24px 78px rgba(0, 0, 0, 0.5);
}

html[data-theme="dark"] .cookie-notice-mark {
  background: #eef0ea;
  color: #1a1c19;
}

html[data-theme="dark"] .cookie-notice-copy strong {
  color: #f3f4ef;
}

html[data-theme="dark"] .cookie-notice-copy p {
  color: #adb2aa;
}

html[data-theme="dark"] .cookie-notice-actions a {
  border-color: #454a43;
  color: #d8dcd4;
}

html[data-theme="dark"] .cookie-notice-actions a:hover {
  border-color: #626960;
  background: #292c27;
}

html[data-theme="dark"] .cookie-notice-actions button {
  border-color: #eef0ea;
  background: #eef0ea;
  color: #1a1c19;
}

html[data-theme="dark"] .cookie-notice-actions button:hover {
  background: #d9ddd5;
}

html[data-theme="dark"] .cookie-policy-page {
  background:
    radial-gradient(circle at 85% 8%, rgba(83, 100, 83, 0.22), transparent 28%),
    #10120f;
  color: #eeefe9;
}

html[data-theme="dark"] .cookie-policy-logo,
html[data-theme="dark"] .cookie-policy-footer a {
  color: #f1f2ed;
}

html[data-theme="dark"] .cookie-policy-back {
  border-color: #343832;
  background: rgba(27, 30, 26, 0.75);
  color: #d9ddd5;
}

html[data-theme="dark"] .cookie-policy-back:hover {
  border-color: #555b52;
  background: #22251f;
}

html[data-theme="dark"] .cookie-policy-hero {
  border: 1px solid #343832;
  background: #181b17;
}

html[data-theme="dark"] .cookie-policy-highlight {
  border-color: #354839;
  background: #18241a;
}

html[data-theme="dark"] .cookie-policy-highlight-icon {
  background: #dce8dc;
  color: #1c2d1f;
}

html[data-theme="dark"] .cookie-policy-highlight strong {
  color: #e7eee5;
}

html[data-theme="dark"] .cookie-policy-highlight p {
  color: #aab9aa;
}

html[data-theme="dark"] .cookie-policy-section,
html[data-theme="dark"] .cookie-policy-inventory {
  border-color: #2e322c;
  background: rgba(24, 27, 23, 0.9);
  box-shadow: none;
}

html[data-theme="dark"] .cookie-policy-section h2,
html[data-theme="dark"] .cookie-policy-inventory h2 {
  color: #f0f1ec;
}

html[data-theme="dark"] .cookie-policy-section p,
html[data-theme="dark"] .cookie-policy-section-heading p {
  color: #aeb3aa;
}

html[data-theme="dark"] .cookie-policy-section a {
  color: #d7e0d5;
}

html[data-theme="dark"] .cookie-policy-technology {
  border-color: #333730;
  background: #1d201b;
}

html[data-theme="dark"] .cookie-policy-technology-heading code {
  color: #eef0ea;
}

html[data-theme="dark"] .cookie-policy-technology-heading > span {
  background: #29352a;
  color: #cad8c8;
}

html[data-theme="dark"] .cookie-policy-technology dt {
  color: #858c82;
}

html[data-theme="dark"] .cookie-policy-technology dd {
  color: #b8bdb4;
}

html[data-theme="dark"] .cookie-policy-footer {
  color: #81877e;
}

@media (max-width: 760px) {
  body:has(.cookie-notice) .site-preferences {
    visibility: hidden;
    pointer-events: none;
  }

  .cookie-notice {
    bottom: max(10px, env(safe-area-inset-bottom));
    width: calc(100% - 20px);
    grid-template-columns: 38px minmax(0, 1fr);
    align-items: start;
    gap: 12px;
    padding: 15px;
    border-radius: 17px;
  }

  .cookie-notice-mark {
    width: 38px;
    height: 38px;
    border-radius: 12px;
    font-size: 17px;
  }

  .cookie-notice-copy strong {
    font-size: 13px;
  }

  .cookie-notice-copy p {
    font-size: 11px;
    line-height: 1.48;
  }

  .cookie-notice-actions {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
  }

  .cookie-notice-actions a,
  .cookie-notice-actions button {
    width: 100%;
    min-height: 43px;
    padding: 0 11px;
  }

  .cookie-policy-page {
    padding: 18px 12px 48px;
  }

  .cookie-policy-nav {
    margin-bottom: 16px;
  }

  .cookie-policy-logo {
    font-size: 20px;
  }

  .cookie-policy-back {
    min-height: 39px;
    padding: 0 12px;
    font-size: 11px;
  }

  .cookie-policy-hero {
    padding: 34px 22px;
    border-radius: 22px;
  }

  .cookie-policy-hero h1 {
    font-size: clamp(35px, 11vw, 52px);
  }

  .cookie-policy-hero > p {
    margin-top: 19px;
    font-size: 14px;
  }

  .cookie-policy-highlight {
    grid-template-columns: 40px minmax(0, 1fr);
    gap: 13px;
    padding: 17px;
    border-radius: 17px;
  }

  .cookie-policy-highlight-icon {
    width: 40px;
    height: 40px;
    border-radius: 12px;
  }

  .cookie-policy-section,
  .cookie-policy-inventory {
    padding: 22px 18px;
    border-radius: 19px;
  }

  .cookie-policy-section,
  .cookie-policy-section-heading {
    grid-template-columns: 1fr;
    gap: 11px;
  }

  .cookie-policy-section h2,
  .cookie-policy-inventory h2 {
    margin-top: 0;
  }

  .cookie-policy-technology {
    padding: 16px;
  }

  .cookie-policy-technology-heading {
    align-items: stretch;
    flex-direction: column;
    gap: 10px;
  }

  .cookie-policy-technology-heading > span {
    align-self: flex-start;
    max-width: 100%;
    text-align: left;
  }

  .cookie-policy-technology dl {
    grid-template-columns: 1fr;
    gap: 12px;
  }
}

/* =========================================================
   PRIVACY POLICY / REGISTRATION PRIVACY NOTICE
========================================================= */

.registration-privacy-confirmation {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  padding: 13px 14px;
  border: 1px solid #d9d9d4;
  border-radius: 13px;
  background: #fafaf7;
  transition:
    border-color 0.18s ease,
    background 0.18s ease,
    box-shadow 0.18s ease;
}

.registration-privacy-confirmation:hover,
.registration-privacy-confirmation:focus-within {
  border-color: #999f9a;
  box-shadow: 0 0 0 3px rgba(17, 17, 17, 0.05);
}

.registration-privacy-confirmation:has(input:checked) {
  border-color: #6f7d75;
  background: #f4f8f5;
}

.registration-privacy-confirmation > input,
.auth-form .registration-privacy-confirmation > input {
  width: 18px;
  min-width: 18px;
  height: 18px;
  min-height: 18px;
  flex: 0 0 18px;
  margin: 2px 0 0;
  padding: 0;
  accent-color: #171917;
  cursor: pointer;
}

.registration-privacy-confirmation > div {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.registration-privacy-confirmation label {
  color: #292c2a;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.4;
  cursor: pointer;
}

.registration-privacy-confirmation small {
  color: #737772;
  font-size: 10px;
  font-weight: 500;
  line-height: 1.5;
}

.registration-privacy-confirmation a {
  color: #283d2c;
  font-weight: 800;
}

.privacy-policy-hero {
  position: relative;
  isolation: isolate;
}

.privacy-policy-hero::after {
  content: "";
  position: absolute;
  z-index: -1;
  top: -110px;
  right: -80px;
  width: 320px;
  height: 320px;
  border-radius: 50%;
  background: rgba(163, 184, 161, 0.12);
  filter: blur(1px);
}

.privacy-policy-highlight .cookie-policy-highlight-icon {
  font-family: Georgia, serif;
  font-style: italic;
}

.privacy-policy-status-note {
  display: grid;
  gap: 5px;
  margin-top: 18px;
  padding: 15px 16px;
  border: 1px solid #e1d8bd;
  border-radius: 14px;
  background: #fffaf0;
}

.privacy-policy-status-note strong {
  color: #5c4b1c;
  font-size: 12px;
}

.cookie-policy-section .privacy-policy-status-note p {
  color: #75643a;
  font-size: 12px;
  line-height: 1.55;
}

.privacy-policy-card-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: 26px;
}

.privacy-policy-card {
  min-width: 0;
  padding: 20px;
  border: 1px solid #e2e3dd;
  border-radius: 17px;
  background: #fafaf7;
}

.privacy-policy-card h3 {
  margin: 0 0 8px;
  color: #252824;
  font-size: 14px;
  letter-spacing: -0.02em;
}

.privacy-policy-card p {
  margin: 0;
  color: #646861;
  font-size: 12px;
  line-height: 1.6;
}

.privacy-policy-bases {
  display: grid;
  gap: 11px;
  margin-top: 26px;
}

.privacy-policy-basis {
  display: grid;
  grid-template-columns: 1fr 1.15fr 1.25fr;
  gap: 18px;
  padding: 19px;
  border: 1px solid #e2e3dd;
  border-radius: 17px;
  background: #fafaf7;
}

.privacy-policy-basis > div {
  min-width: 0;
}

.privacy-policy-basis span {
  display: block;
  margin-bottom: 6px;
  color: #969b93;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.privacy-policy-basis strong {
  color: #262925;
  font-size: 12px;
  line-height: 1.5;
}

.privacy-policy-basis p {
  margin: 0;
  color: #5c6159;
  font-size: 11px;
  line-height: 1.58;
}

.privacy-policy-visibility-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: 20px;
}

.privacy-policy-visibility-grid article {
  padding: 19px;
  border: 1px solid #e1e2dc;
  border-radius: 16px;
  background: #fafaf7;
}

.privacy-policy-visibility-grid article:last-child {
  border-color: #d2ddd1;
  background: #f1f6f0;
}

.privacy-policy-visibility-grid strong {
  color: #2b2e2a;
  font-size: 12px;
}

.privacy-policy-visibility-grid ul {
  display: grid;
  gap: 7px;
  margin: 13px 0 0;
  padding-left: 18px;
  color: #62675f;
  font-size: 12px;
  line-height: 1.55;
}

.privacy-policy-retention {
  display: grid;
  gap: 0;
  margin-top: 26px;
  border: 1px solid #e2e3dd;
  border-radius: 17px;
  background: #fafaf7;
  overflow: hidden;
}

.privacy-policy-retention > div {
  display: grid;
  grid-template-columns: minmax(150px, 0.6fr) minmax(0, 1.4fr);
  gap: 22px;
  padding: 17px 19px;
}

.privacy-policy-retention > div + div {
  border-top: 0;
}

.privacy-policy-retention strong {
  color: #2a2d29;
  font-size: 11px;
  line-height: 1.55;
}

.privacy-policy-retention p {
  margin: 0;
  color: #62675f;
  font-size: 11px;
  line-height: 1.58;
}

.privacy-policy-sources {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 20px;
  padding: 17px 19px;
  border: 1px solid #e0e1db;
  border-radius: 17px;
  background: rgba(255, 255, 252, 0.72);
}

.privacy-policy-sources strong {
  margin-right: 4px;
  color: #343733;
  font-size: 11px;
}

.privacy-policy-sources a {
  padding: 7px 9px;
  border: 1px solid #dcded7;
  border-radius: 9px;
  color: #4d534b;
  font-size: 10px;
  font-weight: 700;
  text-decoration: none;
}

.privacy-policy-sources a:hover {
  border-color: #b7bbb3;
  background: #fff;
}

.privacy-policy-footer {
  gap: 18px;
}

.privacy-policy-footer nav {
  display: flex;
  align-items: center;
  gap: 14px;
}

.privacy-policy-footer nav a {
  color: #656a62;
  font-weight: 700;
}

html[data-theme="dark"] .registration-privacy-confirmation {
  border-color: #3a3a36;
  background: #1a1a18;
}

html[data-theme="dark"] .registration-privacy-confirmation:hover,
html[data-theme="dark"] .registration-privacy-confirmation:focus-within,
html[data-theme="dark"] .registration-privacy-confirmation:has(input:checked) {
  border-color: #71716a;
  background: #20201e;
  box-shadow: 0 0 0 3px rgba(240, 240, 236, 0.05);
}

html[data-theme="dark"] .registration-privacy-confirmation > input {
  accent-color: #efefeb;
}

html[data-theme="dark"] .registration-privacy-confirmation label {
  color: #f0f0ec;
}

html[data-theme="dark"] .registration-privacy-confirmation small {
  color: #aaa9a3;
}

html[data-theme="dark"] .registration-privacy-confirmation a {
  color: #d6ded4;
}

html[data-theme="dark"] .privacy-policy-status-note {
  border-color: #5b512e;
  background: #292619;
}

html[data-theme="dark"] .privacy-policy-status-note strong {
  color: #e5d79d;
}

html[data-theme="dark"] .cookie-policy-section .privacy-policy-status-note p {
  color: #bdb384;
}

html[data-theme="dark"] :is(
  .privacy-policy-card,
  .privacy-policy-basis,
  .privacy-policy-visibility-grid article,
  .privacy-policy-retention
) {
  border-color: #333730;
  background: #1d201b;
}

html[data-theme="dark"] .privacy-policy-visibility-grid article:last-child {
  border-color: #354839;
  background: #18241a;
}

html[data-theme="dark"] :is(
  .privacy-policy-card h3,
  .privacy-policy-basis strong,
  .privacy-policy-visibility-grid strong,
  .privacy-policy-retention strong
) {
  color: #eef0ea;
}

html[data-theme="dark"] :is(
  .privacy-policy-card p,
  .privacy-policy-basis p,
  .privacy-policy-visibility-grid ul,
  .privacy-policy-retention p
) {
  color: #b8bdb4;
}

html[data-theme="dark"] .privacy-policy-basis span {
  color: #858c82;
}

html[data-theme="dark"] .privacy-policy-retention > div + div {
  border-color: #333730;
}

html[data-theme="dark"] .privacy-policy-sources {
  border-color: #2e322c;
  background: rgba(24, 27, 23, 0.82);
}

html[data-theme="dark"] .privacy-policy-sources strong {
  color: #e9ebe5;
}

html[data-theme="dark"] .privacy-policy-sources a {
  border-color: #3a3f38;
  color: #c7ccc3;
}

html[data-theme="dark"] .privacy-policy-sources a:hover {
  border-color: #5a6157;
  background: #252923;
}

html[data-theme="dark"] .privacy-policy-footer nav a {
  color: #aeb4aa;
}

@media (max-width: 760px) {
  .privacy-policy-card-grid,
  .privacy-policy-visibility-grid {
    grid-template-columns: 1fr;
  }

  .privacy-policy-card {
    padding: 17px;
  }

  .privacy-policy-basis {
    grid-template-columns: 1fr;
    gap: 13px;
    padding: 17px;
  }

  .privacy-policy-retention > div {
    grid-template-columns: 1fr;
    gap: 5px;
    padding: 16px;
  }

  .privacy-policy-sources {
    align-items: stretch;
    flex-direction: column;
  }

  .privacy-policy-sources a {
    width: 100%;
