  border-radius: 13px;
  background: #efefe9;
  color: #555550;
  font-size: 12px;
  font-weight: 850;
}

.agreement-fixed-price-note {
  display: block;
  color: #84847e;
  font-size: 10px;
  line-height: 1.5;
}

.agreement-confirmation {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  margin-top: 20px;
  padding: 14px;
  border: 1px solid #e2e2dc;
  border-radius: 14px;
  background: #f8f8f4;
  cursor: pointer;
}

.agreement-confirmation input {
  width: 17px;
  height: 17px;
  flex: 0 0 17px;
  margin: 2px 0 0;
  accent-color: #171717;
}

.agreement-confirmation span {
  color: #555550;
  font-size: 12px;
  line-height: 1.55;
}

.agreement-form-actions,
.agreement-proposal-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 20px;
}

.agreement-primary-button,
.agreement-secondary-button {
  min-height: 44px;
  padding: 0 17px;
  border-radius: 13px;
  font: inherit;
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  transition:
    transform 0.16s ease,
    background 0.16s ease,
    border-color 0.16s ease;
}

.agreement-primary-button {
  border: 1px solid #171717;
  background: #171717;
  color: #fff;
}

.agreement-primary-button:hover:not(:disabled),
.agreement-secondary-button:hover:not(:disabled) {
  transform: translateY(-1px);
}

.agreement-secondary-button {
  border: 1px solid #d9d9d3;
  background: #fff;
  color: #343431;
}

.agreement-secondary-button:hover:not(:disabled) {
  border-color: #bdbdb7;
  background: #f7f7f3;
}

.agreement-primary-button:disabled,
.agreement-secondary-button:disabled {
  cursor: not-allowed;
  opacity: 0.48;
}

.agreement-message,
.agreement-blocked-note {
  margin: 16px 0 0;
  padding: 11px 13px;
  border: 1px solid #efd4ce;
  border-radius: 12px;
  background: #fff6f4;
  color: #8f3d33;
  font-size: 12px;
  line-height: 1.5;
}

.agreement-message.is-success {
  border-color: #d9e5d5;
  background: #f3f8f1;
  color: #42623b;
}

.agreement-details {
  gap: 10px;
}

.agreement-detail {
  min-width: 0;
  padding: 13px 14px;
  border: 1px solid #e6e6e0;
  border-radius: 14px;
  background: #fafaf7;
}

.agreement-detail > span {
  display: block;
  margin-bottom: 5px;
  color: #888882;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.045em;
  text-transform: uppercase;
}

.agreement-detail strong,
.agreement-detail p {
  display: block;
  margin: 0;
  color: #282825;
  font-size: 13px;
  line-height: 1.55;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.agreement-waiting-note {
  color: #5e7058;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.45;
}

.agreement-summary {
  border-bottom: 0;
  background: #fff;
}

.agreement-summary > summary {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 11px;
  padding: 12px 20px;
  list-style: none;
  cursor: pointer;
}

.agreement-summary > summary::-webkit-details-marker {
  display: none;
}

.agreement-status-icon {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #eaf3e6;
  color: #41643a;
  font-size: 13px;
  font-weight: 900;
}

.agreement-summary-copy {
  min-width: 0;
}

.agreement-summary-copy strong,
.agreement-summary-copy small {
  display: block;
}

.agreement-summary-copy strong {
  color: #2c2c29;
  font-size: 12px;
}

.agreement-summary-copy small {
  margin-top: 2px;
  color: #85857f;
  font-size: 10px;
}

.agreement-summary-action {
  color: #62625d;
  font-size: 11px;
  font-weight: 750;
}

.agreement-summary-body {
  padding: 4px 20px 20px;
}

.agreement-legal-note {
  margin: 12px 0 0;
  color: #85857f;
  font-size: 10px;
  line-height: 1.55;
}

.agreement-loading {
  min-height: 360px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 9px;
  color: #777771;
  text-align: center;
}

.agreement-loading p {
  margin: 0;
}

.agreement-waiting-card {
  max-width: 680px;
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  align-items: start;
  gap: 16px;
  margin: 0 auto;
  padding: 24px;
  border: 1px solid rgba(25, 25, 22, 0.09);
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 18px 54px rgba(25, 25, 20, 0.07);
}

.agreement-waiting-icon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border-radius: 15px;
  background: #efefe9;
  color: #555550;
  font-size: 24px;
}

.agreement-waiting-card h3 {
  margin: 2px 0 7px;
  color: #20201e;
  font-size: 18px;
  letter-spacing: -0.25px;
}

.agreement-waiting-card p {
  margin: 0;
  color: #73736d;
  font-size: 13px;
  line-height: 1.65;
}

.agreement-lock-icon {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border: 1px solid #ddddD7;
  border-radius: 50%;
  background: #fff;
}

