  gap: 8px;
  padding: 10px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 13px;
  background:
    radial-gradient(circle at 82% 28%, rgba(72, 128, 219, 0.5), transparent 24%),
    linear-gradient(145deg, #091525, #183a65);
}

#root .account-template-preview-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px 7px;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.95);
}

#root .account-template-preview-nav i:first-child {
  width: 36px;
  margin-right: auto;
  background: #0c1d33;
}

#root .account-template-preview-nav i {
  width: 22px;
  height: 4px;
  display: block;
  border-radius: 10px;
  background: #9ca9ba;
}

#root .account-template-preview-hero {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  align-items: center;
  gap: 10px;
  padding: 13px;
  border-radius: 10px 10px 22px 10px;
  background: rgba(255, 255, 255, 0.97);
}

#root .account-template-preview-hero > span {
  display: grid;
  gap: 7px;
}

#root .account-template-preview-hero i {
  width: 84%;
  height: 7px;
  display: block;
  border-radius: 10px;
  background: #0c1d33;
}

#root .account-template-preview-hero i:nth-child(2) {
  width: 62%;
}

#root .account-template-preview-hero i:nth-child(3) {
  width: 42%;
  height: 17px;
  margin-top: 4px;
  background: #244f8c;
}

#root .account-template-preview-hero b {
  width: 62px;
  height: 62px;
  justify-self: center;
  border-radius: 18px;
  background: linear-gradient(145deg, #183a65, #587eb6);
  transform: rotate(7deg);
}

#root .account-template-preview-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 5px;
}

#root .account-template-preview-cards i {
  height: 28px;
  display: block;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.1);
}

#root .account-template-option.is-classic .account-template-preview {
  border-color: #d8d8d2;
  background: #efefeb;
}

