/* =========================================================
   IDEA HIRE Ă˘ÂÂ V7.5 CONTINUOUS ATMOSPHERE
   One shared background spans hero and categories. The colour
   darkens softly at both viewport edges and has no section seam.
========================================================= */

:root {
  --ih-release: 20260920-8;
}

html {
  scrollbar-gutter: stable !important;
  max-width: 100%;
  overflow-x: clip;
}

body,
#root,
.app.app,
.page,
.account-page,
.privacy-center-page,
.disputes-page,
.admin-page,
.moderation-user-page {
  width: 100%;
}

body {
  max-width: 100%;
  overflow-x: clip;
}

.app.app {
  position: relative;
  isolation: isolate;
  background: var(--ih-canvas) !important;
}

.app.app > main {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-auto-rows: auto;
}

.app.app > main::before {
  content: "";
  position: relative;
  z-index: 0;
  grid-column: 1;
  grid-row: 1 / 3;
  width: 100%;
  min-width: 0;
  align-self: stretch;
  justify-self: stretch;
  background:
    linear-gradient(rgba(255, 255, 255, 0.018) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.018) 1px, transparent 1px),
    radial-gradient(ellipse 48% 70% at -6% 18%, rgba(0, 0, 0, 0.92) 0%, rgba(0, 0, 0, 0.62) 46%, transparent 100%),
    radial-gradient(ellipse 48% 70% at 106% 18%, rgba(0, 0, 0, 0.92) 0%, rgba(0, 0, 0, 0.62) 46%, transparent 100%),
    radial-gradient(ellipse 72% 42% at 73% 11%, rgba(57, 111, 183, 0.48) 0%, rgba(29, 70, 121, 0.2) 48%, transparent 78%),
    linear-gradient(
      180deg,
      #020711 0%,
      #061529 38%,
      #0d2d4d 53%,
      #1d5078 63%,
      #66849f 73%,
      #b7c6d3 83%,
      #e5ebf1 93%,
      #f4f6f9 100%
    );
  background-size: 36px 36px, 36px 36px, auto, auto, auto, auto;
  pointer-events: none;
}

.app.app > main > .hero {
  grid-column: 1;
  grid-row: 1;
  z-index: 2;
  overflow: visible;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.app.app > main > .hero::after {
  content: "";
  position: absolute;
  z-index: 0;
  top: -132px;
  right: auto;
  bottom: 0;
  left: 50%;
  width: 100vw;
  opacity: 1;
  transform: translateX(-50%);
  background:
    linear-gradient(rgba(255, 255, 255, 0.022) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.022) 1px, transparent 1px),
    radial-gradient(ellipse at 84% 18%, rgba(68, 116, 188, 0.4), transparent 35%),
    radial-gradient(ellipse at 12% 86%, rgba(26, 66, 112, 0.3), transparent 35%),
    linear-gradient(150deg, #050e1b 0%, #07172a 52%, #102b4d 100%) !important;
  background-size: 36px 36px, 36px 36px, auto, auto, auto !important;
  mask-image: none !important;
  pointer-events: none;
}

.app.app > main > .categories.section {
  grid-column: 1;
  grid-row: 2;
  position: relative;
  z-index: 1;
  isolation: isolate;
}

.app.app > main > .how.section {
  grid-column: 1;
  grid-row: 3;
}

.app.app > main > .split-section.section {
  grid-column: 1;
  grid-row: 4;
}

.app.app > main > .final-cta {
  grid-column: 1;
  grid-row: 5;
}

.app.app > main > .categories.section::before {
  content: "";
  position: absolute;
  z-index: 0;
  top: -2px;
  left: 50%;
  width: 100vw;
  height: calc(100% + 4px);
  transform: translateX(-50%);
  background:
    radial-gradient(circle at 86% 8%, rgba(89, 135, 197, 0.22), transparent 31%),
    linear-gradient(
      180deg,
      #102b4d 0%,
      #1d3f60 18%,
      #6f8ba4 42%,
      #cbd7e2 68%,
      #e7edf3 86%,
      #f4f6f9 100%
    );
  pointer-events: none;
}

.app.app > main > .categories.section > .section-heading,
.app.app > main > .categories.section > .category-grid {
  position: relative;
  z-index: 1;
}

.app.app > main > .categories .section-heading h2 {
  color: #fff !important;
  text-shadow: 0 3px 28px rgba(3, 13, 27, 0.22);
}

.app.app > main > .categories .section-heading p {
  color: #e0e8f1 !important;
}

.app.app > main > .categories .section-heading .section-label {
  color: #9fbdff !important;
}

html[data-theme="dark"] .app.app > main > .categories.section::before {
  background:
    radial-gradient(circle at 86% 8%, rgba(82, 128, 194, 0.2), transparent 31%),
    linear-gradient(
      180deg,
      #102b4d 0%,
      #173653 22%,
      #101e2d 58%,
      #0a111a 82%,
      #070b11 100%
    );
}

.app.app > main > .hero::after,
.app.app > main > .categories.section::before {
  content: none !important;
  display: none !important;
}

html[data-theme="dark"] .app.app > main::before {
  background:
