/* ---------- MOTION KEYFRAMES ---------- */

@keyframes ih-v6-nav-arrive {
  from {
    opacity: 0;
    transform: translateY(-18px) scale(0.985);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes ih-v6-copy-arrive {
  from {
    opacity: 0;
    transform: translateY(26px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes ih-v6-hero-blob {
  0% {
    transform: rotate(-4deg) scale(0.96);
    border-radius: 43% 57% 62% 38% / 48% 43% 57% 52%;
  }

  100% {
    transform: rotate(13deg) scale(1.07);
    border-radius: 62% 38% 44% 56% / 55% 63% 37% 45%;
  }
}

@keyframes ih-v6-visual-orb {
  0% {
    transform: rotate(-7deg) scale(0.97);
    border-radius: 45% 55% 63% 37% / 45% 42% 58% 55%;
  }

  100% {
    transform: rotate(8deg) scale(1.06);
    border-radius: 61% 39% 42% 58% / 58% 63% 37% 42%;
  }
}

@keyframes ih-v6-orbit-ring {
  from {
    transform: translate(-50%, -50%) rotate(0deg);
  }

  to {
    transform: translate(-50%, -50%) rotate(360deg);
  }
}

@keyframes ih-v6-orbit-ring-reverse {
  from {
    transform: translate(-50%, -50%) rotate(360deg) scale(0.96);
  }

  to {
    transform: translate(-50%, -50%) rotate(0deg) scale(1.04);
  }
}

@keyframes ih-v6-float-top {
  0%,
  100% {
    transform: translate3d(0, 0, 0) rotate(0.7deg);
  }

  50% {
    transform: translate3d(-8px, -17px, 0) rotate(-1deg);
  }
}

@keyframes ih-v6-float-bottom {
  0%,
  100% {
    transform: translate3d(0, 0, 0) rotate(-0.8deg);
  }

