/* =========================================================
   DISPUTE TRANSPARENCY / CONTROLLED ADMIN ACCESS
========================================================= */

.dispute-context-notice {
  display: grid;
  gap: 13px;
  padding: 16px;
  border: 1px solid #d9dfdd;
  border-radius: 15px;
  background: linear-gradient(145deg, #f7faf9, #f1f5f3);
}

.dispute-context-notice-heading {
  display: flex;
  align-items: flex-start;
  gap: 11px;
}

.dispute-context-notice-heading > div,
.dispute-context-acknowledgement > span,
.dispute-transparency-banner > div {
  min-width: 0;
}

.dispute-context-notice-icon,
.dispute-transparency-icon {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  flex: 0 0 28px;
  border-radius: 50%;
  background: #202522;
  color: #fff;
  font-size: 13px;
  font-weight: 800;
  font-style: normal;
}

.dispute-context-notice-heading strong {
  display: block;
  margin: 1px 0 4px;
  color: #1d211f;
  font-size: 13px;
  line-height: 1.35;
}

.dispute-context-notice-heading p,
.dispute-context-notice-safety {
  margin: 0;
  color: #626863;
  font-size: 11px;
  line-height: 1.55;
}

.dispute-context-notice-list {
  display: grid;
  gap: 6px;
  margin: 0;
  padding: 0 0 0 39px;
  color: #404541;
  font-size: 11px;
  line-height: 1.45;
}

.dispute-context-notice-list li::marker {
  color: #65716b;
}

.dispute-context-notice-safety {
  padding: 10px 12px;
  border: 1px solid rgba(55, 67, 61, 0.09);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.68);
}

.dispute-context-acknowledgement {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px;
  border: 1px solid #cfd6d2;
  border-radius: 11px;
  background: #fff;
  cursor: pointer;
  transition:
    border-color 0.18s ease,
    background 0.18s ease,
    box-shadow 0.18s ease;
}

.dispute-context-acknowledgement:hover,
.dispute-context-acknowledgement:focus-within {
  border-color: #818e87;
  box-shadow: 0 0 0 3px rgba(37, 47, 42, 0.06);
}

.dispute-context-acknowledgement:has(input:checked) {
  border-color: #6d7c74;
  background: #f8fbf9;
}

.dispute-context-acknowledgement input {
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
  margin: 1px 0 0;
  accent-color: #171b19;
}

.dispute-context-acknowledgement > span {
  display: grid;
  gap: 3px;
}

.dispute-context-acknowledgement strong {
  color: #252a27;
  font-size: 11px;
  line-height: 1.45;
}

.dispute-context-acknowledgement small {
  color: #737a76;
  font-size: 9px;
  line-height: 1.5;
}

.dispute-transparency-banner {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  margin: 0 0 18px;
  padding: 17px 18px;
  border: 1px solid #dce2de;
  border-radius: 16px;
  background: #f2f6f4;
}

.dispute-transparency-banner strong {
  display: block;
  margin: 1px 0 4px;
  color: #242825;
  font-size: 12px;
  line-height: 1.4;
}

.dispute-transparency-banner p {
  margin: 0;
  color: #626963;
  font-size: 11px;
  line-height: 1.55;
}

.dispute-transparency-banner small {
  display: block;
  margin-top: 7px;
  color: #7b817d;
  font-size: 9px;
  line-height: 1.45;
}

html[data-theme="dark"] .dispute-context-notice {
  border-color: #3b4540;
  background: linear-gradient(145deg, #202522, #1b201d);
}

html[data-theme="dark"] .dispute-context-notice-icon,
html[data-theme="dark"] .dispute-transparency-icon {
  background: #ecefe9;
  color: #171a18;
}

html[data-theme="dark"] .dispute-context-notice-heading strong,
html[data-theme="dark"] .dispute-context-acknowledgement strong,
html[data-theme="dark"] .dispute-transparency-banner strong {
  color: #f1f2ee;
}

html[data-theme="dark"] .dispute-context-notice-heading p,
html[data-theme="dark"] .dispute-context-notice-safety,
html[data-theme="dark"] .dispute-transparency-banner p {
  color: #afb6b0;
}

html[data-theme="dark"] .dispute-context-notice-list {
  color: #cbd0cb;
}

html[data-theme="dark"] .dispute-context-notice-safety {
  border-color: #343d38;
  background: rgba(10, 12, 11, 0.3);
}

html[data-theme="dark"] .dispute-context-acknowledgement {
  border-color: #424b46;
  background: #151816;
}

html[data-theme="dark"] .dispute-context-acknowledgement:hover,
html[data-theme="dark"] .dispute-context-acknowledgement:focus-within,
html[data-theme="dark"] .dispute-context-acknowledgement:has(input:checked) {
  border-color: #717e77;
  background: #1a1f1c;
  box-shadow: 0 0 0 3px rgba(229, 236, 231, 0.05);
}

html[data-theme="dark"] .dispute-context-acknowledgement input {
  accent-color: #e7ebe6;
}

html[data-theme="dark"] .dispute-context-acknowledgement small,
html[data-theme="dark"] .dispute-transparency-banner small {
  color: #929a94;
}

html[data-theme="dark"] .dispute-transparency-banner {
  border-color: #3a4540;
  background: #1c231f;
}

@media (max-width: 600px) {
  .dispute-context-notice {
    gap: 12px;
    padding: 14px;
    border-radius: 13px;
  }

  .dispute-context-notice-list {
    padding-left: 35px;
  }

  .dispute-context-acknowledgement {
    padding: 11px;
  }

  .dispute-transparency-banner {
    gap: 10px;
    padding: 14px;
    border-radius: 14px;
  }

  .dispute-context-notice-icon,
  .dispute-transparency-icon {
    width: 26px;
    height: 26px;
    flex-basis: 26px;
  }
}

