  grid-template-columns: 28px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
}

.privacy-audit-check-title > span {
  width: 28px;
  height: 25px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  background: #edf0eb;
  color: #687067;
  font-size: 8px;
  font-weight: 900;
}

.privacy-audit-check-title strong {
  display: block;
  color: #323932;
  font-size: 11px;
}

.privacy-audit-check-title p {
  margin: 4px 0 0;
  color: #7a8279;
  font-size: 9px;
  font-weight: 500;
  line-height: 1.5;
}

.privacy-audit-check textarea {
  min-height: 78px;
}

.privacy-audit-public-summary {
  padding: 15px;
  border: 1px solid #cbd9cd;
  border-radius: 14px;
  background: #eef5ef;
}

.privacy-audit-public-summary small {
  color: #68776a;
  font-size: 9px;
  font-weight: 600;
  line-height: 1.5;
}

.privacy-audit-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.privacy-audit-approval-panel {
  display: grid;
  gap: 13px;
  margin-top: 17px;
  padding: 16px;
  border: 1px solid #cfd3e1;
  border-radius: 14px;
  background: #f0f1f8;
}

.privacy-audit-approval-panel strong {
  color: #343d62;
  font-size: 12px;
}

.privacy-audit-approval-panel p {
  margin: 4px 0 0;
  color: #666d85;
  font-size: 10px;
  line-height: 1.55;
}

.privacy-audit-approved-summary {
  margin-top: 17px;
  border-color: #c5d9c8;
  background: #edf6ee;
}

.privacy-audit-approved-summary small {
  display: block;
  margin-top: 8px;
  color: #738075;
  font-size: 9px;
}

.privacy-audit-history {
  margin-top: 17px;
  border-top: 0;
}

.privacy-audit-history summary {
  padding: 13px 0 2px;
  color: #3b463c;
  font-size: 10px;
  font-weight: 850;
  cursor: pointer;
}

.privacy-audit-history ol {
  display: grid;
  gap: 8px;
  margin: 12px 0 0;
  padding: 0;
  list-style: none;
}

.privacy-audit-history li {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 12px;
  border-radius: 10px;
  background: #fff;
}

.privacy-audit-history li strong {
  display: block;
  color: #3d453d;
  font-size: 10px;
}

.privacy-audit-history li p {
  margin: 4px 0 0;
  color: #757d74;
  font-size: 9px;
  line-height: 1.5;
}

.privacy-audit-history time {
  flex: 0 0 auto;
  color: #8c938a;
  font-size: 8px;
}

.privacy-audit-contact-note {
  padding: 11px 13px;
  border: 1px solid #d4d9d2;
  border-radius: 11px;
  background: #eef2ed;
  color: #626b61;
  font-size: 10px;
  line-height: 1.55;
}

/* PeÄšÂny, zatwierdzony raport widoczny na koncie uÄšĹşytkownika. */
.privacy-user-audit-report {
  margin: 20px 0 16px;
  padding: clamp(18px, 3vw, 28px);
  border: 1px solid #bfd0c1;
  border-radius: 20px;
  background:
    linear-gradient(145deg, rgba(237, 246, 238, 0.9), rgba(255, 255, 252, 0.98) 46%),
    #fff;
  box-shadow: 0 14px 34px rgba(42, 68, 47, 0.08);
}

.privacy-user-audit-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 18px;
  border-bottom: 0;
}

.privacy-user-audit-heading h4 {
  margin: 6px 0 0;
  color: #1f2c22;
  font-size: clamp(20px, 3vw, 28px);
  letter-spacing: -0.035em;
}

.privacy-user-risk {
  flex: 0 0 auto;
  padding: 8px 11px;
  border: 1px solid #cdd9ce;
  border-radius: 999px;
  background: #edf3ed;
  color: #3f5a44;
  font-size: 11px;
  font-weight: 850;
}

.privacy-user-risk.is-medium,
.privacy-user-risk.is-high {
  border-color: #ead2a6;
  background: #fff4df;
  color: #795516;
}

.privacy-user-risk.is-critical {
  border-color: #e2baba;
  background: #fff0ef;
  color: #8a3434;
}

.privacy-user-report-intro {
  margin: 18px 0;
  padding: 18px;
  border-radius: 14px;
  background: #263a2c;
  color: #fff;
}

.privacy-user-report-intro strong {
  display: block;
  margin-bottom: 7px;
  color: #fff;
  font-size: 12px;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.privacy-user-report-intro p {
  margin: 0;
  color: #f5f8f3;
  font-size: 16px;
  line-height: 1.7;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.privacy-user-report-intro small {
  display: block;
  margin-top: 10px;
  color: #cbd8cc;
  font-size: 11px;
}

.privacy-user-report-grid {
  display: grid;
  gap: 10px;
}

.privacy-user-report-grid article {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  gap: 13px;
  padding: 16px;
  border: 1px solid #e0e6df;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.78);
}

.privacy-user-report-grid article > span,
.privacy-user-check-number {
  width: 34px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: #e8efe8;
  color: #506153;
  font-size: 10px;
  font-weight: 900;
}

.privacy-user-report-grid h5,
.privacy-user-check-title h5 {
  margin: 0;
  color: #263129;
  font-size: 14px;
}

.privacy-user-report-grid p {
  margin: 6px 0 0;
  color: #59645b;
  font-size: 14px;
  line-height: 1.7;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.privacy-user-checks-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 14px;
  margin: 24px 0 11px;
}

.privacy-user-checks-heading span {
  color: #263129;
  font-size: 16px;
  font-weight: 850;
}

.privacy-user-checks-heading p {
  margin: 4px 0 0;
  color: #687269;
  font-size: 12px;
  line-height: 1.5;
}

.privacy-user-checks-heading > strong {
  color: #31573a;
  font-size: 16px;
}

.privacy-user-checklist {
  display: grid;
  gap: 9px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.privacy-user-checklist li {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  gap: 13px;
  padding: 15px 16px;
  border: 1px solid #dde5dd;
  border-left: 4px solid #8aa08e;
  border-radius: 13px;
  background: #fff;
}

.privacy-user-checklist li.is-passed {
  border-left-color: #5d9165;
}

.privacy-user-checklist li.is-issue_found {
  border-left-color: #cc8333;
}

.privacy-user-checklist li.is-not_applicable {
  border-left-color: #858a96;
}

.privacy-user-check-title {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.privacy-user-check-title > span {
  flex: 0 0 auto;
  padding: 5px 8px;
  border-radius: 999px;
  background: #edf2ec;
  color: #4e6252;
  font-size: 10px;
  font-weight: 800;
}

.privacy-user-checklist li.is-issue_found .privacy-user-check-title > span {
  background: #fff0dd;
  color: #7b531b;
}

.privacy-user-checklist li > div > p {
  margin: 7px 0 0;
  color: #5b655d;
  font-size: 14px;
  line-height: 1.65;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.privacy-user-report-boundary {
  margin: 16px 0 0;
  padding: 13px 15px;
  border: 1px solid #e5dfc8;
  border-radius: 12px;
  background: #fffbed;
  color: #6e6549;
  font-size: 12px;
  line-height: 1.65;
}

.privacy-user-acceptance-panel {
  display: grid;
  gap: 12px;
  margin: 16px 0;
  padding: 18px;
  border: 1px solid #bcd5c0;
  border-radius: 16px;
  background: #edf7ef;
}

.privacy-user-acceptance-panel.is-prominent {
  border-width: 2px;
  box-shadow: 0 12px 28px rgba(44, 88, 55, 0.11);
}

.privacy-user-acceptance-panel strong {
  color: #294b31;
  font-size: 15px;
}

.privacy-user-acceptance-panel p {
  margin: 5px 0 0;
  color: #55705b;
  font-size: 13px;
  line-height: 1.6;
}

.privacy-user-acceptance-panel > small {
  color: #687a6b;
  font-size: 11px;
  line-height: 1.55;
}

.privacy-accept-button {
  min-height: 48px;
  padding: 10px 16px;
  border: 1px solid #254b2f;
  border-radius: 12px;
  background: #2d5838;
  color: #fff;
  font: inherit;
  font-size: 12px;
  font-weight: 850;
  cursor: pointer;
}

.privacy-accept-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.privacy-user-closed-banner,
.privacy-admin-closed-banner {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: 12px;
  align-items: start;
  margin: 15px 0;
  padding: 15px 16px;
  border: 1px solid #abd0b1;
  border-radius: 15px;
  background: #e9f7ec;
}

.privacy-user-closed-banner > span,
.privacy-admin-closed-banner > span {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  background: #2d6339;
  color: #fff;
  font-size: 16px;
  font-weight: 900;
}

.privacy-user-closed-banner strong,
.privacy-admin-closed-banner strong {
  display: block;
  color: #285033;
  font-size: 14px;
}

.privacy-user-closed-banner p,
.privacy-admin-closed-banner p {
  margin: 4px 0 0;
  color: #56725c;
  font-size: 12px;
  line-height: 1.55;
}

.privacy-admin-latest-reply {
  display: grid;
  gap: 10px;
  margin: 15px 0;
  padding: 16px;
  border: 1px solid #d8dfd7;
  border-left: 4px solid #758779;
  border-radius: 14px;
  background: #f7f9f5;
}

.privacy-admin-latest-reply.needs-attention {
  border-color: #d8bd83;
  border-left-color: #b7771f;
  background: #fff8e9;
  box-shadow: 0 10px 24px rgba(113, 81, 24, 0.08);
}

.privacy-admin-latest-reply-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.privacy-admin-latest-reply-heading strong {
  display: block;
  margin-top: 4px;
  color: #303a32;
  font-size: 13px;
}

.privacy-admin-latest-reply-heading > span {
  flex: 0 0 auto;
  padding: 6px 9px;
  border-radius: 999px;
  background: #e5ebe4;
  color: #59675b;
  font-size: 9px;
  font-weight: 850;
}

.privacy-admin-latest-reply.needs-attention
  .privacy-admin-latest-reply-heading > span {
  background: #f3dfb7;
  color: #735018;
}

.privacy-admin-latest-reply > p {
  margin: 0;
  color: #48534b;
  font-size: 14px;
  line-height: 1.65;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.privacy-admin-latest-reply > time {
  color: #7b847b;
  font-size: 10px;
}

.privacy-admin-timeline li.is-requester {
  border-left-color: #4f7658;
  background: #f0f6f1;
}

.privacy-admin-timeline li.is-latest {
  box-shadow: inset 0 0 0 1px #b8cbbb;
}

.privacy-user-reply-form,
.privacy-admin-reply-form {
  display: grid;
  gap: 10px;
  margin: 16px 0;
  padding: 16px;
  border: 1px solid #d9dfd7;
  border-radius: 15px;
  background: #f7f9f5;
}

.privacy-user-reply-form > label,
.privacy-admin-reply-form strong,
.privacy-admin-reply-form label {
  color: #303c32;
  font-size: 13px;
  font-weight: 850;
}

.privacy-user-reply-form > p,
.privacy-admin-reply-form p {
  margin: -4px 0 2px;
  color: #687168;
  font-size: 12px;
  line-height: 1.55;
}

.privacy-user-reply-form textarea,
.privacy-admin-reply-form textarea {
  width: 100%;
  min-height: 100px;
  box-sizing: border-box;
  padding: 13px;
  border: 1px solid #d4dad3;
  border-radius: 12px;
  background: #fff;
  color: #242a25;
  font: inherit;
  font-size: 14px;
  line-height: 1.55;
  outline: none;
  resize: vertical;
}

.privacy-user-reply-form textarea:focus,
.privacy-admin-reply-form textarea:focus {
  border-color: #708574;
  box-shadow: 0 0 0 3px rgba(75, 97, 80, 0.1);
}

.privacy-user-reply-form > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.privacy-user-reply-form small {
  color: #828980;
  font-size: 10px;
}

.privacy-user-reply-form .privacy-secondary-button,
.privacy-admin-reply-form .privacy-secondary-button {
  padding: 0 15px;
}

.privacy-timeline li > div {
  display: grid;
  gap: 4px;
}

.privacy-timeline li > div strong {
  color: #344038;
  font-size: 10px;
}

.privacy-timeline li > div span {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.privacy-audit-public-note {
  padding-top: 10px;
  border-top: 0;
}

.privacy-audit-public-note small {
  color: #68786b;
  font-size: 9px;
  font-weight: 600;
}

.privacy-audit-public-editor {
  display: grid;
  gap: 15px;
  padding: 17px;
  border: 1px solid #bed2c1;
  border-radius: 16px;
  background: #edf5ee;
}

.privacy-audit-public-editor-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.privacy-audit-public-editor-heading h5 {
  margin: 4px 0 0;
  color: #2c3d30;
  font-size: 15px;
}

.privacy-audit-public-editor-heading > strong {
  padding: 6px 9px;
  border-radius: 999px;
  background: #dceadd;
  color: #3c6243;
  font-size: 9px;
  text-align: center;
}

.privacy-audit-public-editor > p {
  margin: 0;
  color: #607064;
  font-size: 10px;
  line-height: 1.6;
}

.privacy-admin-reply-form {
  margin-top: 17px;
  border-color: #ccd8cd;
  background: #f2f7f2;
}

