/* =========================================================
   IDEA HIRE Ă˘ÂÂ POMOCNY ONBOARDING I DOPASOWANIE V2.2
========================================================= */

.discovery-onboarding-backdrop {
  position: fixed;
  inset: 0;
  z-index: 12000;
  display: grid;
  place-items: center;
  padding: 24px;
  overflow: auto;
  background:
    radial-gradient(circle at 12% 12%, rgba(111, 126, 255, 0.17), transparent 34%),
    radial-gradient(circle at 88% 86%, rgba(94, 198, 155, 0.15), transparent 32%),
    rgba(13, 13, 14, 0.76);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  animation: discovery-backdrop-in 260ms ease both;
}

.discovery-onboarding-shell {
  position: relative;
  isolation: isolate;
  width: min(1040px, 100%);
  min-height: 690px;
  max-height: calc(100dvh - 48px);
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.74);
  border-radius: 30px;
  background: rgba(255, 255, 252, 0.97);
  box-shadow: 0 36px 110px rgba(0, 0, 0, 0.32);
  color: #171716;
  animation: discovery-shell-in 420ms cubic-bezier(.2, .8, .2, 1) both;
}

.discovery-onboarding-ambient {
  position: absolute;
  inset: 0;
  z-index: -1;
  overflow: hidden;
  pointer-events: none;
}

.discovery-onboarding-ambient span {
  position: absolute;
  width: 330px;
  height: 330px;
  border-radius: 50%;
  filter: blur(2px);
  opacity: 0.7;
  animation: discovery-orbit 12s ease-in-out infinite alternate;
}

.discovery-onboarding-ambient span:first-child {
  top: -225px;
  right: -105px;
  background: radial-gradient(circle, rgba(119, 132, 255, 0.22), transparent 68%);
}

.discovery-onboarding-ambient span:last-child {
  bottom: -240px;
  left: -90px;
  background: radial-gradient(circle, rgba(83, 193, 146, 0.18), transparent 68%);
  animation-delay: -4s;
}

.discovery-onboarding-header {
  min-height: 76px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 18px;
  padding: 0 34px;
  border-bottom: 0;
}

.discovery-onboarding-header .logo {
  justify-self: start;
}

.discovery-step-count {
  justify-self: center;
  color: #74746f;
  font-size: 12px;
  font-weight: 750;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.discovery-close-button {
  width: 38px;
  height: 38px;
  justify-self: end;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid #e2e2dd;
  border-radius: 50%;
  background: #f7f7f4;
  color: #52524e;
  font-size: 23px;
  line-height: 1;
}

.discovery-close-button:hover {
  border-color: #c9c9c3;
  background: #eeeeea;
  color: #111;
  transform: none;
}

.discovery-progress {
  height: 4px;
  overflow: hidden;
  background: #eeeeea;
}

.discovery-progress > span {
  height: 100%;
  display: block;
  border-radius: 0 999px 999px 0;
  background: linear-gradient(90deg, #151515, #5a5a56);
  transition: width 480ms cubic-bezier(.2, .8, .2, 1);
}

.discovery-onboarding-content {
  width: min(880px, 100%);
  align-self: center;
  justify-self: center;
