/* Animacje */

@keyframes discovery-backdrop-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes discovery-shell-in {
  from {
    opacity: 0;
    transform: translateY(22px) scale(0.975);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes discovery-step-in {
  from {
    opacity: 0;
    transform: translateX(18px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes discovery-orbit {
  from { transform: translate3d(-8px, -5px, 0) scale(0.96); }
  to { transform: translate3d(18px, 14px, 0) scale(1.08); }
}

