  background: #fff;
}

.private-work-share-toggle {
  width: 100%;
  min-height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 8px 16px;
  border: 0;
  background: transparent;
  color: #40403c;
