  padding: 4px;
  border-radius: 12px;
  background: #f1f1ed;
}

.private-work-tabs button {
  min-height: 40px;
  padding: 8px 10px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: #696964;
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}

.private-work-tabs button.is-active {
  background: #fff;
  color: #171717;
  box-shadow: 0 2px 8px rgba(20, 20, 20, .07);
}

.private-work-tabs button:disabled {
  cursor: not-allowed;
  opacity: .42;
}

.private-work-field,
.private-work-report-dialog > label {
  display: grid;
  gap: 7px;
  color: #363633;
  font-size: 12px;
  font-weight: 750;
}

.private-work-field textarea,
.private-work-link-inputs input,
.private-work-delivery-actions textarea,
.private-work-report-dialog textarea,
.private-work-report-dialog input,
.private-work-report-dialog select {
  width: 100%;
  padding: 11px 12px;
  border: 1px solid #d9d9d3;
  border-radius: 11px;
  outline: 0;
  background: #fafaf7;
  color: #171717;
  font: inherit;
  line-height: 1.45;
}

.private-work-field textarea:focus,
.private-work-link-inputs input:focus,
.private-work-delivery-actions textarea:focus,
.private-work-report-dialog textarea:focus,
.private-work-report-dialog input:focus,
.private-work-report-dialog select:focus {
