  box-shadow: 0 0 0 3px rgba(30, 30, 28, .07);
}

.private-work-picker-row {
  display: flex;
  align-items: stretch;
  gap: 10px;
}

.private-work-file-picker {
  flex: 1;
  display: grid;
  gap: 2px;
  padding: 13px;
  border: 1px dashed #c8c8c1;
  border-radius: 12px;
  background: #fafaf7;
  cursor: pointer;
}

.private-work-file-picker input {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
}

.private-work-file-picker span {
  font-size: 12px;
  font-weight: 850;
}

.private-work-file-picker small {
  color: #797974;
  font-size: 10px;
}

.private-work-add-link,
.private-work-form-actions button,
.private-work-delivery-actions button {
  min-height: 42px;
  padding: 9px 13px;
  border: 1px solid #d5d5cf;
  border-radius: 11px;
  background: #fff;
  color: #292927;
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}

.private-work-selected-files {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.private-work-selected-files > span {
  max-width: 100%;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 9px;
  border-radius: 9px;
  background: #f0f0ec;
  font-size: 10px;
}

.private-work-selected-files b {
  max-width: 220px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.private-work-selected-files small { color: #777772; }
.private-work-selected-files button {
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font-size: 16px;
  cursor: pointer;
}

.private-work-link-inputs {
  display: grid;
  gap: 7px;
}

.private-work-link-inputs > div {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr) auto;
  gap: 6px;
}

.private-work-link-inputs button {
  width: 38px;
  border: 1px solid #deded8;
  border-radius: 10px;
  background: #fff;
  font-size: 18px;
  cursor: pointer;
}

.private-work-security-note {
  display: grid;
  gap: 4px;
  padding: 12px 13px;
  border: 1px solid #e8d7a9;
  border-radius: 12px;
  background: #fffaf0;
  color: #66501e;
  font-size: 11px;
  line-height: 1.5;
}

.private-work-confirmations {
  display: grid;
  gap: 9px;
}

.private-work-confirmations label,
.private-work-good-faith {
  display: flex !important;
  align-items: flex-start;
  gap: 8px;
  color: #4d4d48;
  font-size: 11px !important;
  font-weight: 600 !important;
  line-height: 1.45;
}

.private-work-confirmations input,
.private-work-good-faith input {
  width: 17px;
  height: 17px;
  flex: 0 0 17px;
  margin: 0;
}

.private-work-progress {
  height: 5px;
  overflow: hidden;
  border-radius: 999px;
  background: #e8e8e3;
}

.private-work-progress span {
  height: 100%;
  display: block;
  border-radius: inherit;
  background: #171717;
  transition: width .2s ease;
}

.private-work-form-message {
  margin: 0;
  color: #715f2c;
  font-size: 11px;
  line-height: 1.5;
}

.private-work-form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.private-work-form-actions button.is-primary,
.private-work-delivery-actions button.is-primary {
  border-color: #171717;
  background: #171717;
  color: #fff;
}

.private-work-form-actions button:disabled,
.private-work-delivery-actions button:disabled {
  cursor: wait;
  opacity: .5;
}

.private-work-delivery {
  display: grid;
  gap: 11px;
  margin: 12px 18px;
  padding: 16px;
  border: 1px solid #d9d9d3;
  border-left: 4px solid #b99a43;
  border-radius: 15px;
  background: #fffdf7;
}

.private-work-delivery.is-accepted { border-left-color: #3d8b62; background: #f7fcf8; }
.private-work-delivery.is-changes_requested { border-left-color: #ba6d36; }
.private-work-delivery.is-blocked { border-left-color: #a43f34; background: #fff8f6; }

.private-work-delivery-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.private-work-delivery-heading span,
.private-work-delivery-heading small {
  color: #767670;
  font-size: 10px;
  font-weight: 750;
  letter-spacing: .03em;
  text-transform: uppercase;
}

.private-work-delivery h3 { margin: 3px 0 0; font-size: 16px; }
.private-work-delivery > p { margin: 0; color: #4f4f4a; font-size: 12px; line-height: 1.55; }

.private-work-delivery blockquote {
  display: grid;
  gap: 4px;
  margin: 0;
  padding: 11px 12px;
  border: 0;
  border-radius: 10px;
  background: rgba(186, 109, 54, .1);
  color: #70401f;
  font-size: 12px;
  line-height: 1.5;
}

.private-work-delivery details summary { color: #686863; font-size: 11px; cursor: pointer; }
.private-work-delivery details p { display: grid; gap: 2px; margin: 8px 0 0; padding-left: 10px; border-left: 2px solid #ddddD6; font-size: 11px; }
.private-work-delivery details time { color: #85857f; font-size: 9px; }

.private-work-delivery-actions {
  display: grid;
  gap: 8px;
}

.private-work-delivery-actions > div {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.private-work-report-backdrop {
  position: fixed;
  z-index: 9999;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(12, 12, 12, .64);
}

.private-work-report-dialog {
  position: relative;
  width: min(620px, 100%);
  max-height: min(820px, calc(100vh - 40px));
  display: grid;
  gap: 14px;
  padding: 24px;
  overflow-y: auto;
  border-radius: 20px;
  background: #fff;
  color: #171717;
  box-shadow: 0 30px 90px rgba(0, 0, 0, .25);
}

.private-work-report-dialog h2,
.private-work-report-dialog p { margin: 0; }
.private-work-report-dialog > p { color: #686863; font-size: 12px; line-height: 1.55; }

.private-work-report-close {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 34px;
  height: 34px;
  border: 0;
  border-radius: 50%;
  background: #f0f0ec;
  font-size: 22px;
  cursor: pointer;
}

.moderation-private-evidence {
  display: grid;
  gap: 10px;
  margin-top: 12px;
  padding: 12px;
  border: 1px solid #e1d5ae;
  border-radius: 12px;
  background: #fffaf0;
}

.moderation-private-evidence > div:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.moderation-private-evidence small {
  color: #75683e;
  font-size: 9px;
}

.moderation-private-evidence blockquote {
  margin: 0;
  padding: 10px;
  border: 0;
  border-radius: 9px;
  background: rgba(255, 255, 255, .8);
  color: #3f3b2f;
  font-size: 11px;
  line-height: 1.55;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.moderation-private-evidence-items {
  display: grid !important;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 7px !important;
}

.moderation-private-evidence-items a {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px;
  border: 1px solid rgba(60, 50, 20, .12);
  border-radius: 9px;
  background: #fff;
  color: #29271f;
  text-decoration: none;
}

.moderation-private-evidence-items img {
  width: 46px !important;
  height: 46px !important;
  flex: 0 0 46px;
  border-radius: 7px !important;
  object-fit: cover;
}

.moderation-private-evidence-items span {
  width: 40px;
  flex: 0 0 40px;
  color: #766527;
  font-size: 9px;
  font-weight: 900;
  text-align: center;
}

.moderation-private-evidence-items b {
  min-width: 0;
  overflow: hidden;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

html[data-theme="dark"] .private-work-share,
html[data-theme="dark"] .private-work-report-dialog {
  background: #1c1c1a;
  color: #f4f4ef;
}

