@media (max-width: 700px) {
  .page {
    padding: 24px 12px 48px;
  }

  .app-page-header {
    margin-bottom: 30px;
  }

  .app-page-header h1 {
    letter-spacing: -2px;
  }

  :is(.project-form, .auth-card, .account-card, .job-card) {
    padding: 20px;
    border-radius: 20px;
  }

  .project-form {
    gap: 20px;
  }

  .job-actions,
  .job-details-actions {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

/* =========================================================
   COMPLETED JOBS & VERIFIED REVIEWS
========================================================= */

.private-work-completion {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px 16px;
  border: 1px solid #b9dfc8;
  border-radius: 15px;
  background: #effaf3;
  color: #174d2d;
}

.private-work-completion > span {
  display: grid;
  flex: 0 0 30px;
  width: 30px;
  height: 30px;
  place-items: center;
  border-radius: 50%;
  background: #267748;
  color: #fff;
  font-weight: 900;
}

.private-work-completion strong,
.private-work-completion p {
  display: block;
  margin: 0;
}

.private-work-completion p {
  margin-top: 3px;
  color: #38684a;
  font-size: 12px;
  line-height: 1.5;
}

.private-work-review-form,
.private-work-saved-review {
  display: grid;
  gap: 13px;
  padding: 18px;
  border: 1px solid #deded8;
  border-radius: 18px;
  background: #fff;
}

.private-work-review-form h3,
.private-work-review-form p,
.private-work-saved-review p {
  margin: 0;
}

.private-work-review-form h3 {
  margin-top: 4px;
  font-size: 20px;
  letter-spacing: -0.4px;
}

.private-work-review-form > div:first-child > p,
.private-work-review-status {
  color: #676761;
  font-size: 12px;
  line-height: 1.55;
}

.private-work-review-form label {
  color: #343431;
  font-size: 12px;
  font-weight: 800;
}

.private-work-review-form textarea {
  width: 100%;
  min-height: 112px;
  resize: vertical;
  box-sizing: border-box;
  border: 1px solid #d5d5cf;
  border-radius: 13px;
  background: #fff;
  color: #171717;
  padding: 13px 14px;
  outline: none;
  font: inherit;
  line-height: 1.55;
}

.private-work-review-form textarea:focus {
  border-color: #a68a35;
  box-shadow: 0 0 0 4px rgba(191, 157, 51, 0.13);
}

.private-work-review-form > button.is-primary {
  justify-self: start;
  min-height: 44px;
  padding: 10px 18px;
  border: 0;
  border-radius: 12px;
  background: #151515;
  color: #fff;
  font-weight: 850;
  cursor: pointer;
}

.private-work-review-form > button.is-primary:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.private-work-review-stars {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px;
}

.private-work-review-stars button {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  padding: 0;
  border: 1px solid #deded8;
  border-radius: 11px;
  background: #f7f7f4;
  color: #c7c7c0;
  font-size: 25px;
  line-height: 1;
  cursor: pointer;
}

.private-work-review-stars button:hover,
.private-work-review-stars button.is-active {
  border-color: #d0ac37;
  background: #fff9e8;
  color: #d5a400;
}

.private-work-review-stars > span {
  margin-left: 8px;
  color: #696963;
  font-size: 12px;
  font-weight: 750;
}

.private-work-saved-review-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.private-work-saved-review-heading > span,
.profile-rating-summary > span,
.profile-review-card-top > span {
  display: inline-flex;
  gap: 1px;
  color: #d2d2cb;
  font-size: 18px;
  letter-spacing: -1px;
}

.private-work-saved-review-heading b,
.profile-rating-summary b,
.profile-review-card-top b {
  color: inherit;
}

.private-work-saved-review-heading b.is-active,
.profile-rating-summary b.is-active,
.profile-review-card-top b.is-active {
  color: #d5a400;
}

.private-work-review-status {
  margin: 0;
  padding: 12px 14px;
  border-radius: 12px;
  background: #f3f3ef;
}

.profile-reviews-section {
  display: grid;
  gap: 18px;
  margin-top: 22px;
  padding: 24px;
  border: 1px solid #e1e1db;
  border-radius: 22px;
  background: #fff;
}

.profile-reviews-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
}

.profile-reviews-heading h2 {
  margin: 5px 0 0;
  color: #171717;
  font-size: clamp(22px, 3vw, 30px);
  letter-spacing: -1px;
}

.profile-rating-summary {
  display: grid;
  grid-template-columns: auto auto;
  align-items: center;
  justify-items: end;
  column-gap: 9px;
}

.profile-rating-summary > strong {
  color: #171717;
  font-size: 25px;
  letter-spacing: -0.8px;
}

.profile-rating-summary > small {
  grid-column: 1 / -1;
  color: #72726c;
  font-size: 11px;
}

.profile-reviews-list {
  display: grid;
  gap: 12px;
}

.profile-review-card {
  display: grid;
  gap: 12px;
  padding: 18px;
  border: 1px solid #e5e5df;
  border-radius: 17px;
  background: #fafaf8;
}

.profile-review-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.profile-review-card-top > div {
  display: grid;
  gap: 3px;
}

.profile-review-card-top strong {
  color: #20201e;
  overflow-wrap: anywhere;
}

.profile-review-card-top small,
.profile-review-card time {
  color: #777771;
  font-size: 10px;
}

.profile-review-card > p,
.profile-reviews-empty {
  margin: 0;
  color: #4d4d48;
  font-size: 13px;
  line-height: 1.65;
  overflow-wrap: anywhere;
}

.profile-reviews-empty {
  padding: 18px;
  border-radius: 15px;
  background: #f5f5f1;
  text-align: center;
}

html[data-theme="dark"] .private-work-completion {
  border-color: #2f6745;
  background: #17271d;
  color: #9fe0b7;
}

html[data-theme="dark"] .private-work-completion p {
  color: #9bc3a8;
}

html[data-theme="dark"] :is(.private-work-review-form, .private-work-saved-review, .profile-reviews-section) {
  border-color: #373733;
  background: #191918;
}

html[data-theme="dark"] .private-work-review-form h3,
html[data-theme="dark"] .private-work-review-form label,
html[data-theme="dark"] .profile-reviews-heading h2,
html[data-theme="dark"] .profile-rating-summary > strong,
html[data-theme="dark"] .profile-review-card-top strong {
  color: #f2f2ee;
}

html[data-theme="dark"] .private-work-review-form textarea {
  border-color: #41413c;
  background: #10100f;
  color: #f1f1ec;
}

html[data-theme="dark"] .private-work-review-stars button {
  border-color: #41413c;
  background: #252523;
  color: #60605a;
}

html[data-theme="dark"] .private-work-review-stars button:hover,
html[data-theme="dark"] .private-work-review-stars button.is-active {
  border-color: #8f7426;
  background: #2d2717;
  color: #e0b321;
}

html[data-theme="dark"] .private-work-review-status,
html[data-theme="dark"] .profile-reviews-empty {
  background: #242422;
  color: #bdbdb6;
}

html[data-theme="dark"] .profile-review-card {
  border-color: #343431;
  background: #141413;
}

html[data-theme="dark"] .profile-review-card > p {
  color: #ccccC5;
}

@media (max-width: 700px) {
  .private-work-review-form,
  .private-work-saved-review,
  .profile-reviews-section {
    padding: 16px;
  }

  .profile-reviews-heading,
  .profile-review-card-top {
    align-items: flex-start;
    flex-direction: column;
  }

  .profile-rating-summary {
    justify-items: start;
  }

  .private-work-review-stars button {
    width: 39px;
    height: 39px;
  }

  .private-work-review-stars > span {
    flex-basis: 100%;
    margin: 5px 0 0;
  }
}

/* =========================================================
   IDEA HIRE Ă˘ÂÂ COHESIVE UI REFRESH 2026-09
   Final, reversible presentation layer. No business logic.
========================================================= */

:root {
  --ih-ink: #171816;
  --ih-ink-soft: #5f625c;
  --ih-muted: #858980;
  --ih-line: #e4e5df;
  --ih-line-strong: #d6d8d0;
  --ih-surface: #ffffff;
  --ih-surface-soft: #f5f6f2;
  --ih-page: #f8f9f6;
  --ih-dark-surface: #181917;
  --ih-radius-sm: 11px;
  --ih-radius-md: 16px;
  --ih-radius-lg: 22px;
  --ih-shadow-sm: 0 8px 24px rgba(27, 29, 25, 0.055);
  --ih-shadow-md: 0 18px 54px rgba(27, 29, 25, 0.075);
  --ih-focus: rgba(38, 87, 214, 0.42);
}

body {
  color: var(--ih-ink);
  background: var(--ih-surface);
  font-feature-settings: "kern" 1, "liga" 1;
  -webkit-font-smoothing: antialiased;
}

/* Shared interactive rhythm */

.btn {
  min-height: 43px;
  padding: 11px 17px;
  border-radius: var(--ih-radius-sm);
  font-size: 13px;
  font-weight: 720;
  letter-spacing: -0.08px;
  box-shadow: none;
}

.btn:hover {
  transform: translateY(-1px);
}

.btn-dark:hover {
  background: #2a2b28;
  box-shadow: 0 9px 24px rgba(22, 23, 21, 0.14);
}

.btn-outline {
  border-color: var(--ih-line-strong);
  background: var(--ih-surface);
}

.btn-outline:hover,
.btn-ghost:hover {
  border-color: #c4c6be;
  background: #f2f3ef;
}

:is(a, button, input, textarea, select, summary):focus-visible {
  outline: 3px solid var(--ih-focus);
  outline-offset: 3px;
}

/* Public header Ă˘ÂÂ one calm surface instead of nested dark pills */

.navbar.home-navbar,
.navbar.account-navbar {
  width: min(1240px, calc(100% - 32px));
  min-height: 68px;
  box-sizing: border-box;
  margin: 14px auto 0;
  padding: 9px 11px;
  border: 1px solid rgba(218, 220, 212, 0.9);
  border-radius: 18px;
  background: rgba(255, 255, 253, 0.92);
  box-shadow: 0 10px 34px rgba(28, 30, 26, 0.055);
  backdrop-filter: blur(18px);
}

.home-navbar {
  display: grid;
  grid-template-columns: minmax(150px, 1fr) auto minmax(260px, 1fr);
  align-items: center;
  gap: 16px;
}

.home-navbar .logo {
  justify-self: start;
  padding-left: 7px;
  font-size: 22px;
}

.home-navbar .nav-links,
.home-nav-links {
  justify-self: center;
  gap: 2px;
  padding: 3px;
  border: 0;
  border-radius: 12px;
  background: var(--ih-surface-soft);
  box-shadow: none;
}

.home-navbar .nav-links a,
.home-nav-links a {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 13px;
  border-radius: 9px;
  color: #676a63;
  font-size: 12px;
  font-weight: 650;
}

.home-navbar .nav-links a:hover,
.home-nav-links a:hover {
  color: var(--ih-ink);
  background: var(--ih-surface);
  box-shadow: 0 3px 11px rgba(23, 24, 22, 0.06);
}

.home-navbar .nav-actions {
  width: auto;
  min-width: 0;
  justify-self: end;
  gap: 7px;
}

.home-navbar .home-account-cluster {
  width: auto;
  min-height: 0;
  display: flex;
  gap: 2px;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.home-navbar .home-account-cluster .auth-user {
  display: none;
}

.home-navbar .home-account-cluster .btn-ghost,
.home-navbar .nav-actions > .btn-ghost {
  min-height: 40px;
  padding: 9px 11px;
  border: 0;
  border-radius: 10px;
  color: #555851;
  background: transparent;
  font-size: 12px;
}

.home-navbar .home-account-cluster .btn-ghost:hover,
.home-navbar .nav-actions > .btn-ghost:hover {
  color: var(--ih-ink);
  background: var(--ih-surface-soft);
}

.home-navbar .nav-actions > .btn-dark {
  min-height: 40px;
  padding: 10px 15px;
  border-radius: 10px;
  font-size: 12px;
}

.home-navbar .home-account-avatar-link {
  display: none;
}

/* Account header Ă˘ÂÂ four primary destinations and one utility menu */

.navbar.account-navbar {
  display: grid;
  grid-template-columns: minmax(160px, 0.75fr) auto minmax(285px, 1fr);
  align-items: center;
  justify-content: stretch;
  gap: 14px;
}

.account-navbar .account-navbar-brand {
  min-width: 0;
  justify-content: flex-start;
  gap: 9px;
  transform: none !important;
}

.account-navbar .navbar-home-back {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  border-color: transparent;
  border-radius: 10px;
  background: var(--ih-surface-soft);
  box-shadow: none;
  color: #4d504a;
  font-size: 17px;
}

.account-navbar .navbar-home-back:hover {
  transform: translateX(-1px);
  border-color: var(--ih-line);
  background: #eef0eb;
  box-shadow: none;
}

.account-navbar .account-navbar-brand .logo {
  font-size: 21px;
}

.account-navbar .nav-links.account-primary-nav {
  min-width: 0;
  justify-self: center;
  gap: 2px;
  padding: 3px;
  border: 0;
  border-radius: 12px;
  background: var(--ih-surface-soft);
  box-shadow: none;
}

.account-navbar .nav-links.account-primary-nav a {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 12px;
  border-radius: 9px;
  color: #676a63;
  font-size: 12px;
  font-weight: 680;
}

.account-navbar .nav-links.account-primary-nav a:hover {
  color: var(--ih-ink);
  background: rgba(255, 255, 255, 0.68);
}

.account-navbar .nav-links.account-primary-nav a.is-active {
  color: var(--ih-ink);
  background: var(--ih-surface);
  box-shadow: 0 3px 12px rgba(25, 27, 23, 0.075);
}

.account-navbar .account-navbar-actions {
  min-width: 0;
  justify-self: end;
  gap: 7px;
}

.account-create-job-button,
.account-notification-button,
.account-mini {
  position: relative;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid transparent;
  text-decoration: none;
  transition:
    color 0.18s ease,
    background 0.18s ease,
    border-color 0.18s ease,
    box-shadow 0.18s ease,
    transform 0.18s ease;
}

.account-create-job-button {
  min-height: 40px;
  gap: 7px;
  padding: 9px 13px;
  border-radius: 10px;
  background: var(--ih-ink);
  color: #fff;
  font-size: 12px;
  font-weight: 760;
  white-space: nowrap;
}

.account-create-job-button > span:first-child {
  font-size: 18px;
  font-weight: 400;
  line-height: 0.8;
}

.account-create-job-button:hover,
.account-create-job-button.is-active {
  background: #2b2d29;
  box-shadow: 0 8px 20px rgba(24, 25, 23, 0.14);
  transform: translateY(-1px);
}

.account-notification-button {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  border-color: var(--ih-line);
  border-radius: 11px;
  background: var(--ih-surface);
  color: #4e514b;
}

.account-notification-button:hover,
.account-notification-button.is-active {
  border-color: var(--ih-line-strong);
  background: var(--ih-surface-soft);
  color: var(--ih-ink);
}

.account-notification-button svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.account-notification-button .notification-dot {
  position: absolute;
  top: 7px;
  right: 7px;
}

.account-menu {
  position: relative;
  z-index: 80;
}

.account-menu > summary {
  list-style: none;
}

.account-menu > summary::-webkit-details-marker {
  display: none;
}

.account-navbar .account-menu .account-mini {
  min-height: 40px;
  gap: 7px;
  padding: 3px 8px 3px 3px;
  border-color: var(--ih-line);
  border-radius: 12px;
  background: var(--ih-surface);
  box-shadow: none;
  cursor: pointer;
}

.account-navbar .account-menu .account-mini:hover,
.account-menu[open] > .account-mini {
  border-color: var(--ih-line-strong);
  background: var(--ih-surface-soft);
}

.account-navbar .account-menu .account-mini-avatar {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  border-radius: 9px;
  font-size: 11px;
}

.account-navbar .account-menu .account-mini-name {
  max-width: 105px;
  color: #3d403b;
  font-size: 11px;
  font-weight: 720;
}

.account-menu-caret {
  display: inline-grid;
  place-items: center;
  color: #8a8d85;
  font-size: 14px;
  line-height: 1;
  transition: transform 0.18s ease;
}

.account-menu[open] .account-menu-caret {
  transform: rotate(180deg);
}

.account-menu-alert-dot {
  position: absolute;
  top: -2px;
  right: -2px;
  width: 8px;
  height: 8px;
  border: 2px solid #fff;
  border-radius: 50%;
  background: #c84138;
}

.account-menu-dropdown {
  position: absolute;
  z-index: 90;
  top: calc(100% + 10px);
  right: 0;
  width: min(270px, calc(100vw - 28px));
  box-sizing: border-box;
  display: grid;
  gap: 3px;
  padding: 8px;
  border: 1px solid var(--ih-line);
  border-radius: 16px;
  background: rgba(255, 255, 253, 0.98);
  box-shadow: 0 22px 60px rgba(23, 25, 21, 0.16);
  backdrop-filter: blur(18px);
  transform-origin: top right;
  animation: account-menu-in 0.16s ease both;
}

@keyframes account-menu-in {
  from {
    opacity: 0;
    transform: translateY(-5px) scale(0.985);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.account-menu-identity {
  min-width: 0;
  display: grid;
  gap: 3px;
  margin: 2px 3px 7px;
  padding: 4px 5px 11px;
  border-bottom: 0;
}

.account-menu-identity strong,
.account-menu-identity span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.account-menu-identity strong {
  color: var(--ih-ink);
  font-size: 13px;
}

.account-menu-identity span {
  color: var(--ih-muted);
  font-size: 10px;
}

.account-menu-dropdown > a,
.account-menu-logout {
  width: 100%;
  min-height: 39px;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 11px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #41443e;
  font: inherit;
  font-size: 12px;
  font-weight: 650;
  text-align: left;
}

.account-menu-dropdown > a:hover,
.account-menu-dropdown > a.is-active,
.account-menu-logout:hover {
  background: var(--ih-surface-soft);
  color: var(--ih-ink);
}

.account-menu-notice-link .notification-dot,
.account-menu-dropdown .notification-dot {
  width: 7px;
  height: 7px;
  flex: 0 0 7px;
  background: #c84138;
  box-shadow: none;
}

.account-menu-divider {
  height: 1px;
  margin: 5px 4px;
  background: var(--ih-line);
}

.account-menu-logout {
  color: #9d3d37;
  cursor: pointer;
}

.account-menu-logout:hover {
  background: #fff2f0;
  color: #87342f;
}

/* Appearance and language Ă˘ÂÂ compact, horizontal and out of the way */

.site-preferences,
.site-preferences.is-open {
  top: auto;
  right: 16px;
  bottom: max(16px, env(safe-area-inset-bottom));
  transform: none;
  display: block;
  gap: 0;
  padding: 4px;
  border: 1px solid rgba(216, 218, 210, 0.95);
  border-radius: 13px;
  background: rgba(255, 255, 253, 0.94);
  box-shadow: 0 10px 30px rgba(25, 27, 23, 0.09);
  backdrop-filter: blur(16px);
}

.site-preferences-handle {
  display: none !important;
}

.site-preferences-panel {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 0;
}

.site-theme-toggle,
.site-language-toggle button {
  min-width: 32px;
  width: 32px;
  height: 32px;
  padding: 0;
  border-radius: 9px;
  font-size: 10px;
}

.site-theme-toggle {
  font-size: 17px;
}

.site-language-toggle {
  display: flex;
  gap: 2px;
  padding: 0 0 0 4px;
  border-top: 0;
  border-left: 1px solid var(--ih-line);
}

.site-language-toggle button.is-active {
  background: var(--ih-ink);
}

/* Homepage density and hierarchy */

.hero {
  min-height: 620px;
  padding: 78px 0 88px;
  gap: clamp(38px, 6vw, 76px);
}

.hero h1 {
  max-width: 720px;
  font-size: clamp(48px, 5.7vw, 74px);
  line-height: 0.99;
}

.hero-text {
  max-width: 540px;
  margin-top: 26px;
  font-size: 16px;
}

.hero-actions {
  margin-top: 27px;
}

.hero-stats {
  gap: 28px;
  margin-top: 42px;
}

.floating-card {
  border-color: var(--ih-line);
  box-shadow: 0 22px 64px rgba(24, 26, 22, 0.085);
}

.visual-glow {
  background: #f2f3ef;
}

.section {
  padding: 88px 0;
}

.section-heading {
  margin-bottom: 40px;
}

.section-heading.centered {
  margin-bottom: 44px;
}

.section-heading h2,
.split-card h2,
.final-cta h2 {
  letter-spacing: -2.2px;
}

.category-grid {
  gap: 10px;
}

.category-card {
  min-height: 104px;
  padding: 19px;
  border-color: var(--ih-line);
  border-radius: 16px;
  box-shadow: none;
}

.category-card:hover {
  transform: translateY(-2px);
  border-color: #cdd0c7;
  box-shadow: var(--ih-shadow-sm);
}

.steps {
  gap: 22px;
}

.step {
  padding: 24px 4px 0;
  border-color: var(--ih-line-strong);
}

.step h3 {
  margin-top: 22px;
}

.split-section {
  gap: 12px;
}

.split-card {
  min-height: 330px;
  padding: clamp(32px, 4vw, 46px);
  border-radius: var(--ih-radius-lg);
}

.split-card.light {
  border: 1px solid var(--ih-line);
  background: var(--ih-surface-soft);
}

.final-cta {
  margin-bottom: 26px;
  padding: 72px 50px;
  border-radius: 24px;
}

.footer {
  padding: 34px 0 46px;
}

/* Application pages Ă˘ÂÂ quieter surfaces and consistent spacing */

.page {
  min-height: 100vh;
  box-sizing: border-box;
  padding: 1px 20px 76px;
  background:
    radial-gradient(circle at 50% -180px, rgba(255, 255, 255, 0.96), transparent 460px),
    var(--ih-page);
}

.app-page {
  padding-top: clamp(48px, 6vw, 76px);
}

.app-page-header {
  margin-bottom: 34px;
}

.app-page-header .section-label,
.section-label {
  margin-bottom: 10px;
  color: #777b72;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.35px;
}

.app-page-header h1 {
  margin: 9px 0 13px;
  font-size: clamp(39px, 6vw, 64px);
  line-height: 1;
  letter-spacing: -2.7px;
}

.app-page-header p {
  max-width: 640px;
  color: var(--ih-ink-soft);
  font-size: 16px;
  line-height: 1.65;
}

:is(.account-card, .project-form, .job-card, .auth-card, .talent-controls, .talent-card) {
  border-color: var(--ih-line);
  border-radius: 20px;
  background: var(--ih-surface);
  box-shadow: var(--ih-shadow-sm);
}

.account-card {
  padding: clamp(24px, 4vw, 34px);
}

.project-form {
  padding: clamp(22px, 4vw, 32px);
  gap: 21px;
  box-shadow: var(--ih-shadow-sm);
}

.project-form :is(input, textarea, select),
.auth-form :is(input, textarea, select),
.account-form :is(input, textarea, select) {
  border-color: #dfe1da;
  border-radius: 12px;
  background-color: #fbfcf9;
}

.project-form :is(input, textarea, select):focus,
.auth-form :is(input, textarea, select):focus,
.account-form :is(input, textarea, select):focus {
  border-color: #8f9389;
  background-color: #fff;
  box-shadow: 0 0 0 4px rgba(61, 65, 57, 0.075);
}

.jobs-list {
  gap: 13px;
}

.job-card {
  padding: 24px;
  box-shadow: none;
}

.job-card:hover {
  transform: translateY(-1px);
  border-color: #d4d6cf;
  box-shadow: var(--ih-shadow-sm);
}

.job-card h2 {
  margin: 9px 0 9px;
  font-size: clamp(21px, 3vw, 25px);
}

.job-actions,
.job-details-actions {
  gap: 9px;
}

.job-actions .btn,
.job-details-actions .btn {
  min-height: 44px;
}

.talent-controls {
  margin-bottom: 22px;
  padding: 13px;
  box-shadow: none;
}

.talent-search-box {
  min-height: 52px;
  border-radius: 12px;
  background: #fbfcf9;
}

.talent-order-row {
  margin-top: 13px;
}

.talent-category-row {
  gap: 6px;
  margin-top: 13px;
}

.talent-category-row button,
.jobs-order-switch button {
  min-height: 34px;
  border-radius: 9px;
}

.talent-grid {
  gap: 13px;
}

.talent-card {
  padding: 21px;
  box-shadow: none;
}

.talent-card:hover {
  transform: translateY(-2px);
  border-color: #d2d5cc;
  box-shadow: var(--ih-shadow-sm);
}

/* Authentication Ă˘ÂÂ shorter, clearer and less card-heavy */

.auth-card {
  width: min(520px, 100%);
  margin: 36px auto;
  padding: clamp(26px, 5vw, 38px);
  border-radius: 22px;
  box-shadow: var(--ih-shadow-md);
}

.auth-card .logo {
  margin-bottom: 40px;
  font-size: 24px;
}

.auth-header h1 {
  margin: 8px 0;
  font-size: clamp(36px, 7vw, 44px);
  letter-spacing: -1.8px;
}

.auth-header p {
  color: var(--ih-ink-soft);
}

.auth-form {
  gap: 18px;
  margin-top: 28px;
}

.auth-footer {
  margin-top: 21px;
}

.google-auth-notice,
.registration-privacy-confirmation,
.registration-terms-confirmation {
  border-radius: 13px;
}

/* Nested account/profile areas should read as sections, not stacked cards */

:is(
  .profile-expertise-card,
  .profile-content-card,
  .profile-stat-card,
  .profile-specialties-field,
  .profile-skills-field,
  .profile-portfolio-manager,
  .profile-reviews-section,
  .discovery-settings-card,
  .privacy-entry-card
) {
  border-color: var(--ih-line);
  box-shadow: none;
}

.profile-preview {
  margin-bottom: 28px;
  padding-bottom: 26px;
}

.profile-stat-card {
  border-radius: 15px;
  background: #fafbf8;
}

.profile-specialties-field,
.profile-skills-field,
.profile-portfolio-manager,
.profile-reviews-section {
  border-radius: 18px;
}

.profile-portfolio-edit-card,
.profile-review-card {
  border-color: var(--ih-line);
  border-radius: 14px;
  background: #fafbf8;
}

/* Messages, notifications, disputes and privacy Ă˘ÂÂ consistent information density */

:is(.messages-row, .notification-decision-card, .notification-accepted-card, .notification-block-card) {
  border-color: var(--ih-line);
  border-radius: 16px;
  box-shadow: none;
}

.messages-row:hover {
  transform: none;
  border-color: #cfd2c9;
  background: #fafbf8;
}

.chat-shell {
  overflow: hidden;
  border-color: var(--ih-line);
  border-radius: 20px;
  box-shadow: var(--ih-shadow-sm);
}

.chat-header,
.chat-form {
  border-color: var(--ih-line);
}

.chat-messages {
  background: #fafbf8;
}

.chat-message.is-theirs {
  border: 1px solid var(--ih-line);
  background: #fff;
}

:is(
  .dispute-panel,
  .dispute-state-card,
  .privacy-request-card,
  .privacy-form-card,
  .privacy-user-audit-report,
  .privacy-audit-workspace,
  .moderation-appeal-card
) {
  border-color: var(--ih-line);
  border-radius: 18px;
  box-shadow: none;
}

/* Administrative navigation follows the same product language */

.admin-navbar {
  min-height: 70px;
  padding-block: 8px;
}

.admin-nav-links {
  gap: 3px;
  padding: 3px;
  border-color: var(--ih-line);
  border-radius: 12px;
  background: var(--ih-surface-soft);
  box-shadow: none;
}

.admin-nav-links a {
  min-height: 36px;
  padding: 8px 11px;
  border-radius: 9px;
  color: #666a62;
  font-size: 11px;
}

.admin-nav-links a:hover,
.admin-nav-links a.is-active {
  color: var(--ih-ink);
  background: #fff;
  box-shadow: 0 3px 11px rgba(24, 26, 22, 0.065);
}

/* Restricted account remains clear, but visually belongs to the same header */

.restricted-account-navbar {
  grid-template-columns: minmax(215px, 1fr) auto minmax(120px, 1fr);
  border-color: #ebd3d0 !important;
  background: rgba(255, 251, 250, 0.95) !important;
}

.restricted-account-navbar .restricted-navbar-links {
  border: 0;
  background: #fff2f0;
  box-shadow: none;
}

.restricted-account-navbar .restricted-navbar-links a {
  color: #7f514d;
}

.restricted-account-navbar .restricted-navbar-links a.is-active {
  color: #702f2a;
  background: #fff;
  box-shadow: 0 3px 11px rgba(91, 45, 40, 0.08);
}

/* Dark theme */

html[data-theme="dark"] {
  --ih-ink: #f0f1ec;
  --ih-ink-soft: #b2b5ad;
  --ih-muted: #858980;
  --ih-line: #32342f;
  --ih-line-strong: #41443d;
  --ih-surface: #191a18;
  --ih-surface-soft: #22231f;
  --ih-page: #0e0f0d;
  --ih-shadow-sm: 0 10px 28px rgba(0, 0, 0, 0.18);
  --ih-shadow-md: 0 22px 64px rgba(0, 0, 0, 0.28);
  --ih-focus: rgba(151, 180, 255, 0.55);
}

html[data-theme="dark"] .page {
  background:
    radial-gradient(circle at 50% -180px, rgba(41, 43, 38, 0.55), transparent 460px),
    var(--ih-page) !important;
}

html[data-theme="dark"] .navbar.home-navbar,
html[data-theme="dark"] .navbar.account-navbar {
  border-color: rgba(52, 55, 49, 0.96);
  background: rgba(20, 21, 19, 0.92);
  box-shadow: 0 12px 38px rgba(0, 0, 0, 0.22);
}

html[data-theme="dark"] .home-navbar .nav-links,
html[data-theme="dark"] .account-navbar .nav-links.account-primary-nav,
html[data-theme="dark"] .home-navbar .home-account-cluster {
  border: 0;
  background: #22231f;
  box-shadow: none;
}

html[data-theme="dark"] .home-navbar .home-account-cluster {
  background: transparent;
}

html[data-theme="dark"] .home-navbar .nav-links a,
html[data-theme="dark"] .account-navbar .nav-links.account-primary-nav a,
html[data-theme="dark"] .home-navbar .home-account-cluster .btn-ghost {
  color: #b7bab1 !important;
}

html[data-theme="dark"] .home-navbar .nav-links a:hover,
html[data-theme="dark"] .account-navbar .nav-links.account-primary-nav a:hover,
html[data-theme="dark"] .account-navbar .nav-links.account-primary-nav a.is-active,
html[data-theme="dark"] .home-navbar .home-account-cluster .btn-ghost:hover {
  color: #f3f4ef !important;
  background: #30322c !important;
  box-shadow: none;
}

html[data-theme="dark"] .account-navbar .navbar-home-back,
html[data-theme="dark"] .account-notification-button,
html[data-theme="dark"] .account-navbar .account-menu .account-mini {
  border-color: #343731;
  background: #20211e;
  color: #d7d9d2;
}

html[data-theme="dark"] .account-navbar .account-menu .account-mini:hover,
html[data-theme="dark"] .account-menu[open] > .account-mini,
html[data-theme="dark"] .account-notification-button:hover,
html[data-theme="dark"] .account-notification-button.is-active {
  border-color: #464941;
  background: #292b26;
}

html[data-theme="dark"] .account-navbar .account-menu .account-mini-name,
html[data-theme="dark"] .account-menu-identity strong {
  color: #eff0eb;
}

html[data-theme="dark"] .account-menu-alert-dot {
  border-color: #141513;
}

html[data-theme="dark"] .account-menu-dropdown {
  border-color: #383a35;
  background: rgba(24, 25, 23, 0.98);
  box-shadow: 0 24px 68px rgba(0, 0, 0, 0.42);
}

html[data-theme="dark"] .account-menu-dropdown > a,
html[data-theme="dark"] .account-menu-logout {
  color: #c6c9c0;
}

html[data-theme="dark"] .account-menu-dropdown > a:hover,
html[data-theme="dark"] .account-menu-dropdown > a.is-active {
  color: #f2f3ee;
  background: #292b26;
}

html[data-theme="dark"] .account-menu-logout {
  color: #e49a94;
}

html[data-theme="dark"] .account-menu-logout:hover {
  background: #332321;
  color: #f0aaa4;
}

html[data-theme="dark"] .site-preferences {
  border-color: #383a35;
  background: rgba(25, 26, 23, 0.95);
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.3);
}

html[data-theme="dark"] .site-language-toggle {
  border-left-color: #3b3d37;
}

html[data-theme="dark"] :is(
  .account-card,
  .project-form,
  .job-card,
  .auth-card,
  .talent-controls,
  .talent-card,
  .profile-expertise-card,
  .profile-content-card,
  .profile-stat-card,
  .profile-specialties-field,
  .profile-skills-field,
  .profile-portfolio-manager,
  .profile-reviews-section,
  .discovery-settings-card,
  .privacy-entry-card
) {
  border-color: var(--ih-line) !important;
  background: var(--ih-surface) !important;
  box-shadow: var(--ih-shadow-sm) !important;
}

html[data-theme="dark"] :is(
  .profile-stat-card,
  .profile-portfolio-edit-card,
  .profile-review-card,
  .talent-search-box,
  .chat-messages
) {
  border-color: var(--ih-line);
  background: #141513 !important;
}

html[data-theme="dark"] :is(.project-form, .auth-form, .account-form) :is(input, textarea, select) {
  border-color: #3b3d37 !important;
  background-color: #111210 !important;
}

html[data-theme="dark"] .restricted-account-navbar {
  border-color: #5e3a36 !important;
  background: rgba(39, 29, 27, 0.96) !important;
}

html[data-theme="dark"] .restricted-account-navbar .restricted-navbar-links {
  background: #332321;
}

html[data-theme="dark"] .restricted-account-navbar .restricted-navbar-links a {
  color: #dfaaa4 !important;
}

/* Tablet */

@media (max-width: 1120px) and (min-width: 721px) {
  .navbar.account-navbar {
    grid-template-columns: minmax(150px, 1fr) auto;
    grid-template-areas:
      "brand actions"
      "links links";
    gap: 8px 14px;
  }

  .account-navbar .account-navbar-brand {
    grid-area: brand;
  }

  .account-navbar .nav-links.account-primary-nav {
    width: 100%;
    grid-area: links;
    justify-content: center;
  }

  .account-navbar .account-navbar-actions {
    grid-area: actions;
  }
}

@media (max-width: 980px) and (min-width: 721px) {
  .home-navbar {
    grid-template-columns: auto minmax(0, 1fr) auto;
    grid-template-areas:
      "logo empty actions"
      "links links links";
    gap: 7px 14px;
  }

  .home-navbar .logo {
    grid-area: logo;
  }

  .home-navbar .nav-links {
    width: 100%;
    grid-area: links;
  }

  .home-navbar .nav-actions {
    grid-area: actions;
  }

  .home-navbar .nav-links a {
    flex: 1;
  }
}

/* Mobile */

@media (max-width: 720px) {
  .navbar.home-navbar,
  .navbar.account-navbar {
    width: calc(100% - 20px);
    min-height: 0;
    margin-top: 10px;
    padding: 8px;
    border-radius: 16px;
  }

  .home-navbar {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
      "logo actions"
      "links links";
    gap: 7px 10px;
  }

  .home-navbar .logo {
    grid-area: logo;
    margin: 0;
    padding-left: 4px;
    font-size: 20px;
  }

  .home-navbar .nav-links {
    width: 100%;
    grid-area: links;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 2px;
    padding: 3px !important;
    overflow: hidden;
  }

  .home-navbar .nav-links a,
  .home-navbar .nav-links a:first-child {
    width: 100%;
    min-width: 0;
    min-height: 34px;
    display: inline-flex;
    padding: 7px 5px !important;
    overflow: hidden;
    font-size: 10px !important;
    text-align: center;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .home-navbar .nav-actions {
    width: auto;
    grid-area: actions;
    display: flex;
    grid-template-columns: none;
    gap: 4px;
  }

  .home-navbar .nav-actions > a.btn-ghost {
    min-height: 36px;
    display: inline-flex !important;
    padding: 8px 9px;
    font-size: 10px;
  }

  .home-navbar .nav-actions > a.btn-dark {
    min-height: 36px;
    display: inline-flex !important;
    padding: 8px 10px;
    font-size: 10px;
  }

  .home-navbar .home-account-cluster,
  .home-navbar .nav-actions > button.btn-dark {
    display: none !important;
  }

  .home-navbar .home-account-avatar-link {
    width: 36px;
    height: 36px;
    flex: 0 0 36px;
    display: grid;
    border-color: var(--ih-line);
    background: var(--ih-surface);
    box-shadow: none;
  }

  .navbar.account-navbar {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
      "brand actions"
      "links links";
    gap: 7px 9px;
  }

  .account-navbar .account-navbar-brand {
    grid-area: brand;
  }

  .account-navbar .account-navbar-brand .logo {
    font-size: 19px;
  }

  .account-navbar .navbar-home-back {
    width: 32px;
    height: 32px;
    flex-basis: 32px;
  }

  .account-navbar .nav-links.account-primary-nav {
    width: 100%;
    grid-area: links;
    display: grid;
    grid-template-columns: none;
    grid-auto-flow: column;
    grid-auto-columns: minmax(0, 1fr);
    gap: 2px;
    padding: 3px !important;
    overflow: hidden;
  }

  .account-navbar .nav-links.account-primary-nav a {
    width: 100%;
    min-width: 0;
    min-height: 34px;
    padding: 7px 4px !important;
    overflow: hidden;
    font-size: 10px !important;
    text-align: center;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .account-navbar .account-navbar-actions {
    grid-area: actions;
    gap: 5px;
  }

  .account-create-job-button {
    width: 36px;
    height: 36px;
    min-height: 36px;
    flex: 0 0 36px;
    padding: 0;
    border-radius: 10px;
  }

  .account-create-job-button > span:first-child {
    font-size: 21px;
  }

  .account-create-job-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }

  .account-notification-button {
    width: 36px;
    height: 36px;
    flex-basis: 36px;
  }

  .account-navbar .account-menu .account-mini {
    width: 36px;
    min-width: 36px;
    min-height: 36px;
    padding: 2px;
    border-radius: 10px;
  }

  .account-navbar .account-menu .account-mini-avatar {
    width: 30px;
    height: 30px;
    flex-basis: 30px;
    border-radius: 8px;
  }

  .account-navbar .account-menu .account-mini-name,
  .account-menu-caret {
    display: none;
  }

  .account-menu-dropdown {
    top: calc(100% + 9px);
    right: 0;
  }

  .site-preferences,
  .site-preferences.is-open {
    right: 10px;
    bottom: max(10px, env(safe-area-inset-bottom));
    transform: none;
    padding: 3px;
    border-right: 1px solid rgba(216, 218, 210, 0.95);
    border-radius: 12px;
  }

  .site-theme-toggle,
  .site-language-toggle button {
    width: 30px;
    min-width: 30px;
    height: 30px;
  }

  .page {
    padding: 1px 10px 62px;
  }

  .app-page {
    padding-top: 38px;
  }

  .app-page-header {
    margin-bottom: 26px;
  }

  .app-page-header h1 {
