    gap: 42px;
  }

  .hero h1 {
    font-size: clamp(42px, 13vw, 60px);
    letter-spacing: -3px;
  }

  .hero-text {
    font-size: 15px;
  }

  .hero-stats {
    gap: 18px;
    margin-top: 35px;
  }

  .section {
    padding: 68px 0;
  }

  .section-heading {
    gap: 20px;
    margin-bottom: 30px;
  }

  .category-grid,
  .split-section {
    gap: 9px;
  }

  .category-card {
    min-height: 88px;
