}

.site-language-toggle button.is-active {
  background: var(--ih-violet);
  color: #fff;
}

/* ---------- LOAD AND SCROLL MOTION ---------- */

@keyframes ih-v3-hero-copy {
  from {
    opacity: 0;
    transform: translateY(18px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes ih-v3-hero-visual {
  from {
    opacity: 0;
    transform: translateY(22px) scale(0.97);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes ih-v3-morph {
  0% {
    border-radius: 45% 55% 62% 38% / 43% 39% 61% 57%;
    transform: rotate(0deg) scale(1);
  }

  100% {
    border-radius: 62% 38% 44% 56% / 55% 62% 38% 45%;
    transform: rotate(18deg) scale(1.06);
  }
}

@keyframes ih-v3-orb {
  0% {
    border-radius: 40% 60% 60% 40% / 46% 40% 60% 54%;
    transform: rotate(-3deg) scale(0.98);
  }

  100% {
    border-radius: 61% 39% 43% 57% / 56% 61% 39% 44%;
    transform: rotate(7deg) scale(1.04);
  }
}

@keyframes ih-v3-pulse {
  0%,
  100% {
    box-shadow: 0 0 0 4px rgba(83, 213, 179, 0.12);
  }

  50% {
    box-shadow: 0 0 0 8px rgba(83, 213, 179, 0.04);
  }
}

@keyframes ih-v3-float-top {
  0%,
  100% {
    transform: translateY(0) rotate(0.3deg);
  }

  50% {
    transform: translateY(-11px) rotate(-0.5deg);
  }
}

@keyframes ih-v3-float-bottom {
  0%,
  100% {
    transform: translateY(0) rotate(-0.4deg);
  }

  50% {
    transform: translateY(10px) rotate(0.5deg);
  }
}

@keyframes ih-v3-reveal {
  from {
    opacity: 0;
    transform: translateY(24px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@supports (animation-timeline: view()) {
  .categories .section-heading,
  .category-card,
  .how .section-heading,
  .how .step,
  .split-card,
  .final-cta {
    animation: ih-v3-reveal both;
    animation-timeline: view();
    animation-range: entry 5% cover 26%;
  }
}

