:root {
  --ih-release: 20260919-2;
  --ih-v4-surface: #ffffff;
  --ih-v4-surface-muted: #f8f9f6;
  --ih-v4-line: #e2e5de;
  --ih-v4-line-strong: #d5d9d0;
  --ih-v4-ink: #191b18;
  --ih-v4-copy: #656a62;
  --ih-v4-violet: #6c5ce7;
  --ih-v4-violet-soft: #f1efff;
  --ih-v4-mint: #53d5b3;
  --ih-v4-shadow: 0 18px 55px rgba(25, 27, 23, 0.07);
}

/* ---------- CONSISTENT APPLICATION CANVAS ---------- */

.page > .app-page,
.account-page > .app-page,
.account-page > .messages-page {
  width: min(1180px, calc(100% - 40px));
  box-sizing: border-box;
  margin-inline: auto;
}

.page > .app-page,
.account-page > .app-page {
  padding-bottom: 92px;
}

.app-page-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(240px, 390px);
  align-items: end;
  gap: 32px;
  max-width: none;
  margin-bottom: 30px;
  padding-bottom: 25px;
  border-bottom: 0;
}

.app-page-header > .section-label,
.app-page-header > h1 {
  grid-column: 1;
}

.app-page-header > h1 {
  margin-bottom: 0;
}

.app-page-header > p {
  grid-column: 2;
  grid-row: 1 / span 2;
  align-self: end;
  margin: 0 0 5px;
  padding-left: 25px;
  border-left: 1px solid var(--ih-v4-line);
  line-height: 1.72;
}

.account-page-heading {
  margin-bottom: 18px;
}

:is(
  .account-card,
  .project-form,
  .jobs-search,
  .talent-controls,
  .messages-list,
  .messages-empty,
  .chat-shell,
  .privacy-entry-card,
  .dispute-panel,
  .dispute-state-card
) {
  border-color: var(--ih-v4-line);
}

:is(button, a, input, textarea, select):focus-visible {
  outline: 3px solid rgba(108, 92, 231, 0.22);
  outline-offset: 3px;
}

/* ---------- ACCOUNT: SECTIONED, SCANNABLE WORKSPACE ---------- */

.account-section-nav {
  position: sticky;
  z-index: 35;
  top: 84px;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
  margin: 0 0 18px;
  padding: 7px;
  border: 1px solid rgba(218, 221, 213, 0.92);
  border-radius: 17px;
  background: rgba(255, 255, 253, 0.88);
  box-shadow: 0 14px 38px rgba(25, 27, 23, 0.075);
