/* ---------- LOWER HOMEPAGE: POLISHED AMBIENT MOTION ---------- */

@keyframes ih-v4-process-rings {
  0%,
  100% {
    transform: translate3d(0, 0, 0) rotate(0deg) scale(1);
    opacity: 0.72;
  }

  50% {
    transform: translate3d(-24px, 18px, 0) rotate(9deg) scale(1.06);
    opacity: 1;
  }
}

@keyframes ih-v4-path-glow {
  0% {
    background-position: -180% 0;
  }

  100% {
    background-position: 280% 0;
  }
}

@keyframes ih-v4-orbit {
  0%,
  100% {
    transform: rotate(-18deg) translate3d(0, 0, 0);
  }

  50% {
    transform: rotate(-8deg) translate3d(-17px, -12px, 0) scale(1.05);
  }
}

@keyframes ih-v4-cta-orbit-left {
  0%,
  100% {
    transform: translate3d(0, 0, 0) scale(1);
  }

  50% {
    transform: translate3d(28px, 17px, 0) scale(1.08);
  }
}

@keyframes ih-v4-cta-orbit-right {
  0%,
  100% {
    transform: translate3d(0, 0, 0) scale(1);
  }

  50% {
    transform: translate3d(-34px, -21px, 0) scale(0.94);
  }
}

@keyframes ih-v4-card-breathe {
  0%,
  100% {
    box-shadow: 0 25px 70px rgba(24, 24, 29, 0.13);
  }

  50% {
    box-shadow: 0 31px 82px rgba(61, 49, 148, 0.19);
  }
}

.app > main > .how.section::before {
  animation: ih-v4-process-rings 12s ease-in-out infinite;
}

.how .steps::before {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(169, 157, 255, 0.18) 18%,
    rgba(255, 255, 255, 0.9) 42%,
    rgba(83, 213, 179, 0.72) 55%,
    rgba(169, 157, 255, 0.18) 82%,
    transparent 100%
  );
  background-size: 220% 100%;
  animation: ih-v4-path-glow 7s linear infinite;
}

.how .step:nth-child(2) {
  animation-delay: -1.8s;
}

.how .step:nth-child(3) {
  animation-delay: -3.6s;
}

.split-card {
  animation: ih-v4-card-breathe 8s ease-in-out infinite;
}

.split-card.light {
  animation-delay: -4s;
}

.split-card::after {
  animation: ih-v4-orbit 11s ease-in-out infinite;
}

.split-card.light::after {
  animation-delay: -5.5s;
}

.split-card:hover::after {
  animation-duration: 5s;
}

.final-cta::before {
  animation: ih-v4-cta-orbit-left 13s ease-in-out infinite;
}

.final-cta::after {
  animation: ih-v4-cta-orbit-right 15s ease-in-out infinite;
}

.final-cta .btn {
  transition: transform 0.22s ease, box-shadow 0.22s ease;
}

.final-cta .btn:hover {
  transform: translateY(-3px);
  box-shadow: 0 18px 38px rgba(0, 0, 0, 0.24);
}

.app > .footer {
  position: relative;
  overflow: hidden;
}

.app > .footer::before {
  content: "";
  position: absolute;
  top: -1px;
  left: -32%;
  width: 32%;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--ih-v4-violet), var(--ih-v4-mint), transparent);
  animation: ih-v4-footer-line 8s ease-in-out infinite;
}

@keyframes ih-v4-footer-line {
  0% {
    left: -32%;
  }

  100% {
    left: 100%;
  }
}

