  --ih-shadow-lg: 0 32px 90px rgba(4, 11, 20, 0.16);
}

html {
  overflow-y: scroll;
  scrollbar-gutter: stable both-edges;
  background: var(--ih-canvas);
}

body,
#root {
  min-width: 0;
  min-height: 100%;
  background: var(--ih-canvas);
}

body {
  color: var(--ih-ink);
}

.app,
.page,
.account-page,
.privacy-center-page,
.disputes-page,
.admin-page,
.moderation-user-page {
  min-height: 100vh;
  background: var(--ih-canvas) !important;
}

.page:not(:has(> .auth-card)),
html[data-theme="dark"] .page:not(:has(> .auth-card)) {
  background: var(--ih-canvas) !important;
}

/* One width and one horizontal axis everywhere. */

.navbar.home-navbar,
.navbar.account-navbar,
.navbar.admin-navbar,
.navbar.restricted-navbar,
.app > main > .hero,
.app > main > .section,
.app > main > .how.section,
.app > main > .split-section.section,
.app > main > .final-cta,
.app > .footer,
.page > .app-page,
.account-page > .app-page,
.account-page > .messages-page,
.account-page > .chat-page,
.privacy-center-shell,
.disputes-shell,
.age-access-shell,
.admin-shell,
.moderation-user-shell,
.limited-account-shell {
  width: min(var(--ih-shell-width), calc(100% - var(--ih-shell-gutter))) !important;
  max-width: var(--ih-shell-width) !important;
  box-sizing: border-box;
  margin-right: auto !important;
  margin-left: auto !important;
}

.page > .app-page,
.account-page > .app-page,
.account-page > .messages-page,
.account-page > .chat-page,
.privacy-center-shell,
.disputes-shell,
.age-access-shell,
.admin-shell,
.moderation-user-shell,
.limited-account-shell {
  padding-top: 48px;
  padding-bottom: 88px;
}

@keyframes ih-v5-page-in {
  from {
    opacity: 0;
    transform: translateY(7px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.page > main,
.account-page > main,
.app > main > section,
.privacy-center-shell,
.disputes-shell,
.admin-shell {
  animation: ih-v5-page-in 0.32s cubic-bezier(0.22, 1, 0.36, 1) both;
}

