  background: var(--ih-navy-900);
}

.account-page .messages-overview strong,
.account-page .messages-overview span {
  color: #fff;
}

.account-page .messages-overview span {
  opacity: 0.65;
}

.account-page .messages-list {
  overflow: hidden;
  border-radius: 15px !important;
}

.account-page .messages-list-header {
  min-height: 38px;
  padding-left: 86px;
  border-color: var(--ih-line);
