  color: #747d88;
}

.account-page .messages-row {
  min-height: 86px;
  grid-template-columns: 50px minmax(0, 1fr) 92px;
  padding: 15px 18px;
  border-color: #e8ebef;
  background: #fff !important;
}

.account-page .messages-row:hover {
  background: #f6f8fb !important;
  box-shadow: inset 3px 0 0 var(--ih-navy-700);
}

.account-page .messages-avatar {
  width: 50px;
  height: 50px;
  border-radius: 12px;
}

.account-page .messages-date {
  background: #edf0f4;
  color: #68717c;
}

.page .notification-decision-card,
.page .notification-accepted-card,
.page .notification-block-card,
.page .notification-card,
.page .account-card.notification-decision-card,
.page .account-card.notification-accepted-card,
.page .account-card.notification-block-card {
  border-color: var(--ih-line) !important;
  background: #fff !important;
}

.page .notification-decision-icon,
.page .notification-accepted-icon,
.page .notification-block-icon {
  border-radius: 10px !important;
  background: #edf1f6 !important;
  color: var(--ih-navy-700) !important;
}

.page .notification-clear-button {
  border-color: var(--ih-line-strong) !important;
  border-radius: 9px !important;
  background: #fff !important;
  color: var(--ih-navy-800) !important;
}

.account-page > .chat-page {
  margin-top: 0 !important;
}

.account-page .chat-shell {
  min-height: calc(100vh - 150px);
  border-radius: 16px !important;
}

.account-page .chat-header {
  min-height: 72px;
  padding: 14px 17px;
  border-color: var(--ih-line);
  background: #fff;
}

.account-page .chat-avatar {
  border-radius: 11px;
  background: var(--ih-navy-900);
  color: #fff;
}

.account-page .chat-messages {
  min-height: 440px;
  padding: 22px;
  background:
