}

.account-page .chat-message.is-mine {
  border-color: var(--ih-navy-800);
  background: var(--ih-navy-900);
  color: #fff;
}

.account-page .chat-message.is-theirs {
  border-color: var(--ih-line);
  background: #fff;
}

.account-page .chat-form {
  border-color: var(--ih-line);
  background: #fff;
}

/* ---------- PRIVACY / DISPUTES / ADMIN ---------- */

.privacy-center-header,
.disputes-page-header,
.admin-page-header {
  grid-template-columns: minmax(0, 1fr) auto;
}

.privacy-center-header > div > p,
.disputes-page-header > div > p,
.admin-page-header > div > p {
