}

.hero-stats {
  border-color: rgba(255, 255, 255, 0.12);
}

.hero-stats div {
  border-color: rgba(255, 255, 255, 0.12);
}

.hero-stats strong {
  color: #fff !important;
}

.hero-stats span {
  color: #909baa !important;
}

.hero-visual .visual-glow {
  background: radial-gradient(circle, rgba(60, 105, 174, 0.42), rgba(12, 29, 49, 0.03) 68%);
}

.hero-visual .floating-card {
  border-color: rgba(255, 255, 255, 0.11) !important;
  background: rgba(255, 255, 255, 0.94) !important;
  box-shadow: 0 28px 70px rgba(0, 0, 0, 0.26) !important;
}

.hero-visual .card-main::before {
