}

.hero-visual .card-main h3,
.hero-visual .card-small strong {
  color: var(--ih-ink) !important;
}

.hero-visual .live-dot,
.hero-visual .mini-icon,
.hero-visual .check-icon {
  color: var(--ih-blue-600) !important;
}

.app > main > .section {
  padding-top: 90px;
  padding-bottom: 90px;
}

.app > main > .section .section-heading h2,
.split-card h2,
.final-cta h2 {
  color: var(--ih-ink);
