}

.category-grid {
  gap: 9px;
}

.category-card,
.category-card:nth-child(n) {
  min-height: 126px;
  border-color: var(--ih-line) !important;
  border-radius: 14px;
  background: #fff !important;
  box-shadow: none;
}

.category-card::before,
.category-card:nth-child(n)::before {
  width: 126px;
  height: 126px;
  background: rgba(16, 36, 61, 0.055) !important;
}

.category-card:hover {
  border-color: #bcc5d0 !important;
  box-shadow: var(--ih-shadow-md);
}

.category-number,
.category-arrow {
  border-color: var(--ih-line);
  background: #f1f3f6;
  color: var(--ih-navy-700);
}

.category-name {
  color: var(--ih-ink);
}

.app > main > .how.section {
  margin-top: 8px !important;
  margin-bottom: 8px !important;
  padding: 70px 52px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 20px;
  background:
    radial-gradient(circle at 92% 4%, rgba(62, 108, 177, 0.25), transparent 27%),
    var(--ih-navy-950) !important;
  box-shadow: var(--ih-shadow-lg);
}

.app > main > .how.section::before {
  border-color: rgba(255, 255, 255, 0.09);
