}

.app > main > .how .section-heading .section-label {
  color: #91b2ff;
}

.how .step {
  min-height: 220px;
  border-color: rgba(255, 255, 255, 0.09);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.045);
}

.how .step:hover {
  border-color: rgba(145, 178, 255, 0.3);
  background: rgba(255, 255, 255, 0.07);
}

.how .step > span {
  border-color: rgba(255, 255, 255, 0.13);
  border-radius: 10px;
  background: rgba(71, 112, 174, 0.32);
}

.how .steps::before {
  background: linear-gradient(90deg, transparent, rgba(145, 178, 255, 0.28), #fff, rgba(145, 178, 255, 0.28), transparent);
}

.app > main > .split-section.section {
  gap: 10px;
  padding-top: 78px;
  padding-bottom: 78px;
}

.split-card,
.split-card.light,
html[data-theme="dark"] .split-card.light {
  min-height: 345px;
  border: 1px solid var(--ih-line) !important;
  border-radius: 16px;
  background: #fff !important;
  box-shadow: var(--ih-shadow-sm) !important;
}

.split-card:first-child {
  border-color: rgba(255, 255, 255, 0.08) !important;
  background: var(--ih-navy-900) !important;
}

.split-card:first-child h2 {
  color: #fff !important;
}

.split-card:first-child p {
  color: #aeb8c5 !important;
}

.split-card:first-child .section-label {
  color: #91b2ff;
}

.split-card.light h2 {
  color: var(--ih-ink) !important;
}

.split-card.light p {
  color: var(--ih-copy) !important;
}

.split-card::after {
  border-color: rgba(145, 178, 255, 0.16);
  box-shadow: 0 0 0 34px rgba(145, 178, 255, 0.025);
}

.split-card.light::after {
  border-color: rgba(16, 36, 61, 0.1);
  box-shadow: 0 0 0 34px rgba(16, 36, 61, 0.025);
