.app > main > .final-cta {
  margin-bottom: 24px !important;
  padding: 72px 40px;
  border-color: rgba(255, 255, 255, 0.08);
  border-radius: 20px;
  background:
    radial-gradient(circle at 84% 80%, rgba(61, 108, 178, 0.35), transparent 34%),
