  box-shadow: var(--ih-shadow-lg);
}

.final-cta .section-label {
  color: #91b2ff;
}

.final-cta h2 {
  color: #fff;
}

.final-cta .btn-light {
  color: var(--ih-navy-900);
  background: #fff;
}

.final-cta::before,
.final-cta::after {
  border-color: rgba(255, 255, 255, 0.09);
}

.app > .footer {
  padding: 32px 0 42px;
  border-color: var(--ih-line);
}

.app > .footer::before {
  background: linear-gradient(90deg, transparent, var(--ih-navy-700), #7da5e7, transparent);
}

.footer .logo,
.footer .logo span {
  color: var(--ih-ink) !important;
}

.footer-links a {
  color: #68717d;
}

.footer-links a:hover {
  color: var(--ih-navy-800);
}

/* ---------- DARK MODE: BLACK / NAVY, SAME GEOMETRY ---------- */

html[data-theme="dark"] {
  --ih-ink: #f4f6f9;
  --ih-copy: #aab3bf;
  --ih-muted: #7f8996;
  --ih-canvas: #070b11;
  --ih-surface: #0d131c;
  --ih-surface-soft: #101823;
  --ih-line: #222c38;
  --ih-line-strong: #303c4a;
  --ih-blue-100: rgba(72, 118, 188, 0.16);
  --ih-shadow-sm: 0 10px 30px rgba(0, 0, 0, 0.2);
  --ih-shadow-md: 0 20px 55px rgba(0, 0, 0, 0.3);
}

html[data-theme="dark"],
html[data-theme="dark"] body,
html[data-theme="dark"] #root,
html[data-theme="dark"] .app,
html[data-theme="dark"] .page,
html[data-theme="dark"] .account-page,
html[data-theme="dark"] .privacy-center-page,
html[data-theme="dark"] .disputes-page,
html[data-theme="dark"] .admin-page {
  background: var(--ih-canvas) !important;
}

html[data-theme="dark"] .navbar.home-navbar,
html[data-theme="dark"] .navbar.account-navbar,
html[data-theme="dark"] .navbar.admin-navbar,
html[data-theme="dark"] .navbar.restricted-navbar {
  border-color: var(--ih-line);
  background: rgba(12, 18, 27, 0.94) !important;
}

html[data-theme="dark"] .navbar .logo,
html[data-theme="dark"] .navbar .logo span {
  color: #fff !important;
}

html[data-theme="dark"] :is(
  .account-card,
  .project-form,
  .job-card,
  .talent-controls,
  .talent-card,
  .messages-list,
  .messages-empty,
  .chat-shell,
  .privacy-entry-card,
  .privacy-request-form-card,
  .privacy-request-card,
  .privacy-trust-panel,
  .dispute-panel,
  .dispute-state-card,
  .dispute-list-card,
  .moderation-appeal-card,
  .admin-card,
  .account-form-section,
  .account-profile-workspace > .profile-portfolio-manager,
  .discovery-settings-card,
  .job-republication-panel,
  .my-jobs-section
) {
  border-color: var(--ih-line) !important;
  background: var(--ih-surface) !important;
  color: var(--ih-ink);
}

html[data-theme="dark"] :is(input, textarea, select),
html[data-theme="dark"] .profile-category-option,
html[data-theme="dark"] .page .jobs-filter,
html[data-theme="dark"] .page .talent-category-row button,
html[data-theme="dark"] .btn-outline,
html[data-theme="dark"] .privacy-secondary-button,
html[data-theme="dark"] .dispute-secondary-button,
html[data-theme="dark"] .privacy-entry-link {
  border-color: var(--ih-line-strong) !important;
  background: var(--ih-surface-soft) !important;
  color: #d9dfe7 !important;
}

html[data-theme="dark"] .page .jobs-filter.active,
html[data-theme="dark"] .page .talent-category-row button.is-active,
html[data-theme="dark"] .jobs-order-switch button.is-active {
  border-color: #e9edf3 !important;
  background: #e9edf3 !important;
  color: var(--ih-navy-950) !important;
}

html[data-theme="dark"] .account-section-nav,
html[data-theme="dark"] .disputes-filter-bar,
html[data-theme="dark"] .jobs-order-switch {
  border-color: var(--ih-line);
  background: rgba(13, 19, 28, 0.96);
}

html[data-theme="dark"] .account-form-section .profile-specialties-field,
html[data-theme="dark"] .account-form-section .profile-skills-field,
html[data-theme="dark"] .profile-portfolio-editor,
html[data-theme="dark"] .profile-portfolio-edit-card,
html[data-theme="dark"] .jobs-order-panel,
html[data-theme="dark"] .talent-order-row,
html[data-theme="dark"] .account-form-actions,
html[data-theme="dark"] .messages-list-header,
html[data-theme="dark"] .messages-date {
  border-color: var(--ih-line);
  background: var(--ih-surface-soft) !important;
}

html[data-theme="dark"] .account-page .messages-row,
html[data-theme="dark"] .account-page .chat-header,
html[data-theme="dark"] .account-page .chat-form {
  border-color: var(--ih-line);
  background: var(--ih-surface) !important;
}

html[data-theme="dark"] .account-page .messages-row:hover {
  background: #111b28 !important;
}

html[data-theme="dark"] .account-page .chat-messages {
  background:
    linear-gradient(rgba(126, 166, 255, 0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(126, 166, 255, 0.025) 1px, transparent 1px),
    #080d14;
  background-size: 26px 26px;
}

html[data-theme="dark"] .category-card,
html[data-theme="dark"] .category-card:nth-child(n),
html[data-theme="dark"] .split-card.light {
  border-color: var(--ih-line) !important;
  background: var(--ih-surface) !important;
}

html[data-theme="dark"] .category-name,
html[data-theme="dark"] .split-card.light h2,
html[data-theme="dark"] .footer .logo,
html[data-theme="dark"] .footer .logo span {
  color: #fff !important;
}

/* ---------- RESPONSIVE, WITHOUT AXIS CHANGES ---------- */

@media (max-width: 1120px) {
  :root {
    --ih-shell-gutter: 28px;
  }

  .navbar.account-navbar {
    padding-left: 12px;
  }

  .account-navbar-brand {
    min-width: 145px;
  }

  .account-navbar .nav-links.account-primary-nav {
    grid-auto-columns: 82px;
  }

  .account-navbar .nav-links.account-primary-nav a {
    width: 82px;
    font-size: 10px;
  }

  .account-navbar .account-navbar-actions {
    min-width: 261px;
  }

  .account-create-job-button {
    min-width: 116px;
  }

  .account-navbar .account-menu .account-mini {
    width: 124px;
  }

  .app > main > .hero {
    padding: 56px 44px;
  }
}

@media (max-width: 900px) {
  .account-navbar .account-navbar-brand .logo,
  .account-navbar .account-mini-name,
  .account-create-job-label {
    display: none;
  }

  .account-navbar-brand {
    min-width: 38px;
  }

  .account-navbar .account-navbar-actions {
    min-width: 94px;
  }

  .account-create-job-button {
    min-width: 42px;
    width: 42px;
    padding: 0;
  }

  .account-navbar .account-menu .account-mini {
    width: 42px;
    padding: 3px;
  }

  .account-menu-caret {
    display: none;
  }

  .app-page-header,
  .privacy-center-header,
  .disputes-page-header,
  .admin-page-header,
  .account-page .messages-heading {
    grid-template-columns: minmax(0, 1fr) 290px;
    gap: 24px;
  }

  .page .jobs-filter-row,
  .page .talent-category-row {
    grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
  }
}

@media (max-width: 720px) {
  :root {
    --ih-shell-gutter: 18px;
  }

  html {
    overflow-y: auto;
    scrollbar-gutter: auto;
  }

  .navbar.home-navbar,
  .navbar.account-navbar,
  .navbar.admin-navbar,
  .navbar.restricted-navbar {
    top: 7px;
    min-height: 58px;
    margin-top: 7px !important;
    border-radius: 12px;
  }

  .page > .app-page,
  .account-page > .app-page,
  .account-page > .messages-page,
  .account-page > .chat-page,
  .privacy-center-shell,
  .disputes-shell,
  .age-access-shell,
  .admin-shell,
  .moderation-user-shell,
  .limited-account-shell {
    padding-top: 34px;
    padding-bottom: 64px;
  }

  .app-page-header,
  .privacy-center-header,
  .disputes-page-header,
  .admin-page-header,
  .account-page .messages-heading {
    min-height: 0;
    display: block;
    margin-bottom: 18px;
    padding: 8px 0 18px;
  }

  .app-page-header > p {
    min-height: 0;
    display: block;
    margin-top: 12px;
    padding: 0;
    border-left: 0;
