/* Reversible scroll motion: entering and leaving work in both directions. */

.app.home-motion-ready .home-reveal {
  opacity: 0;
  translate: 0 42px;
  scale: 0.975;
  filter: blur(10px);
  will-change: opacity, translate, scale, filter;
  transition:
    opacity 720ms cubic-bezier(0.22, 1, 0.36, 1),
    translate 760ms cubic-bezier(0.22, 1, 0.36, 1),
    scale 760ms cubic-bezier(0.22, 1, 0.36, 1),
    filter 620ms ease;
  transition-delay: var(--home-reveal-delay, 0ms);
}

.app.home-motion-ready .home-reveal.is-above {
  opacity: 0;
  translate: 0 -30px;
  scale: 0.985;
  filter: blur(7px);
}

.app.home-motion-ready .home-reveal.is-below {
  opacity: 0;
  translate: 0 42px;
  scale: 0.975;
  filter: blur(10px);
}

.app.home-motion-ready .home-reveal.is-visible {
  opacity: 1;
  translate: 0 0;
  scale: 1;
  filter: blur(0);
}

.app.home-motion-ready .category-card.home-reveal:nth-child(odd):not(.is-visible):not(.is-above) {
  translate: -18px 42px;
}

.app.home-motion-ready .category-card.home-reveal:nth-child(even):not(.is-visible):not(.is-above) {
  translate: 18px 42px;
}

