/* =========================================================
   IDEA HIRE — V10.2 UI REPAIR SEAL — 2026-09-25
   Final, reversible corrections for navigation, both templates,
   mobile layouts, chat media and the administration workspace.
========================================================= */

:root {
  --ih-release: 20260925-102;
}

/* Fast route change: keep the old frame solid and move the new one in.
   There is deliberately no opacity fade, blur or white loading frame. */

@keyframes ih-v102-route-in {
  from { transform: translateY(4px); }
  to { transform: translateY(0); }
}

::view-transition-group(root) {
  animation-duration: 160ms !important;
  animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1) !important;
}

::view-transition-old(root) {
  opacity: 1 !important;
  animation: none !important;
  mix-blend-mode: normal !important;
}

::view-transition-new(root) {
  opacity: 1 !important;
  animation: ih-v102-route-in 160ms cubic-bezier(0.22, 1, 0.36, 1) both !important;
  mix-blend-mode: normal !important;
}

::view-transition-image-pair(root) {
  isolation: isolate;
}

.page > main,
.account-page > main,
.app > main > section,
.privacy-center-shell,
.disputes-shell,
.admin-shell,
.chat-messages {
  animation: none !important;
  transform: none !important;
}

/* Home motion stays reversible but no longer blurs or scales entire layers. */

.app.home-motion-ready .home-reveal,
.app.home-motion-ready .home-reveal.is-below {
  opacity: 0;
  translate: 0 22px;
  scale: 1;
  filter: none !important;
  will-change: auto;
  transition:
    opacity 360ms ease,
    translate 430ms cubic-bezier(0.22, 1, 0.36, 1);
  transition-delay: min(var(--home-reveal-delay, 0ms), 90ms);
}

.app.home-motion-ready .home-reveal.is-above {
  opacity: 0;
  translate: 0 -16px;
  scale: 1;
  filter: none !important;
}

.app.home-motion-ready .home-reveal.is-visible {
  opacity: 1;
  translate: 0;
  scale: 1;
  filter: none !important;
}

.app.home-motion-ready .category-card.home-reveal:nth-child(n):not(.is-visible):not(.is-above) {
  translate: 0 22px;
}

.app.home-motion-ready .split-section.home-reveal .split-card {
  transition: transform 430ms cubic-bezier(0.22, 1, 0.36, 1), opacity 300ms ease;
}

.app.home-motion-ready .split-section.home-reveal:not(.is-visible) .split-card:first-child {
  opacity: 0.9;
  transform: translateX(-18px);
}

.app.home-motion-ready .split-section.home-reveal:not(.is-visible) .split-card:last-child {
  opacity: 0.9;
  transform: translateX(18px);
}

