  position: relative;
  z-index: 2;
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 26px;
}

.calendar-hero-stats article {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-width: 0;
  min-height: 78px;
  padding: 18px 21px;
  border: 1px solid var(--calendar-line);
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.54);
  backdrop-filter: blur(12px);
}

html[data-theme="dark"] .calendar-hero-stats article {
  background: rgba(10, 18, 28, 0.3);
}

html[data-template="classic"] .calendar-hero-stats article {
  background: var(--calendar-surface-soft);
  backdrop-filter: none;
}

.calendar-hero-stats span {
  min-width: 0;
  color: var(--calendar-copy);
  font-size: 11px;
  font-weight: 750;
  line-height: 1.35;
}

.calendar-hero-stats strong {
  margin-left: 16px;
  color: var(--calendar-ink);
  font-size: clamp(24px, 2.2vw, 36px);
  font-weight: 800;
  letter-spacing: -0.055em;
}

.calendar-hero-orbit {
  position: absolute;
  top: clamp(22px, 4vw, 58px);
  right: clamp(32px, 8vw, 132px);
  z-index: 1;
  width: clamp(120px, 16vw, 230px);
  aspect-ratio: 1;
  border: 1px solid rgba(35, 95, 168, 0.14);
  border-radius: 50%;
  animation: calendar-orbit-float 8s ease-in-out infinite;
  pointer-events: none;
}

.calendar-hero-orbit::before,
.calendar-hero-orbit::after {
  content: "";
  position: absolute;
  inset: 17%;
  border: 1px solid rgba(35, 95, 168, 0.12);
  border-radius: 50%;
}

.calendar-hero-orbit::after {
  inset: 35%;
  background: rgba(35, 95, 168, 0.07);
}

.calendar-hero-orbit span {
  position: absolute;
  width: 9px;
  height: 9px;
  border: 2px solid var(--calendar-surface);
  border-radius: 50%;
  background: var(--calendar-accent);
  box-shadow: 0 0 0 6px rgba(35, 95, 168, 0.1);
}

.calendar-hero-orbit span:nth-child(1) {
  top: 7%;
  left: 47%;
}

.calendar-hero-orbit span:nth-child(2) {
  right: 9%;
  bottom: 25%;
}

.calendar-hero-orbit span:nth-child(3) {
  bottom: 14%;
  left: 17%;
}

html[data-template="classic"] .calendar-hero-orbit {
  display: none;
}

.calendar-feedback {
  display: flex;
  align-items: center;
  gap: 12px;
  width: min(760px, 100%);
  margin: 18px auto 0;
  padding: 14px 18px;
  border: 1px solid rgba(171, 76, 73, 0.2);
  border-radius: 16px;
  background: rgba(255, 241, 240, 0.96);
  color: #8d3e3a;
  box-shadow: 0 16px 34px rgba(98, 48, 46, 0.08);
}

.calendar-feedback.is-success {
  border-color: rgba(36, 131, 103, 0.22);
  background: rgba(235, 248, 243, 0.98);
  color: #17684f;
}

html[data-theme="dark"] .calendar-feedback {
  background: rgba(92, 35, 34, 0.32);
  color: #ffb6b0;
}

html[data-theme="dark"] .calendar-feedback.is-success {
  background: rgba(25, 91, 72, 0.3);
  color: #91e1c8;
}

.calendar-feedback > span {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 28px;
  height: 28px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-size: 13px;
  font-weight: 850;
}

.calendar-feedback p {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.5;
}

.calendar-toolbar {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  align-items: center;
  gap: 18px;
  margin-top: 22px;
  padding: 17px 19px;
  border: 1px solid var(--calendar-line);
  border-radius: 22px;
  background: color-mix(in srgb, var(--calendar-surface) 90%, transparent);
  box-shadow: 0 14px 34px rgba(32, 58, 92, 0.06);
  backdrop-filter: blur(16px);
}

.calendar-month-navigation {
  display: grid;
  grid-template-columns: 43px minmax(180px, auto) 43px;
  align-items: center;
  gap: 12px;
}

.calendar-month-navigation > button,
.calendar-today-button {
  display: grid;
  place-items: center;
  min-width: 43px;
  min-height: 43px;
  border: 1px solid var(--calendar-line-strong);
  border-radius: 14px;
  background: var(--calendar-surface-soft);
  color: var(--calendar-ink);
  font: inherit;
  font-size: 18px;
  font-weight: 700;
  cursor: pointer;
  transition:
    border-color 180ms ease,
    background 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}

.calendar-month-navigation > button:hover,
.calendar-today-button:hover {
  border-color: var(--calendar-accent);
  background: var(--calendar-accent);
  color: #ffffff;
  transform: translateY(-1px);
}

html[data-template="classic"][data-theme="dark"] .calendar-month-navigation > button:hover,
html[data-template="classic"][data-theme="dark"] .calendar-today-button:hover {
  color: #111111;
}

.calendar-month-navigation > div {
  min-width: 0;
}

.calendar-month-navigation span {
  display: block;
  margin-bottom: 3px;
  color: var(--calendar-muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.calendar-month-navigation h2 {
  margin: 0;
  color: var(--calendar-ink);
  font-size: 20px;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.035em;
  text-transform: capitalize;
}

.calendar-today-button {
  display: inline-flex;
  min-width: 90px;
  padding: 0 17px;
  font-size: 11px;
  font-weight: 800;
}

.calendar-legend {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px 14px;
}

.calendar-legend > span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--calendar-copy);
  font-size: 10px;
  font-weight: 750;
  white-space: nowrap;
}

.calendar-legend i,
.calendar-event-chip i,
.calendar-agenda-marker {
  display: inline-block;
  flex: 0 0 auto;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--calendar-personal);
}

.calendar-legend .is-deadline i,
.calendar-event-chip.is-deadline i,
.calendar-agenda-item.is-deadline .calendar-agenda-marker {
  background: var(--calendar-deadline);
}

.calendar-legend .is-meeting i,
.calendar-event-chip.is-meeting i,
.calendar-agenda-item.is-meeting .calendar-agenda-marker {
  background: var(--calendar-meeting);
}

.calendar-legend .is-payment i,
.calendar-event-chip.is-payment i,
.calendar-agenda-item.is-payment .calendar-agenda-marker {
  background: var(--calendar-payment);
}

.calendar-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1.9fr) minmax(320px, 0.72fr);
  align-items: start;
  gap: 20px;
  margin-top: 20px;
}

.calendar-board,
.calendar-day-agenda,
.calendar-upcoming {
  border: 1px solid var(--calendar-line);
  background: var(--calendar-surface);
  box-shadow: 0 22px 52px rgba(29, 51, 83, 0.08);
}

.calendar-board {
  min-width: 0;
  padding: 14px;
  overflow: hidden;
  border-radius: 28px;
}

.calendar-weekdays,
.calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
}

.calendar-weekdays {
  gap: 6px;
  padding: 0 3px 10px;
}

.calendar-weekdays span {
  display: grid;
  place-items: center;
  min-height: 30px;
  color: var(--calendar-muted);
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.calendar-grid {
  gap: 6px;
  transform-origin: center top;
  animation: calendar-page-turn-next 520ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.calendar-grid.is-previous {
  animation-name: calendar-page-turn-previous;
}

.calendar-grid.is-today {
  animation-name: calendar-page-focus;
}

.calendar-day {
  position: relative;
  min-width: 0;
  min-height: clamp(98px, 10.2vw, 150px);
  padding: 8px;
  overflow: hidden;
  border: 1px solid var(--calendar-line);
  border-radius: 16px;
  background: var(--calendar-surface-soft);
  transition:
    border-color 180ms ease,
    background 180ms ease,
    transform 180ms ease,
    box-shadow 180ms ease;
}

.calendar-day:hover {
  z-index: 2;
  border-color: var(--calendar-line-strong);
  background: var(--calendar-surface);
  box-shadow: 0 14px 28px rgba(29, 53, 88, 0.09);
  transform: translateY(-2px);
}

.calendar-day.is-selected {
  border-color: var(--calendar-accent);
  box-shadow: inset 0 0 0 1px var(--calendar-accent);
}

.calendar-day.is-today {
  background:
    linear-gradient(145deg, var(--calendar-accent-soft), var(--calendar-surface));
}

.calendar-day.is-outside {
  opacity: 0.47;
}

.calendar-day-number {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-height: 31px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--calendar-ink);
  font: inherit;
  cursor: pointer;
}

.calendar-day-number > span {
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  border-radius: 10px;
  font-size: 11px;
  font-weight: 820;
}

.calendar-day.is-today .calendar-day-number > span {
  background: var(--calendar-accent);
  color: #ffffff;
}

html[data-template="classic"][data-theme="dark"] .calendar-day.is-today .calendar-day-number > span {
  color: #111111;
}

.calendar-day-number em {
  margin-right: 3px;
  color: var(--calendar-accent-deep);
  font-size: 8px;
  font-style: normal;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.calendar-day-events {
  display: grid;
  gap: 4px;
  margin-top: 6px;
}

.calendar-event-chip {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  min-width: 0;
  min-height: 25px;
  padding: 5px 7px;
  border: 0;
  border-radius: 8px;
  background: color-mix(in srgb, var(--calendar-personal) 10%, var(--calendar-surface));
  color: var(--calendar-ink);
  font: inherit;
  font-size: 8.5px;
  font-weight: 730;
  line-height: 1.15;
  text-align: left;
  cursor: pointer;
  transition: transform 160ms ease, filter 160ms ease;
}

.calendar-event-chip.is-deadline {
  background: color-mix(in srgb, var(--calendar-deadline) 11%, var(--calendar-surface));
}

.calendar-event-chip.is-meeting {
  background: color-mix(in srgb, var(--calendar-meeting) 11%, var(--calendar-surface));
}

.calendar-event-chip.is-payment {
  background: color-mix(in srgb, var(--calendar-payment) 11%, var(--calendar-surface));
}

.calendar-event-chip:hover {
  filter: brightness(0.97);
  transform: translateX(2px);
}

.calendar-event-chip.is-completed {
  opacity: 0.5;
  text-decoration: line-through;
}

.calendar-event-chip span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.calendar-more-events {
  justify-self: start;
  padding: 3px 7px;
  border: 0;
  background: transparent;
  color: var(--calendar-accent-deep);
  font: inherit;
  font-size: 9px;
  font-weight: 850;
  cursor: pointer;
}

.calendar-sidebar {
  display: grid;
  gap: 20px;
  min-width: 0;
}

.calendar-day-agenda,
.calendar-upcoming {
  padding: 22px;
  border-radius: 26px;
}

.calendar-sidebar-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
}

.calendar-sidebar-heading > div {
  min-width: 0;
}

.calendar-sidebar-heading span {
  display: block;
  margin-bottom: 6px;
  color: var(--calendar-accent-deep);
  font-size: 8.5px;
  font-weight: 850;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.calendar-sidebar-heading h2 {
  margin: 0;
  color: var(--calendar-ink);
  font-size: 18px;
  font-weight: 800;
  line-height: 1.3;
  letter-spacing: -0.035em;
  text-transform: capitalize;
}

.calendar-sidebar-heading > button {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 39px;
  height: 39px;
  border: 1px solid var(--calendar-accent);
  border-radius: 13px;
  background: var(--calendar-accent);
  color: #ffffff;
  font: inherit;
  font-size: 20px;
  cursor: pointer;
  transition: transform 180ms ease, background 180ms ease;
}

.calendar-sidebar-heading > button:hover {
  background: var(--calendar-accent-deep);
  transform: rotate(8deg) scale(1.04);
}

html[data-template="classic"][data-theme="dark"] .calendar-sidebar-heading > button {
  color: #111111;
}

.calendar-sidebar-heading.is-small h2 {
  font-size: 20px;
}

.calendar-empty-state {
  display: grid;
  justify-items: start;
  min-height: 230px;
  padding: 25px;
  border: 1px dashed var(--calendar-line-strong);
  border-radius: 20px;
  background: var(--calendar-surface-soft);
}

.calendar-empty-state > span {
  display: grid;
  place-items: center;
  width: 43px;
  height: 43px;
  margin-bottom: 25px;
  border: 1px solid var(--calendar-line-strong);
  border-radius: 14px;
  color: var(--calendar-accent-deep);
  font-size: 24px;
}

.calendar-empty-state strong {
  color: var(--calendar-ink);
  font-size: 17px;
  font-weight: 800;
}

.calendar-empty-state p {
  margin: 8px 0 19px;
  color: var(--calendar-copy);
  font-size: 11px;
  font-weight: 550;
  line-height: 1.55;
}

.calendar-empty-state button {
  min-height: 38px;
  padding: 9px 13px;
  border: 1px solid var(--calendar-line-strong);
  border-radius: 11px;
  background: var(--calendar-surface);
  color: var(--calendar-ink);
  font: inherit;
  font-size: 10px;
  font-weight: 800;
  cursor: pointer;
}

.calendar-agenda-list,
.calendar-upcoming-list {
  display: grid;
  gap: 9px;
}

.calendar-agenda-item {
  position: relative;
  display: grid;
  grid-template-columns: 9px minmax(0, 1fr);
  gap: 11px;
  min-width: 0;
  padding: 15px;
  border: 1px solid var(--calendar-line);
  border-radius: 17px;
  background: var(--calendar-surface-soft);
  transition: border-color 180ms ease, transform 180ms ease;
}

.calendar-agenda-item:hover {
  border-color: var(--calendar-line-strong);
  transform: translateY(-1px);
}

.calendar-agenda-marker {
  width: 9px;
  height: 9px;
  margin-top: 4px;
  box-shadow: 0 0 0 4px color-mix(in srgb, currentColor 8%, transparent);
}

.calendar-agenda-copy {
  min-width: 0;
}

.calendar-agenda-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--calendar-muted);
  font-size: 8px;
  font-weight: 850;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.calendar-agenda-meta em {
  padding: 3px 6px;
  border: 1px solid var(--calendar-line);
  border-radius: 999px;
  color: var(--calendar-accent-deep);
  font-size: 7px;
  font-style: normal;
  letter-spacing: 0.06em;
}

.calendar-agenda-copy > strong {
  display: block;
  margin-top: 5px;
  overflow-wrap: anywhere;
  color: var(--calendar-ink);
  font-size: 12px;
  font-weight: 800;
  line-height: 1.35;
}

.calendar-agenda-copy > time {
  display: block;
  margin-top: 5px;
  color: var(--calendar-accent-deep);
  font-size: 9.5px;
  font-weight: 750;
}

.calendar-agenda-copy > p {
  margin: 8px 0 0;
  overflow-wrap: anywhere;
  color: var(--calendar-copy);
  font-size: 10px;
  line-height: 1.5;
}

.calendar-email-state {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 9px;
  color: var(--calendar-payment);
  font-size: 8.5px;
  font-weight: 750;
}

.calendar-email-state svg {
  width: 13px;
  height: 13px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.calendar-agenda-actions {
  grid-column: 2;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 2px;
}

.calendar-agenda-actions button {
  min-height: 30px;
  padding: 6px 9px;
  border: 1px solid var(--calendar-line-strong);
  border-radius: 9px;
  background: var(--calendar-surface);
  color: var(--calendar-copy);
  font: inherit;
  font-size: 8.5px;
  font-weight: 800;
  cursor: pointer;
  transition: border-color 160ms ease, color 160ms ease;
}

.calendar-agenda-actions button:hover {
  border-color: var(--calendar-accent);
  color: var(--calendar-accent-deep);
}

.calendar-agenda-item.is-completed {
  opacity: 0.57;
}

.calendar-agenda-item.is-completed .calendar-agenda-copy > strong {
  text-decoration: line-through;
}

.calendar-agenda-item.is-compact {
  grid-template-columns: 7px minmax(0, 1fr);
  padding: 12px;
}

.calendar-agenda-item.is-compact .calendar-agenda-marker {
  width: 7px;
  height: 7px;
}

.calendar-agenda-item.is-compact .calendar-agenda-copy > strong {
  font-size: 10.5px;
}

.calendar-upcoming-empty {
  margin: 0;
  padding: 18px;
  border: 1px dashed var(--calendar-line);
  border-radius: 14px;
  color: var(--calendar-copy);
  font-size: 10px;
  line-height: 1.5;
}

.calendar-dialog-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1200;
  display: grid;
  place-items: center;
  padding: 24px;
  overflow: auto;
  background: rgba(5, 12, 22, 0.62);
  backdrop-filter: blur(14px);
  animation: calendar-backdrop-in 220ms ease both;
}

.calendar-dialog {
  width: min(760px, 100%);
  max-height: calc(100vh - 48px);
  overflow: auto;
  border: 1px solid var(--calendar-line-strong);
  border-radius: 28px;
  background: var(--calendar-surface);
  color: var(--calendar-ink);
  box-shadow: 0 42px 110px rgba(0, 0, 0, 0.32);
  animation: calendar-dialog-fold-in 520ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.calendar-dialog-heading {
  position: sticky;
  top: 0;
  z-index: 4;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 25px 27px 21px;
  border-bottom: 0;
  background: color-mix(in srgb, var(--calendar-surface) 92%, transparent);
  backdrop-filter: blur(18px);
}

.calendar-dialog-heading span {
  color: var(--calendar-accent-deep);
  font-size: 8px;
  font-weight: 850;
  letter-spacing: 0.15em;
}

.calendar-dialog-heading h2 {
  margin: 7px 0 0;
  color: var(--calendar-ink);
  font-size: 27px;
  font-weight: 800;
  letter-spacing: -0.045em;
}

.calendar-dialog-heading > button {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 40px;
  height: 40px;
  border: 1px solid var(--calendar-line-strong);
  border-radius: 13px;
  background: var(--calendar-surface-soft);
  color: var(--calendar-ink);
  font: inherit;
  font-size: 24px;
  font-weight: 400;
  cursor: pointer;
}

.calendar-form {
  display: grid;
  gap: 19px;
  padding: 25px 27px 28px;
}

.calendar-type-picker {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

.calendar-type-picker legend,
.calendar-field > span {
  display: block;
  margin-bottom: 8px;
  color: var(--calendar-copy);
  font-size: 10px;
  font-weight: 800;
}

.calendar-type-picker > div {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.calendar-type-picker label {
  position: relative;
  display: grid;
  grid-template-columns: 8px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  min-height: 48px;
  padding: 10px;
  border: 1px solid var(--calendar-line);
  border-radius: 13px;
  background: var(--calendar-surface-soft);
  color: var(--calendar-copy);
  cursor: pointer;
  transition: border-color 170ms ease, background 170ms ease, transform 170ms ease;
}

.calendar-type-picker label:hover {
  border-color: var(--calendar-line-strong);
  transform: translateY(-1px);
}

.calendar-type-picker label.is-selected {
  border-color: var(--calendar-accent);
  background: var(--calendar-accent-soft);
  color: var(--calendar-ink);
  box-shadow: inset 0 0 0 1px var(--calendar-accent);
}

.calendar-type-picker input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.calendar-type-picker i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--calendar-personal);
}

.calendar-type-picker .is-deadline i {
  background: var(--calendar-deadline);
}

.calendar-type-picker .is-meeting i {
  background: var(--calendar-meeting);
}

.calendar-type-picker .is-payment i {
  background: var(--calendar-payment);
}

.calendar-type-picker label span {
  min-width: 0;
  font-size: 9px;
  font-weight: 780;
  line-height: 1.25;
}

.calendar-form-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.calendar-field {
  position: relative;
  display: block;
