@keyframes calendar-hero-reveal {
  0% {
    opacity: 0;
    clip-path: inset(0 100% 0 0 round 36px);
    transform: translateY(16px);
  }
  100% {
    opacity: 1;
    clip-path: inset(0 0 0 0 round 36px);
    transform: translateY(0);
  }
}

@keyframes calendar-light-sweep {
  to {
    transform: rotate(360deg);
  }
}

@keyframes calendar-orbit-float {
  0%,
  100% {
    transform: translate3d(0, 0, 0) rotate(0deg);
  }
  50% {
    transform: translate3d(0, 9px, 0) rotate(6deg);
  }
}

@keyframes calendar-page-turn-next {
  0% {
    opacity: 0;
    clip-path: inset(0 0 0 18% round 18px);
    transform: perspective(1000px) rotateY(-3deg) translateX(18px);
  }
  100% {
    opacity: 1;
    clip-path: inset(0 0 0 0 round 18px);
    transform: perspective(1000px) rotateY(0) translateX(0);
  }
}

@keyframes calendar-page-turn-previous {
  0% {
    opacity: 0;
    clip-path: inset(0 18% 0 0 round 18px);
    transform: perspective(1000px) rotateY(3deg) translateX(-18px);
  }
  100% {
    opacity: 1;
    clip-path: inset(0 0 0 0 round 18px);
    transform: perspective(1000px) rotateY(0) translateX(0);
  }
}

@keyframes calendar-page-focus {
  0% {
    opacity: 0;
    transform: scale(0.985);
    filter: blur(5px);
  }
  100% {
    opacity: 1;
    transform: scale(1);
    filter: blur(0);
  }
}

@keyframes calendar-backdrop-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes calendar-dialog-fold-in {
  0% {
    opacity: 0;
    transform: perspective(1200px) rotateX(-7deg) translateY(30px) scale(0.97);
    transform-origin: center top;
  }
  100% {
    opacity: 1;
    transform: perspective(1200px) rotateX(0) translateY(0) scale(1);
  }
}

