/* A 12-second story: arrival, sitting, making the work, completion. */
.ih5-scene-shadow { fill: var(--ih5-scene-ink); opacity: .07; }
.ih5-scene-person { animation: ih5-person-arrive 12s cubic-bezier(.45,0,.25,1) infinite; transform-origin: 145px 220px; }
.ih5-person-head { animation: ih5-person-think 12s ease infinite; transform-origin: 149px 107px; }
.ih5-person-arm { animation: ih5-person-type 12s linear infinite; transform-origin: 148px 132px; }
.ih5-scene-code { animation: ih5-code-stage 12s linear infinite; }
.ih5-code-line { stroke-dasharray: 44; stroke-dashoffset: 44; animation: ih5-code-write 12s ease infinite; }
.ih5-code-line.is-two { animation-delay: .6s; }
.ih5-code-line.is-three { animation-delay: 1.2s; }
.ih5-code-line.is-four { animation-delay: 1.8s; }
.ih5-scene-done { opacity: 0; transform-origin: 261px 118px; animation: ih5-work-complete 12s ease infinite; }
.ih5-scene-pixels { transform-origin: 210px 130px; animation: ih5-story-pixels 12s ease infinite; }
.ih5-story-caption .is-idea { animation: ih5-caption-idea 12s linear infinite; }
.ih5-story-caption .is-work { animation: ih5-caption-work 12s linear infinite; }
.ih5-story-caption .is-done { animation: ih5-caption-done 12s linear infinite; }
.ih5-story[data-paused="true"] * { animation-play-state: paused !important; }
@keyframes ih5-person-arrive { 0%,3% { transform: translate(-64px,-17px); opacity: 0; } 13% { transform: translate(0,-12px); opacity: 1; } 21%,92% { transform: translate(0,0); opacity: 1; } 100% { transform: translate(0,0); opacity: 0; } }
@keyframes ih5-person-think { 0%,20%,70%,100% { transform: rotate(0); } 26%,62% { transform: rotate(6deg); } 80%,88% { transform: rotate(-5deg); } }
@keyframes ih5-person-type { 0%,20%,70%,100% { transform: rotate(0); } 24%,32%,40%,48%,56%,64% { transform: rotate(2deg); } 28%,36%,44%,52%,60%,68% { transform: rotate(-2deg); } }
@keyframes ih5-code-write { 0%,20% { stroke-dashoffset: 44; } 38%,94% { stroke-dashoffset: 0; } 100% { stroke-dashoffset: 44; } }
@keyframes ih5-code-stage { 0%,20%,76%,100% { opacity: 0; } 24%,70% { opacity: 1; } }
@keyframes ih5-work-complete { 0%,72%,100% { opacity: 0; transform: scale(.7); } 79%,94% { opacity: 1; transform: scale(1); } }
@keyframes ih5-story-pixels { 0%,10%,100% { opacity: 0; transform: scale(.8); } 20%,75% { opacity: .5; transform: scale(1); } 85% { opacity: .9; transform: scale(1.1); } 96% { opacity: 0; transform: scale(1.2); } }
@keyframes ih5-caption-idea { 0%,19% { opacity: 1; } 24%,100% { opacity: 0; } }
@keyframes ih5-caption-work { 0%,19%,76%,100% { opacity: 0; } 25%,70% { opacity: 1; } }
@keyframes ih5-caption-done { 0%,72%,100% { opacity: 0; } 79%,94% { opacity: 1; } }

