/* IdeaHire P13 — safe scrolling background and a readable messenger. */
:root {
  --ih13-start-a: #e8effc;
  --ih13-start-b: #f5f7fc;
  --ih13-end-a: #f0eaf9;
  --ih13-end-b: #e7f2f2;
}
html[data-theme="dark"] {
  --ih13-start-a: #111e34;
  --ih13-start-b: #0e1727;
  --ih13-end-a: #201c35;
  --ih13-end-b: #11262b;
}
html[data-template="classic"] {
  --ih13-start-a: #eeeee9;
  --ih13-start-b: #f8f8f5;
  --ih13-end-a: #e8e8e5;
  --ih13-end-b: #f3f1eb;
}
html[data-template="classic"][data-theme="dark"] {
  --ih13-start-a: #1b1c1e;
  --ih13-start-b: #121315;
  --ih13-end-a: #232223;
  --ih13-end-b: #171a1c;
}

/* No positioning or z-index changes on content, menus or notifications. */
html:root body { isolation: isolate; }
html:root body .ih13-background {
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  overflow: hidden;
  contain: strict;
  background: var(--ih7-bg, #f5f7fc);
  --ih13-blend: 0;
}
html:root body .ih13-background > div {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.ih13-background-start {
  background: radial-gradient(ellipse at 12% 0%, var(--ih13-start-a), transparent 72%),
    linear-gradient(145deg, var(--ih13-start-b), var(--ih13-start-a));
}
.ih13-background-end {
  background: radial-gradient(ellipse at 85% 22%, var(--ih13-end-a), transparent 72%),
    linear-gradient(155deg, var(--ih13-end-b), var(--ih13-end-a));
  opacity: var(--ih13-blend);
  transition: opacity 280ms linear;
}
html:root body #root#root#root :is(.app, .page, .account-page) {
  background-color: transparent !important;
  background-image: none !important;
